window.listeningBank = {"version":1,"sets":[{"id":"2021-06-1","title":"2021年6月 六级第1套（含 Day 1 必练 Q1–8）","year":"2021.06","exam":"六级 CET-6","totalQuestions":25,"audioMode":"sliced","sections":[{"id":"2021-06-1-s1","section":"Section A","title":"Conversation 1 · 离职访谈（Day 1 必练） (Q1–4)","qRange":[1,4],"audio":"audio/listening/202106_s1.mp3","durationSec":184.5,"segments":[{"t0":0.0,"t1":0.83,"text":"with a single line through the centre."},{"t0":0.83,"t1":2.83,"text":"Conversation 1"},{"t0":2.83,"t1":5.33,"text":"It's my last day at work tomorrow."},{"t0":5.33,"t1":7.83,"text":"I start my new job in two weeks."},{"t0":7.83,"t1":12.33,"text":"My human resources manager wants to conduct an interview with me before I leave."},{"t0":12.33,"t1":16.33,"text":"Ah, an exit interview. Are you looking forward to it?"},{"t0":16.33,"t1":18.83,"text":"I'm not sure how I feel about it."},{"t0":18.83,"t1":22.83,"text":"I resigned because I've been unhappy at that company for a long time."},{"t0":22.83,"t1":26.33,"text":"But I'm not sure if I should tell them how I really feel."},{"t0":26.33,"t1":29.83,"text":"To my way of thinking, there are two main potential benefits"},{"t0":29.83,"t1":33.83,"text":"that come from unleashing an agitated stream of truth"},{"t0":33.83,"t1":35.83,"text":"during an exit interview."},{"t0":35.83,"t1":37.83,"text":"The first is release."},{"t0":37.83,"t1":41.83,"text":"Unburdening yourself of frustration and perhaps even anger"},{"t0":41.83,"t1":44.33,"text":"by someone who isn't a friend or close colleague"},{"t0":44.33,"t1":46.33,"text":"can be wonderfully freeing."},{"t0":46.33,"t1":48.33,"text":"And let me guess."},{"t0":48.33,"t1":51.33,"text":"The second is that the criticism will, theoretically,"},{"t0":51.33,"t1":54.33,"text":"help the organisation I'm leaving to improve,"},{"t0":54.33,"t1":56.33,"text":"making sure employees of the future"},{"t0":56.33,"t1":59.33,"text":"are less likely to encounter what I did?"},{"t0":59.33,"t1":60.33,"text":"That's right."},{"t0":60.33,"t1":63.33,"text":"But the problem with the company improvement part"},{"t0":63.33,"t1":65.33,"text":"is that very often it doesn't happen."},{"t0":65.33,"t1":68.33,"text":"An exit interview is supposed to be private,"},{"t0":68.33,"t1":70.33,"text":"but often isn't."},{"t0":70.83,"t1":72.83,"text":"The information gained from these interviews"},{"t0":72.83,"t1":74.83,"text":"is often not confidential"},{"t0":74.83,"t1":78.83,"text":"and the information is used as dirt against another manager"},{"t0":78.83,"t1":81.83,"text":"or can be traded among senior managers."},{"t0":81.83,"t1":83.83,"text":"Now, you've got me rethinking"},{"t0":83.83,"t1":85.83,"text":"what I'll disclose in the interview."},{"t0":85.83,"t1":88.83,"text":"There is always the chance that it could affect my reputation"},{"t0":88.83,"t1":91.83,"text":"and my ability to network in the industry."},{"t0":91.83,"t1":94.83,"text":"It is a pretty small industry, after all."},{"t0":94.83,"t1":96.83,"text":"Anything you initially gain"},{"t0":96.83,"t1":99.83,"text":"from the instant satisfaction of telling it like it is"},{"t0":100.33,"t1":102.33,"text":"you might lose down the track"},{"t0":102.33,"t1":104.33,"text":"by injuring your future career prospects."},{"t0":104.33,"t1":106.33,"text":"Right."},{"t0":106.33,"t1":108.33,"text":"Perhaps I would be better getting things off my chest"},{"t0":108.33,"t1":111.33,"text":"by going to one of those rate-your-employer websites."},{"t0":111.33,"t1":113.33,"text":"You could."},{"t0":113.33,"t1":115.33,"text":"And don't do the interview at all."},{"t0":115.33,"t1":117.33,"text":"Exit interviews are not mandatory."},{"t0":117.33,"t1":119.33,"text":"Questions one to four"},{"t0":119.33,"t1":122.33,"text":"are based on the conversation you have just heard."},{"t0":122.33,"t1":124.33,"text":"Question one."},{"t0":124.33,"t1":139.97,"text":"What do we learn about the man from the conversation?"},{"t0":139.97,"t1":141.97,"text":"Question two."},{"t0":141.97,"t1":143.97,"text":"What does the woman think about the information"},{"t0":143.97,"t1":145.97,"text":"gained from an exit interview?"},{"t0":145.97,"t1":160.96,"text":"Question three."},{"t0":160.96,"t1":163.96,"text":"Why does the man want to rethink"},{"t0":163.96,"t1":166.96,"text":"what he will say in the coming exit interview?"},{"t0":166.96,"t1":181.82,"text":"Question four."},{"t0":181.82,"t1":184.5,"text":"What does the man think he had better do?"}],"questions":[{"no":1,"type":"细节/推断题","prompt":"Question 1（请对照听稿录音）","options":[{"label":"A","text":"He is going to leave his present job."},{"label":"B","text":"He is going to attend a job interview."},{"label":"C","text":"He will meet his new manager in two weeks."},{"label":"D","text":"He will tell the management how he really feels."}],"answer":"A","evidence":"即将离职","explanation":"答案 A。录音核心依据：即将离职。"},{"no":2,"type":"细节/推断题","prompt":"Question 2（请对照听稿录音）","options":[{"label":"A","text":"It should be carefully analyzed."},{"label":"B","text":"It should be kept private."},{"label":"C","text":"It can be quite useful to senior managers."},{"label":"D","text":"It can improve interviewees' job prospects."}],"answer":"B","evidence":"离职访谈应保密","explanation":"答案 B。录音核心依据：离职访谈应保密。"},{"no":3,"type":"细节/推断题","prompt":"Question 3（请对照听稿录音）","options":[{"label":"A","text":"It may do harm to his fellow employees."},{"label":"B","text":"It may displease his immediate superiors."},{"label":"C","text":"It may adversely affect his future career prospects."},{"label":"D","text":"It may leave a negative impression on the interviewer."}],"answer":"C","evidence":"损害今后职业与人脉","explanation":"答案 C。录音核心依据：损害今后职业与人脉。"},{"no":4,"type":"细节/推断题","prompt":"Question 4（请对照听稿录音）","options":[{"label":"A","text":"Pour out his frustrations on a rate-your-employer website."},{"label":"B","text":"Network with his close friends to find a better employer."},{"label":"C","text":"Do some practice for the exit interview."},{"label":"D","text":"Prepare a comprehensive exit report."}],"answer":"A","evidence":"雇主评分网站倾诉","explanation":"答案 A。录音核心依据：雇主评分网站倾诉。"}]},{"id":"2021-06-1-s2","section":"Section A","title":"Conversation 2 · 植物学家纪录片（Day 1 必练） (Q5–8)","qRange":[5,8],"audio":"audio/listening/202106_s2.mp3","durationSec":219.5,"segments":[{"t0":0.0,"t1":0.32,"text":"What does the man think he had better do?"},{"t0":0.32,"t1":15.16,"text":"Conversation two."},{"t0":15.16,"t1":18.16,"text":"Today, I'm talking to the renowned botanist,"},{"t0":18.16,"t1":20.16,"text":"Jane Forster."},{"t0":20.16,"t1":24.16,"text":"Thank you for inviting me to join you on the show, Henry."},{"t0":24.16,"t1":27.16,"text":"Recently, Jane, you've become quite a celebrity"},{"t0":27.16,"t1":30.16,"text":"since the release of your latest documentary."},{"t0":30.16,"t1":33.16,"text":"Can you tell us a little about it?"},{"t0":33.16,"t1":35.16,"text":"Well, it follows my expedition"},{"t0":35.16,"t1":37.16,"text":"to study the vegetation"},{"t0":37.16,"t1":39.16,"text":"indigenous to the rainforest"},{"t0":39.16,"t1":42.16,"text":"in equatorial areas of Southeast Asia."},{"t0":42.16,"t1":44.16,"text":"You certainly get to travel"},{"t0":44.16,"t1":46.16,"text":"to some very exotic locations."},{"t0":46.16,"t1":49.16,"text":"It was far from glamorous, to be honest."},{"t0":49.16,"t1":53.16,"text":"The area we visited was accessible only by canoe"},{"t0":53.16,"t1":55.16,"text":"and the living conditions in the hut"},{"t0":55.16,"t1":57.16,"text":"were primitive to say the least."},{"t0":57.16,"t1":59.16,"text":"There was no electricity"},{"t0":59.16,"t1":62.16,"text":"and our water supply was a nearby stream."},{"t0":62.16,"t1":65.16,"text":"How were the weather conditions while you were there?"},{"t0":65.16,"t1":68.16,"text":"The weather was not conducive to our work at all"},{"t0":68.16,"t1":71.16,"text":"since the humidity was almost unbearable."},{"t0":71.16,"t1":74.16,"text":"At midday, we stayed in the hut and did nothing."},{"t0":74.16,"t1":77.16,"text":"It was too humid to either work or sleep."},{"t0":77.16,"t1":80.16,"text":"How long did your team spend in the jungle?"},{"t0":80.16,"t1":83.16,"text":"Originally, we planned to be there for a month"},{"t0":83.16,"t1":86.16,"text":"but in the end we stayed for only two weeks."},{"t0":86.16,"t1":89.16,"text":"Why did you cut the expedition short?"},{"t0":89.16,"t1":91.16,"text":"Halfway through the trip,"},{"t0":91.16,"t1":93.16,"text":"we received news that a hurricane was approaching"},{"t0":93.16,"t1":96.16,"text":"and we had to evacuate at very short notice."},{"t0":96.16,"t1":99.16,"text":"That sounds like a fascinating anecdote."},{"t0":99.16,"t1":101.16,"text":"It was frightening."},{"t0":101.16,"t1":105.16,"text":"The fastest evacuation route was through river rapids."},{"t0":105.16,"t1":108.16,"text":"We had to navigate them carrying all of our equipment."},{"t0":108.16,"t1":111.16,"text":"So overall, was the journey unsuccessful?"},{"t0":111.16,"t1":113.16,"text":"Absolutely not."},{"t0":113.16,"t1":117.16,"text":"We gathered a massive amount of data about the local plant life."},{"t0":117.16,"t1":120.16,"text":"Why do you put up with such adverse conditions?"},{"t0":120.16,"t1":123.16,"text":"Botany is an obsession for me."},{"t0":123.16,"t1":127.16,"text":"Many of the destinations I visit have stunning scenery"},{"t0":127.16,"t1":131.16,"text":"and I get to meet a variety of people from all over the world."},{"t0":131.16,"t1":134.16,"text":"So where will your next destination be?"},{"t0":134.16,"t1":136.16,"text":"I haven't decided yet."},{"t0":136.16,"t1":140.16,"text":"Then we can leave it for another occasion. Thanks."},{"t0":140.16,"t1":145.16,"text":"Questions 5 to 8 are based on the conversation you have just heard."},{"t0":145.16,"t1":147.16,"text":"Question 5"},{"t0":147.16,"t1":150.16,"text":"What does the man want Jane Forrester to talk about?"},{"t0":150.16,"t1":165.02,"text":"Question 6"},{"t0":165.02,"t1":170.02,"text":"Why does the woman describe her experience as far from glamorous?"},{"t0":170.02,"t1":185.08,"text":"Question 7"},{"t0":185.08,"t1":189.08,"text":"Why did the woman and those who went with her end their trip halfway?"},{"t0":189.08,"t1":204.04,"text":"Question 8"},{"t0":204.04,"t1":219.5,"text":"What does the woman think of the journey?"}],"questions":[{"no":5,"type":"细节/推断题","prompt":"What does the man want Jane Forrester to talk about?","options":[{"label":"A","text":"Her career as a botanist."},{"label":"B","text":"Her latest documentary."},{"label":"C","text":"Her month-long expedition."},{"label":"D","text":"Her unsuccessful journey."}],"answer":"B","evidence":"最新纪录片","explanation":"答案 B。录音核心依据：最新纪录片。"},{"no":6,"type":"细节/推断题","prompt":"Why does the woman describe her experience as far from glamorous?","options":[{"label":"A","text":"She was caught in a hurricane."},{"label":"B","text":"She had to live like a vegetarian."},{"label":"C","text":"She suffered from water shortage."},{"label":"D","text":"She had to endure many hardships."}],"answer":"D","evidence":"经历艰苦","explanation":"答案 D。录音核心依据：经历艰苦。"},{"no":7,"type":"细节/推断题","prompt":"Why did the woman and those who went with her end their trip halfway?","options":[{"label":"A","text":"They could no longer bear the humidity."},{"label":"B","text":"They had no more food in the canoe."},{"label":"C","text":"A flood was approaching."},{"label":"D","text":"A hurricane was coming."}],"answer":"D","evidence":"飓风将至","explanation":"答案 D。录音核心依据：飓风将至。"},{"no":8,"type":"细节/推断题","prompt":"What does the woman think of the journey?","options":[{"label":"A","text":","},{"label":"B","text":","},{"label":"C","text":"and"},{"label":"D","text":". Then mark the corresponding letter on Answer Sheet 1 with a single line through the centre."}],"answer":"C","evidence":"收集大量植物数据、成果丰硕","explanation":"答案 C。录音核心依据：收集大量植物数据、成果丰硕。"}]},{"id":"2021-06-1-s3","section":"Section B","title":"Passage 1 · 科学术语与科普 (Q9–11)","qRange":[9,11],"audio":"audio/listening/202106_s3.mp3","durationSec":181.0,"segments":[{"t0":0.0,"t1":0.74,"text":"with a single line through the centre."},{"t0":0.74,"t1":2.74,"text":"Passage 1"},{"t0":2.74,"t1":7.74,"text":"Scientists often use specialised jargon terms while communicating with laymen."},{"t0":7.74,"t1":12.74,"text":"Most of them don't realise the harmful effects of this practice."},{"t0":12.74,"t1":15.74,"text":"In a new study people exposed to jargon"},{"t0":15.74,"t1":18.74,"text":"when reading about subjects like autonomous vehicles"},{"t0":18.74,"t1":22.74,"text":"and surgical robots later said they were less interested in science"},{"t0":22.74,"t1":25.74,"text":"than others who read about the same topics"},{"t0":25.74,"t1":28.74,"text":"but without the use of specialised terms."},{"t0":28.74,"t1":31.74,"text":"They also felt less informed about science"},{"t0":31.74,"t1":35.74,"text":"and less qualified to discuss science topics."},{"t0":35.74,"t1":38.74,"text":"It's noteworthy that it made no difference"},{"t0":38.74,"t1":41.74,"text":"if the jargon terms were defined in the text."},{"t0":41.74,"t1":44.74,"text":"Even when the terms were defined"},{"t0":44.74,"t1":47.74,"text":"readers still felt the same lack of engagement"},{"t0":47.74,"t1":51.74,"text":"as readers who read jargon that wasn't explained."},{"t0":51.74,"t1":56.74,"text":"The problem is that the mere presence of jargon"},{"t0":56.74,"t1":59.74,"text":"sends a discouraging message to readers."},{"t0":59.74,"t1":62.74,"text":"Hilary Schulman, the author of the study,"},{"t0":62.74,"t1":66.74,"text":"asserts that specialised words are a signal."},{"t0":66.74,"t1":71.74,"text":"Jargon tells people that the message isn't for them."},{"t0":71.74,"t1":75.74,"text":"There's an even darker side to how people react to jargon."},{"t0":75.74,"t1":78.74,"text":"In another study researchers found that"},{"t0":78.74,"t1":81.74,"text":"reading scientific articles containing jargon"},{"t0":81.74,"t1":85.74,"text":"led people to doubt the actual science."},{"t0":85.74,"t1":90.74,"text":"They found the opposite when a text is easier to read."},{"t0":90.74,"t1":94.74,"text":"Then people are more persuaded."},{"t0":94.74,"t1":97.74,"text":"Thus it's important to communicate clearly"},{"t0":97.74,"t1":101.74,"text":"when talking about complex science subjects."},{"t0":101.74,"t1":105.74,"text":"This is especially true with issues related to public health."},{"t0":106.74,"t1":108.74,"text":"Like the safety of new medications"},{"t0":108.74,"t1":111.74,"text":"and the benefits of vaccines."},{"t0":111.74,"t1":114.74,"text":"Schulman concedes that the use of jargon"},{"t0":114.74,"t1":118.74,"text":"is appropriate with scientific audiences."},{"t0":118.74,"t1":122.74,"text":"But scientists who want to communicate with the general public"},{"t0":122.74,"t1":124.74,"text":"need to modify their language."},{"t0":124.74,"t1":127.74,"text":"They need to eliminate jargon."},{"t0":127.74,"t1":132.74,"text":"Questions 9 to 11 are based on the passage you have just heard."},{"t0":132.74,"t1":135.74,"text":"Question 9, what does the passage say"},{"t0":135.74,"t1":139.74,"text":"about the use of jargon terms by experts?"},{"t0":139.74,"t1":155.57,"text":"Question 10, what do researchers find"},{"t0":155.57,"t1":160.57,"text":"about people reading scientific articles containing jargon terms?"},{"t0":160.57,"t1":178.44,"text":"Question 11, what does Schulman suggest scientists do"},{"t0":178.44,"t1":181.0,"text":"when communicating with the general public?"}],"questions":[{"no":9,"type":"细节/推断题","prompt":"Question 9（请对照听稿录音）","options":[{"label":"A","text":"It ensures the accuracy of their arguments."},{"label":"B","text":"It diminishes laymen's interest in science."},{"label":"C","text":"It hurts laymen's dignity and self-esteem."},{"label":"D","text":"It makes their expressions more explicit."}],"answer":"B","evidence":"术语降低兴趣","explanation":"答案 B。录音核心依据：术语降低兴趣。"},{"no":10,"type":"细节/推断题","prompt":"Question 10（请对照听稿录音）","options":[{"label":"A","text":"They will see the complexity of science."},{"label":"B","text":"They feel great respect towards scientists."},{"label":"C","text":"They tend to disbelieve the actual science."},{"label":"D","text":"They can learn to communicate with scientists."}],"answer":"C","evidence":"术语引起对科学的怀疑","explanation":"答案 C。录音核心依据：术语引起对科学的怀疑。"},{"no":11,"type":"细节/推断题","prompt":"Question 11（请对照听稿录音）","options":[{"label":"A","text":"Explain all the jargon terms."},{"label":"B","text":"Do away with jargon terms."},{"label":"C","text":"Find appropriate topics."},{"label":"D","text":"Stimulate their interest."}],"answer":"B","evidence":"面向公众去掉术语","explanation":"答案 B。录音核心依据：面向公众去掉术语。"}]},{"id":"2021-06-1-s4","section":"Section B","title":"Passage 2 · 得州石油与钻井 (Q12–15)","qRange":[12,15],"audio":"audio/listening/202106_s4.mp3","durationSec":201.5,"segments":[{"t0":0.0,"t1":0.44,"text":"when communicating with the general public?"},{"t0":0.44,"t1":18.52,"text":"Passage 2, at the beginning of the 20th century"},{"t0":18.52,"t1":22.52,"text":"on the Gulf Coast in the US state of Texas"},{"t0":22.52,"t1":26.52,"text":"there was a hill where gas leakage was so noticeable"},{"t0":26.52,"t1":30.52,"text":"that schoolboys would sometimes set the hill on fire."},{"t0":30.52,"t1":34.52,"text":"Patio Higgins, a disreputable local businessman"},{"t0":34.52,"t1":38.52,"text":"became convinced that there was oil below the gassy hill."},{"t0":38.52,"t1":41.52,"text":"Oil wells weren't drilled back then."},{"t0":41.52,"t1":44.52,"text":"They were essentially dug."},{"t0":44.52,"t1":47.52,"text":"The sand under the hill defeated several attempts"},{"t0":47.52,"t1":50.52,"text":"by Higgins' workers to make a proper hole."},{"t0":50.52,"t1":53.52,"text":"Higgins had forecast oil at 1,000 feet,"},{"t0":53.52,"t1":56.52,"text":"a totally made-up figure."},{"t0":56.52,"t1":59.52,"text":"Higgins subsequently hired a mining engineer,"},{"t0":59.52,"t1":61.52,"text":"Captain Anthony Lucas."},{"t0":61.52,"t1":64.52,"text":"After encountering several setbacks,"},{"t0":64.52,"t1":67.52,"text":"Captain Lucas decided to use a drill"},{"t0":67.52,"t1":71.52,"text":"and his innovations created the modern oil drilling industry."},{"t0":71.52,"t1":75.52,"text":"In January 1901, at 1,020 feet,"},{"t0":75.52,"t1":79.52,"text":"almost precisely the depth predicted by Higgins' wild guess,"},{"t0":79.52,"t1":83.52,"text":"the well roared and suddenly ejected mud"},{"t0":83.52,"t1":86.52,"text":"and six tons of drilling pipe out of the ground,"},{"t0":86.52,"t1":89.52,"text":"terrifying those present."},{"t0":89.52,"t1":92.52,"text":"For the next nine days until the well was capped,"},{"t0":92.52,"t1":97.52,"text":"the well poured out more oil than all the wells in America combined."},{"t0":97.52,"t1":101.52,"text":"In those days, Texas was almost entirely rural,"},{"t0":101.52,"t1":104.52,"text":"with no large cities and practically no industry,"},{"t0":105.52,"t1":108.52,"text":"cotton and beef were the foundation of the economy."},{"t0":108.52,"t1":111.52,"text":"Higgins' well changed that."},{"t0":111.52,"t1":114.52,"text":"The boom made some prospectors millionaires,"},{"t0":114.52,"t1":117.52,"text":"but the sudden surplus of petroleum"},{"t0":117.52,"t1":120.52,"text":"was not entirely a blessing for Texas."},{"t0":120.52,"t1":123.52,"text":"In the 1930s, prices crashed,"},{"t0":123.52,"t1":126.52,"text":"to the point that in some parts of the country,"},{"t0":126.52,"t1":128.52,"text":"oil was cheaper than water."},{"t0":128.52,"t1":130.52,"text":"That would become a familiar pattern"},{"t0":130.52,"t1":133.52,"text":"of the boom or bust Texas economy."},{"t0":134.52,"t1":138.52,"text":"Questions 12-15 are based on the passage you have just heard."},{"t0":138.52,"t1":140.52,"text":"Question 12."},{"t0":140.52,"t1":145.52,"text":"What did Texas businessman Petilio Higgins believe?"},{"t0":145.52,"t1":160.32,"text":"Question 13."},{"t0":160.32,"t1":163.32,"text":"What prevented Higgins' workers from digging a proper hole"},{"t0":163.32,"t1":178.12,"text":"to get the oil?"},{"t0":178.12,"t1":179.12,"text":"Question 14."},{"t0":179.12,"t1":184.12,"text":"What does the passage say about Captain Lucas' drilling method?"},{"t0":184.12,"t1":198.92,"text":"Question 15."},{"t0":198.92,"t1":201.5,"text":"What do we learn about Texas' oil industry boom?"}],"questions":[{"no":12,"type":"细节/推断题","prompt":"What did Texas businessman Petilio Higgins believe?","options":[{"label":"A","text":"There were oil deposits below a local gassy hill."},{"label":"B","text":"The erupting gas might endanger local children."},{"label":"C","text":"There was oil leakage along the Gulf Coast."},{"label":"D","text":"The local gassy hill might start a huge fire."}],"answer":"A","evidence":"山下有石油","explanation":"答案 A。录音核心依据：山下有石油。"},{"no":13,"type":"细节/推断题","prompt":"What prevented Higgins' workers from digging a proper hole to get the oil?","options":[{"label":"A","text":"The massive gas underground."},{"label":"B","text":"Their lack of the needed skill."},{"label":"C","text":"It gave birth to the oil drilling industry."},{"label":"D","text":"It was not popularized until years later."}],"answer":"D","evidence":"沙土阻碍挖洞","explanation":"答案 D。录音核心依据：沙土阻碍挖洞。"},{"no":14,"type":"细节/推断题","prompt":"What does the passage say about Captain Lucas' drilling method?","options":[{"label":"A","text":","},{"label":"B","text":","},{"label":"C","text":"and"},{"label":"D","text":". Then mark the corresponding letter on Answer Sheet 1 with a single line through the centre."}],"answer":"C","evidence":"催生现代钻井","explanation":"答案 C。录音核心依据：催生现代钻井。"},{"no":15,"type":"细节/推断题","prompt":"What do we learn about Texas' oil industry boom?","options":[{"label":"A","text":"It ruined the state's cotton and beef industries."},{"label":"B","text":"It totally destroyed the state's rural landscape."},{"label":"C","text":"Their lack of suitable tools."},{"label":"D","text":"The sand under the hill."}],"answer":"D","evidence":"改变得州经济","explanation":"答案 D。录音核心依据：改变得州经济。"}]},{"id":"2021-06-1-s5","section":"Section C","title":"Recording 1 · 差劲经理与企业文化 (Q16–18)","qRange":[16,18],"audio":"audio/listening/202106_s5.mp3","durationSec":241.5,"segments":[{"t0":0.85,"t1":2.85,"text":"Recording one."},{"t0":2.85,"t1":5.85,"text":"Most people dislike their jobs."},{"t0":5.85,"t1":9.85,"text":"It's an astonishing but statistical fact."},{"t0":9.85,"t1":12.85,"text":"A primary cause of employee dissatisfaction"},{"t0":12.85,"t1":14.85,"text":"according to fresh research"},{"t0":14.85,"t1":17.85,"text":"is that many believe they have terrible managers."},{"t0":17.85,"t1":23.85,"text":"Few describe their managers as malicious or manipulative, though."},{"t0":23.85,"t1":25.85,"text":"While those types certainly exist,"},{"t0":25.85,"t1":27.85,"text":"they are a minority."},{"t0":27.85,"t1":31.85,"text":"The majority of managers seemingly just don't know any better."},{"t0":31.85,"t1":35.85,"text":"They're often emulating bad managers they've had in the past."},{"t0":35.85,"t1":38.85,"text":"It's likely they've never read a management book"},{"t0":38.85,"t1":40.85,"text":"or attended a management course."},{"t0":40.85,"t1":45.85,"text":"They might not have even reflected on what good management looks like"},{"t0":45.85,"t1":49.85,"text":"and how it would influence their own management style."},{"t0":49.85,"t1":53.85,"text":"The researchers interviewed employees about their managers,"},{"t0":53.85,"t1":57.85,"text":"beginning with a question about the worst manager they had ever had."},{"t0":57.85,"t1":61.85,"text":"From this, the researchers came up with four main causes"},{"t0":61.85,"t1":66.85,"text":"of why some managers are perceived as being simply awful at their jobs."},{"t0":66.85,"t1":69.85,"text":"The first cause was company culture,"},{"t0":69.85,"t1":74.85,"text":"which was seen by employees as enabling poor management practices."},{"t0":74.85,"t1":78.85,"text":"It was specifically stressful work environments,"},{"t0":78.85,"t1":81.85,"text":"minimal training, and a lack of accountability"},{"t0":81.85,"t1":84.85,"text":"that were found to be the most blame-worthy."},{"t0":84.85,"t1":86.85,"text":"Often a manager's superiors"},{"t0":86.85,"t1":90.85,"text":"can effectively encourage a manager's distasteful behaviour"},{"t0":90.85,"t1":93.85,"text":"when they fail to discipline the person's wrong-doings."},{"t0":93.85,"t1":97.85,"text":"Such workplaces are sometimes described as toxic."},{"t0":97.85,"t1":102.85,"text":"The second cause was attributed to the manager's characteristics."},{"t0":102.85,"t1":106.85,"text":"Those deemed to be most destructive were odd people,"},{"t0":106.85,"t1":108.85,"text":"those without drive,"},{"t0":108.85,"t1":111.85,"text":"those who allow personal problems into the workplace"},{"t0":111.85,"t1":116.85,"text":"and those with an unpleasant temperament or personality in general."},{"t0":116.85,"t1":119.85,"text":"The third cause of poor management was associated"},{"t0":119.85,"t1":122.85,"text":"with a deficiency of qualifications."},{"t0":122.85,"t1":126.85,"text":"Not so much the formal variety one obtains from a university,"},{"t0":126.85,"t1":129.85,"text":"but the informal variety that comes from"},{"t0":129.85,"t1":133.85,"text":"credible work experience and professional accomplishments."},{"t0":133.85,"t1":136.85,"text":"The fourth cause concerned managers"},{"t0":136.85,"t1":140.85,"text":"who've been promoted for reasons other than potential."},{"t0":140.85,"t1":144.85,"text":"One reason in particular why these people had been promoted"},{"t0":144.85,"t1":147.85,"text":"was that they had been around the longest."},{"t0":147.85,"t1":152.85,"text":"It wasn't their skill set or other merits that got them the job,"},{"t0":152.85,"t1":154.85,"text":"it was their tenure."},{"t0":154.85,"t1":157.85,"text":"A point worth making is that the study was based"},{"t0":157.85,"t1":160.85,"text":"only on the perspective of employees."},{"t0":160.85,"t1":163.85,"text":"The researchers didn't ask senior leaders"},{"t0":163.85,"t1":167.85,"text":"what they thought of their frontline managers."},{"t0":167.85,"t1":171.85,"text":"It's quite possible their content with how the individuals"},{"t0":171.85,"t1":174.85,"text":"they promoted are now performing,"},{"t0":174.85,"t1":178.85,"text":"merrily ignorant of the damage they're actually causing."},{"t0":178.85,"t1":182.85,"text":"Which might explain why, as the researchers conclude,"},{"t0":182.85,"t1":185.85,"text":"those same middle managers are usually unaware"},{"t0":185.85,"t1":188.85,"text":"that they are a bad manager."},{"t0":189.85,"t1":194.85,"text":"Questions 16 to 18 are based on the recording you have just heard."},{"t0":194.85,"t1":196.85,"text":"Question 16."},{"t0":196.85,"t1":200.85,"text":"What is a primary cause of employee dissatisfaction"},{"t0":200.85,"t1":217.04,"text":"according to recent research?"},{"t0":217.04,"t1":219.04,"text":"Question 17."},{"t0":219.04,"t1":235.9,"text":"What is one of the causes for poor management practices?"},{"t0":235.9,"t1":237.9,"text":"Question 18."},{"t0":237.9,"t1":241.5,"text":"What do we learn about the study on job dissatisfaction?"}],"questions":[{"no":16,"type":"细节/推断题","prompt":"What is a primary cause of employee dissatisfaction according to recent research?","options":[{"label":"A","text":"Insufficient motivation."},{"label":"B","text":"Tough regulations."},{"label":"C","text":"Unsuitable jobs."},{"label":"D","text":"Bad managers."}],"answer":"D","evidence":"差劲经理","explanation":"答案 D。录音核心依据：差劲经理。"},{"no":17,"type":"细节/推断题","prompt":"What is one of the causes for poor management practices?","options":[{"label":"A","text":"Ineffective training."},{"label":"B","text":"Toxic company culture."},{"label":"C","text":"Overburdening of managers."},{"label":"D","text":"Lack of regular evaluation. /'\\\u0006 2021 6 J:J"}],"answer":"B","evidence":"有毒公司文化","explanation":"答案 B。录音核心依据：有毒公司文化。"},{"no":18,"type":"细节/推断题","prompt":"What do we learn about the study on job dissatisfaction?","options":[{"label":"A","text":"It was based only on the perspective of employees."},{"label":"B","text":"It provided meaningful clues to solving the problem."},{"label":"C","text":"It was conducted from frontline managers' point of view."},{"label":"D","text":"It collected feedback from both employers and employees."}],"answer":"A","evidence":"研究只采员工视角","explanation":"答案 A。录音核心依据：研究只采员工视角。"}]},{"id":"2021-06-1-s6","section":"Section C","title":"Recording 2 · 矿业自动化革命 (Q19–21)","qRange":[19,21],"audio":"audio/listening/202106_s6.mp3","durationSec":252.0,"segments":[{"t0":0.0,"t1":0.4,"text":"What do we learn about the study on job dissatisfaction?"},{"t0":0.4,"t1":16.36,"text":"Recording 2."},{"t0":16.36,"t1":20.36,"text":"With the use of driverless vehicles seemingly inevitable,"},{"t0":20.36,"t1":23.36,"text":"mining companies in the vast Australian desert state"},{"t0":23.36,"t1":27.36,"text":"of Western Australia are definitely taking the lead."},{"t0":27.36,"t1":31.36,"text":"Iron ore is a key ingredient in steel making."},{"t0":31.36,"t1":35.36,"text":"The mining companies here produce almost 300 million tons"},{"t0":35.36,"t1":37.36,"text":"of iron ore a year."},{"t0":37.36,"t1":41.36,"text":"The 240 giant autonomous trucks in use"},{"t0":41.36,"t1":46.36,"text":"in the Western Australian mines can weigh 400 tons fully loaded"},{"t0":46.36,"t1":50.36,"text":"and travel at speeds of up to 60 kilometers per hour."},{"t0":50.36,"t1":52.36,"text":"They are a technological leap,"},{"t0":52.36,"t1":55.36,"text":"transporting iron ore along routes which run"},{"t0":55.36,"t1":59.36,"text":"for hundreds of kilometers from mines to their destinations."},{"t0":59.36,"t1":62.36,"text":"Here, when the truck arrives at its destination,"},{"t0":62.36,"t1":65.36,"text":"staff in the operation centre direct it"},{"t0":65.36,"t1":67.36,"text":"precisely where to unload."},{"t0":67.36,"t1":71.36,"text":"Vast quantities of iron ore are then transported"},{"t0":71.36,"t1":74.36,"text":"by autonomous trains to ocean ports."},{"t0":74.36,"t1":77.36,"text":"Advocates argue these automated vehicles"},{"t0":77.36,"t1":79.36,"text":"will change mining forever."},{"t0":79.36,"t1":82.36,"text":"It may only be five years before the use"},{"t0":82.36,"t1":86.36,"text":"of automation technology leads to a fully robotic mine."},{"t0":86.36,"t1":90.36,"text":"A range of factors has pushed Western Australia's"},{"t0":90.36,"t1":94.36,"text":"desert region to the lead of this automation revolution."},{"t0":94.36,"t1":97.36,"text":"These include the huge size of the mines,"},{"t0":97.36,"t1":99.36,"text":"the scale of equipment,"},{"t0":99.36,"t1":102.36,"text":"and the repetitive nature of some of the work."},{"t0":102.36,"t1":105.36,"text":"Then there's the area's remoteness."},{"t0":105.36,"t1":108.36,"text":"At 502,000 square kilometers,"},{"t0":108.36,"t1":111.36,"text":"it can sometimes make recruiting staff a challenge."},{"t0":111.36,"t1":113.36,"text":"Another consideration is the risks"},{"t0":113.36,"t1":116.36,"text":"when humans interact with large machinery."},{"t0":116.36,"t1":119.36,"text":"There are also the financial imperatives."},{"t0":119.36,"t1":122.36,"text":"The ongoing push by the mining corporations"},{"t0":122.36,"t1":124.36,"text":"to be more productive and more efficient"},{"t0":124.36,"t1":126.36,"text":"is another powerful driver"},{"t0":126.36,"t1":129.36,"text":"in embracing automation technology."},{"t0":129.36,"t1":132.36,"text":"The concept of a fully autonomous mine"},{"t0":132.36,"t1":134.36,"text":"is a bit of a misleading term, however."},{"t0":134.36,"t1":137.36,"text":"This is because the more technology is put into the field,"},{"t0":137.36,"t1":140.36,"text":"the more people are needed to deploy,"},{"t0":140.36,"t1":142.36,"text":"maintain, and improve it."},{"t0":142.36,"t1":145.36,"text":"The automation and digitization of the industry"},{"t0":145.36,"t1":148.36,"text":"is creating a need for different jobs."},{"t0":148.36,"t1":150.36,"text":"These include data scientists"},{"t0":150.36,"t1":152.36,"text":"and engineers in automation"},{"t0":152.36,"t1":155.36,"text":"and artificial intelligence."},{"t0":155.36,"t1":158.36,"text":"The mining companies claim automation and robotics"},{"t0":158.36,"t1":160.36,"text":"present opportunities to make mining"},{"t0":160.36,"t1":163.36,"text":"more sustainable and safer."},{"t0":163.36,"t1":165.36,"text":"Employees will be offered a career"},{"t0":165.36,"t1":169.36,"text":"that is even more fulfilling and more rewarding."},{"t0":169.36,"t1":171.36,"text":"Workers' unions have accepted"},{"t0":171.36,"t1":174.36,"text":"the inevitability of the introduction of new technology,"},{"t0":174.36,"t1":176.36,"text":"but they still have reservations"},{"t0":176.36,"t1":179.36,"text":"about the rise of automation technology."},{"t0":179.36,"t1":182.36,"text":"Their main concern is the potential impact"},{"t0":182.36,"t1":184.36,"text":"on remote communities."},{"t0":184.36,"t1":186.36,"text":"As automation spreads further,"},{"t0":186.36,"t1":189.36,"text":"the question is how these remote communities"},{"t0":189.36,"t1":192.36,"text":"will survive when the old jobs are eliminated,"},{"t0":192.36,"t1":195.36,"text":"and this may well prove to be the most"},{"t0":195.36,"t1":198.36,"text":"significant impact of robotic technology"},{"t0":198.36,"t1":201.36,"text":"in many places around the world."},{"t0":201.36,"t1":204.36,"text":"Questions 19-21 are based on the recording"},{"t0":204.36,"t1":206.36,"text":"you have just heard."},{"t0":206.36,"t1":209.36,"text":"Question 19- What does the passage say"},{"t0":209.36,"t1":212.36,"text":"about the mining industry in Western Australia?"},{"t0":212.36,"t1":228.45,"text":"Question 20- What is the impact"},{"t0":228.45,"t1":231.45,"text":"of the digitization of the mining industry?"},{"t0":231.45,"t1":247.47,"text":"Question 21- What is the attitude"},{"t0":247.47,"t1":250.47,"text":"of workers' unions towards the introduction"},{"t0":250.47,"t1":252.0,"text":"of new technology?"}],"questions":[{"no":19,"type":"细节/推断题","prompt":"What does the passage say about the mining industry in Western Australia?","options":[{"label":"A","text":"It is expanding at an accelerating speed."},{"label":"B","text":"It is bringing prosperity to the region."},{"label":"C","text":"It is yielding an unprecedented profit."},{"label":"D","text":"It is seeing an automation revolution."}],"answer":"D","evidence":"采矿自动化革命","explanation":"答案 D。录音核心依据：采矿自动化革命。"},{"no":20,"type":"细节/推断题","prompt":"What is the impact of the digitization of the mining industry?","options":[{"label":"A","text":"It creates a lot of new jobs."},{"label":"B","text":"It exhausts res<;mrces sooner."},{"label":"C","text":"It causes conflicts between employers and employees."},{"label":"D","text":"It calls for the retraining of unskilled mining workers."}],"answer":"A","evidence":"创造新岗位","explanation":"答案 A。录音核心依据：创造新岗位。"},{"no":21,"type":"细节/推断题","prompt":"What is the attitude of workers' unions towards the introduction of new technology?","options":[{"label":"A","text":"They will wait to see its effect."},{"label":"B","text":"They welcome it with open arms."},{"label":"C","text":"They accept it with reservations."},{"label":"D","text":"They are strongly opposed to it."}],"answer":"C","evidence":"接受但有保留","explanation":"答案 C。录音核心依据：接受但有保留。"}]},{"id":"2021-06-1-s7","section":"Section C","title":"Recording 3 · 道路交通安全 (Q22–25)","qRange":[22,25],"audio":"audio/listening/202106_s7.mp3","durationSec":296.0,"segments":[{"t0":0.0,"t1":0.47,"text":"of new technology?"},{"t0":0.47,"t1":17.46,"text":"Recording 3- According to official statistics,"},{"t0":17.46,"t1":20.46,"text":"Thailand's annual road death rate"},{"t0":20.46,"t1":23.46,"text":"is almost double the global average."},{"t0":23.46,"t1":27.46,"text":"Thai people know that their roads are dangerous,"},{"t0":27.46,"t1":31.46,"text":"but they don't know this could easily be changed."},{"t0":31.46,"t1":34.46,"text":"Globally, road accidents kill more people"},{"t0":34.46,"t1":38.46,"text":"every year than any infectious disease."},{"t0":38.46,"t1":41.46,"text":"Researchers at the Institute for Health Metrics"},{"t0":41.46,"t1":44.46,"text":"and Evaluation in America put the death toll"},{"t0":44.46,"t1":48.46,"text":"in 2017 at 1.24 million."},{"t0":48.46,"t1":51.46,"text":"According to the Institute, the overall number"},{"t0":51.46,"t1":54.46,"text":"of deaths has been more or less static"},{"t0":54.46,"t1":56.46,"text":"since the turn of the century,"},{"t0":56.46,"t1":59.46,"text":"but that disguises a lot of changes"},{"t0":59.46,"t1":61.46,"text":"in individual countries."},{"t0":61.46,"t1":64.46,"text":"In many poor countries, road accidents"},{"t0":64.46,"t1":67.46,"text":"are killing more people than ever before."},{"t0":67.46,"t1":71.46,"text":"Those countries have swelling young populations,"},{"t0":71.46,"t1":74.46,"text":"a fast-growing fleet of cars and motorbikes,"},{"t0":74.46,"t1":77.46,"text":"and a limited supply of surgeons."},{"t0":77.46,"t1":79.46,"text":"It is impossible to know for sure"},{"t0":79.46,"t1":82.46,"text":"because official statistics are so inadequate,"},{"t0":82.46,"t1":86.46,"text":"but deaths are thought to have risen by 40%"},{"t0":86.46,"t1":90.46,"text":"since 1990 in many low-income countries."},{"t0":90.46,"t1":93.46,"text":"In many rich countries, by contrast,"},{"t0":93.46,"t1":95.46,"text":"roads are becoming even safer."},{"t0":95.46,"t1":98.46,"text":"In Estonia and Ireland, for example,"},{"t0":98.46,"t1":101.46,"text":"the number of deaths has fallen by about"},{"t0":101.46,"t1":105.46,"text":"two-thirds since the late 1990s."},{"t0":105.46,"t1":109.46,"text":"But the most important and intriguing changes"},{"t0":109.46,"t1":112.46,"text":"are taking place in middle-income countries"},{"t0":112.46,"t1":115.46,"text":"which contain most of the world's people"},{"t0":115.46,"t1":118.46,"text":"and have some of the most dangerous roads."},{"t0":118.46,"t1":122.46,"text":"According to researchers, in China and South Africa,"},{"t0":122.46,"t1":126.46,"text":"traffic deaths have been falling since 2000"},{"t0":126.46,"t1":129.46,"text":"and in India since 2012,"},{"t0":129.46,"t1":133.46,"text":"and the Philippines reached its peak four years ago."},{"t0":133.46,"t1":139.46,"text":"The question is whether Thailand can soon follow suit."},{"t0":139.46,"t1":144.46,"text":"Rob McKinney, head of the International Road Assessment Programme,"},{"t0":144.46,"t1":148.46,"text":"says that all countries tend to go through three phases."},{"t0":148.46,"t1":152.46,"text":"They begin with poor, slow roads."},{"t0":152.46,"t1":155.46,"text":"In the second phase, as they grow wealthier,"},{"t0":155.46,"t1":159.46,"text":"they pave the roads, allowing traffic to move faster"},{"t0":159.46,"t1":161.46,"text":"and pushing up the death rate."},{"t0":161.46,"t1":164.46,"text":"Lastly, in the third phase,"},{"t0":164.46,"t1":167.46,"text":"countries act to make their roads safer."},{"t0":167.46,"t1":171.46,"text":"The trick, then, is to reach the third stage sooner"},{"t0":171.46,"t1":177.46,"text":"by focusing earlier and more closely on fatal accidents."},{"t0":177.46,"t1":179.46,"text":"How to do that?"},{"t0":179.46,"t1":182.46,"text":"The solution lies not just in better infrastructure"},{"t0":182.46,"t1":185.46,"text":"but in better social incentives."},{"t0":185.46,"t1":188.46,"text":"Safe driving habits are practices"},{"t0":188.46,"t1":192.46,"text":"which people know they should follow but often don't."},{"t0":192.46,"t1":198.46,"text":"Dangerous driving is not a fixed cultural trait, as some imagine."},{"t0":198.46,"t1":202.46,"text":"People respond to incentives such as traffic laws"},{"t0":202.46,"t1":205.46,"text":"that are actually enforced."},{"t0":205.46,"t1":210.46,"text":"Questions 22 to 25 are based on the recording you have just heard."},{"t0":210.46,"t1":212.46,"text":"Question 22."},{"t0":212.46,"t1":217.46,"text":"What does the speaker say about traffic accidents in Thailand?"},{"t0":217.46,"t1":232.2,"text":"Question 23."},{"t0":232.2,"t1":236.2,"text":"What do we learn from an American Institute's statistics"},{"t0":236.2,"t1":238.2,"text":"regarding road deaths?"},{"t0":238.2,"t1":252.94,"text":"Question 24."},{"t0":252.94,"t1":255.94,"text":"What is said about middle-income countries?"},{"t0":255.94,"t1":270.67,"text":"Question 25."},{"t0":270.67,"t1":274.67,"text":"What else could be done to reduce fatal road accidents"},{"t0":274.67,"t1":276.67,"text":"in addition to safer roads?"},{"t0":276.67,"t1":292.44,"text":"That's the end of listening comprehension."}],"questions":[{"no":22,"type":"细节/推断题","prompt":"What does the speaker say about traffic accidents in Thailand?","options":[{"label":"A","text":"They have experienced a gradual decline since the year of 2017."},{"label":"B","text":"Their annual death rate is about twice that of the global average."},{"label":"C","text":"They kill more people than any infectious disease."},{"label":"D","text":"Their cost to the nation's economy is incalculable."}],"answer":"B","evidence":"年死亡率约全球两倍","explanation":"答案 B。录音核心依据：年死亡率约全球两倍。"},{"no":23,"type":"细节/推断题","prompt":"What do we learn from an American Institute's statistics regarding road deaths?","options":[{"label":"A","text":"They are not as reliable as claimed."},{"label":"B","text":"They rise and fall from year to year."},{"label":"C","text":"They don't reflect the changes in individual countries."},{"label":"D","text":"They show a difference between rich and poor nations."}],"answer":"C","evidence":"总量掩盖各国变化","explanation":"答案 C。录音核心依据：总量掩盖各国变化。"},{"no":24,"type":"细节/推断题","prompt":"What is said about middle-income countries?","options":[{"label":"A","text":"Many of them are investing heavily in infrastructure."},{"label":"B","text":"Many of them have seen a decline in road-death rates."},{"label":"C","text":"Many of them are following the example set by Thailand."},{"label":"D","text":"Many of them have increasing numbers of cars on the road."}],"answer":"B","evidence":"许多中等收入国死亡率下降","explanation":"答案 B。录音核心依据：许多中等收入国死亡率下降。"},{"no":25,"type":"细节/推断题","prompt":"What else could be done to reduce fatal road accidents in addition to safer roads?","options":[{"label":"A","text":"Supportive."},{"label":"B","text":"Skeptical."},{"label":"C","text":"Divided. Translation ( 30 minutes)"},{"label":"D","text":"Unclear. should write your answer on Answer Sheet 2 . --D«EFGHI*J•-*•'D&F*J·--IKfilo ··· ,m JE,LMN¥-r ,ffl.*O1Ji' ,m7.J<Ylti'ftL*P?tmiX1UL:P..Q&ffflSDRvlcS 131c?frI:fll!TUEJr, ffif Wftff 1g * J Im*:m \u000eJt@Jf!Jff!. ,4ff&ffflSVs! T*:ffl:*1HhfWo m * 1988 &f Xi/Y\" LlHtE , , \u000ffij} _\u000e!L \u000f \u0004ii* r: .ill(lS i\u0004L\u0005\u0006, \u0007 * \u0003 ltfE-I 1i #JH:HJHf fiL :(£ * \u0004 Z[SQmA\\I*h]^_,--`ab*J•*I§wfficdefo 6 fj"}],"answer":"A","evidence":"改善驾驶行为/社会激励","explanation":"答案 A。录音核心依据：改善驾驶行为/社会激励。"}]}]},{"id":"2026-06-1","title":"2026年6月 六级第1套（最新真题 · 含逐段双语听稿）","year":"2026.06","exam":"六级 CET-6","totalQuestions":25,"audioMode":"full","fullAudio":"audio/listening/202606_set1.mp3","sections":[{"id":"2026-06-1-s1","section":"Section A","title":"Conversation 1 (Q1–4)","qRange":[1,4],"audio":"audio/listening/202606_set1.mp3","fullTrack":true,"bilingual":[{"en":"M: Welcome to \"Business Matters\". Today we have invited career development consultant Lucy Williams to talk about how to get ahead at work. Hi, Lucy. Many of us never seem to get promoted. Why is that? And what can we do about it?","zh":"M: 欢迎收听《商业纵横》。今天我们邀请了职业发展顾问露西·威廉姆斯,来谈谈如何在职场上取得成功。你好,露西。我们很多人似乎一直得不到晋升,这是为什么?我们又能做些什么呢?"},{"en":"W: One mistake people make is to limit communication only to their bosses. It's important to expand your network and include your co-workers.","zh":"W: 人们常犯的一个错误,是把沟通对象局限在自己的上司。拓展人际网络很重要,也要把同事纳入其中。"},{"en":"M: But some of our co-workers are less senior to us. Is it really necessary to connect with them?","zh":"M: 但我们有些同事的职位比我们低。真的有必要和他们建立联系吗?"},{"en":"W: It's important not to underestimate your colleagues. Sometimes a job title might not clearly demonstrate the influence they may have.","zh":"W: 重要的是不要低估你的同事。有时候,职位名称并不能清楚地体现他们可能拥有的影响力。"},{"en":"M: Now many of us think that working hard creates a good impression, but this isn't always true, is it?","zh":"M: 现在我们很多人都认为努力工作会给别人留下好印象,但事实并不总是如此,对吧?"},{"en":"W: That's right. We should avoid trying to take on too much work and constantly staying late, just to show that you are committed.","zh":"W: 没错。我们应该避免为了表现出自己的投入,就试图承担过多的工作,还总是加班到很晚。"},{"en":"M: I see. So setting expectations too high at the beginning can make us look bad if we don't maintain them.","zh":"M: 我明白了。所以,一开始就把别人对我们的期待设得太高,如果后来无法保持,就可能让我们看起来很糟糕。"},{"en":"W: Yeah, it's better to make sure you are putting in quality time instead of just a large quantity of time. And these efforts can easily be demonstrated by the results we achieve.","zh":"W: 是的,最好确保自己投入的是高质量的时间,而不只是大量的时间。而且,我们取得的成果很容易证明这些努力。"},{"en":"M: What about helping others at work? Should you try and go beyond your normal responsibilities and offer to help people with their projects?","zh":"M: 那么,在工作中帮助别人呢?你是否应该尽力超越自己的日常职责,主动提出帮助别人完成项目?"},{"en":"W: Extend your assistance to those who need it, but only as long as your own work will not go unattended. If someone can benefit from your assistance or advice, help them out to gain their respect and trust.","zh":"W: 向那些需要帮助的人提供援助,但前提是不能让自己的工作无人处理。如果有人能从你的帮助或建议中获益,就帮他们一把,以赢得他们的尊重和信任。"},{"en":"M: But it goes without saying that you shouldn't act like a know-it-all, otherwise you'll appear arrogant.","zh":"M: 不过,显而易见,你不应该表现得像个无所不知的人,否则会显得傲慢。"},{"en":"W: Absolutely. Be humble, and you'll get a lot of time later on to show your genius.","zh":"W: 当然。保持谦逊,之后你会有很多时间展现自己的才华。"}],"questions":[{"no":1,"type":"主旨题","prompt":"What are the speakers mainly talking about?","options":[{"label":"A","text":"How to run one's business successfully.","zh":"如何成功经营自己的事业。"},{"label":"B","text":"How to make progress in one's career.","zh":"如何在职业生涯中取得进步。"},{"label":"C","text":"Why few people can fully display their capabilities.","zh":"为什么很少有人能够充分展现自己的能力。"},{"label":"D","text":"Why young people seldom get the expected promotion.","zh":"为什么年轻人很少得到预期的晋升。"}],"answer":"B","evidence":"M: Welcome to \"Business Matters\". Today we have invited career development consultant\nLucy Williams to talk about how to get ahead at work. Hi, Lucy. Many of us never seem to\nget promoted. Why is that? And what can we do about it?\n男:欢迎来到《Business Matters》。今天我们邀请了职业发展顾问 Lucy Williams 来谈谈\n如何在职场上取得进步。嗨,Lucy。很多人似乎一直得不到晋升。为什么会这样?我们能做\n些什么?","signal":"开头点题句。主持人开场即点明 “to talk about how to get ahead at work”,how to\nget ahead at work 直接给出对话主题;后续多次出现的 promoted、career 等词进一步\n锁定。","paraphrase":"how to get ahead at work ↔How to make progress in one's career.\n同义改写:get ahead = make progress;at work = in one's career","explanation":"【信号】开头点题句。主持人开场即点明 “to talk about how to get ahead at work”,how to\nget ahead at work 直接给出对话主题;后续多次出现的 promoted、career 等词进一步\n锁定。\n【替换】how to get ahead at work ↔How to make progress in one's career.\n同义改写:get ahead = make progress;at work = in one's career\n【排除】A"},{"no":2,"type":"细节题","prompt":"What does the woman say is one mistake people make?","options":[{"label":"A","text":"To mix and interact with peers within the organization.","zh":"在组织内与同辈交流互动。"},{"label":"B","text":"To restrict their connections exclusively to colleagues.","zh":"将自己的交往范围仅限于同事。"},{"label":"C","text":"To limit communication only to their superiors.","zh":"将交流仅限于上级。"},{"label":"D","text":"To underestimate their role in the company.","zh":"低估自己在公司的作用。"}],"answer":"C","evidence":"W: One mistake people make is to limit communication only to their bosses. It's important to\nexpand your network and include your co-workers.\n女:人们犯的一个错误是只跟老板沟通。重要的是拓展人脉,把同事也包括进来。","signal":"被问者直接应答 + 关键信息 “One mistake...”。男人在 P1 末尾问 “Why is that? And\nwhat can we do about it?”,女人在 P2 直接以 “One mistake people make is...” 作答,\nOne mistake people make is to limit communication only to their bosses. 就是答\n案句。","paraphrase":"limit communication only to their bosses. ↔To limit communication only to their superiors.\n同义替换:bosses = superiors","explanation":"【信号】被问者直接应答 + 关键信息 “One mistake...”。男人在 P1 末尾问 “Why is that? And\nwhat can we do about it?”,女人在 P2 直接以 “One mistake people make is...” 作答,\nOne mistake people make is to limit communication only to their bosses. 就是答\n案句。\n【替换】limit communication only to their bosses. ↔To limit communication only to their superiors.\n同义替换:bosses = superiors\n【排除】A"},{"no":3,"type":"细节题","prompt":"What does the woman advise people to do in their work?","options":[{"label":"A","text":"Put in quality time.","zh":"投入高质量的时间。"},{"label":"B","text":"Connect with managers.","zh":"与管理人员建立联系。"},{"label":"C","text":"Make greater efforts.","zh":"付出更大的努力。"},{"label":"D","text":"Demonstrate final results.","zh":"展示最终成果。"}],"answer":"A","evidence":"W: Yeah, it's better to make sure you are putting in quality time instead of just a large quantity\nof time. And these efforts can easily be demonstrated by the results we achieve.\n女:是的,你最好确保自己投入的是高质量时间,而不是单纯的大量时间。并且这些努力可\n以通过我们取得的成果轻易体现出来。","signal":"建议句 it's better to... + 取舍 instead of。男人在 P5 提出 “working hard... staying\nlate” 的困惑,女人在 P8 用 “it's better to...” 给出建议,并用 “instead of” 把 “quality\ntime” 与 “quantity of time” 对立,答案落在 quality time 上。","paraphrase":"putting in quality time ↔Put in quality time.\n直接提取核心动作短语","explanation":"【信号】建议句 it's better to... + 取舍 instead of。男人在 P5 提出 “working hard... staying\nlate” 的困惑,女人在 P8 用 “it's better to...” 给出建议,并用 “instead of” 把 “quality\ntime” 与 “quantity of time” 对立,答案落在 quality time 上。\n【替换】putting in quality time ↔Put in quality time.\n直接提取核心动作短语\n【排除】B"},{"no":4,"type":"细节题","prompt":"Why does the man say one should not act like a know-it-all?","options":[{"label":"A","text":",","zh":"为了展示自己的才智。"},{"label":"B","text":",","zh":"为了赢得应有的尊重。"},{"label":"C","text":"and","zh":"为了避免受到羞辱。"},{"label":"D","text":". Then mark the corresponding letter on Answer Sheet 1 with a single line through the centre.","zh":"为了避免显得傲慢。"}],"answer":"D","evidence":"M: But it goes without saying that you shouldn't act like a know-it-all, otherwise you'll\nappear arrogant.\n男:但不用说,你不应该表现得像个万事通,否则你会显得傲慢。","signal":"因果连接词 otherwise 后的结果。男人在 P11 用 “otherwise you'll appear arrogant” 直\n接给出 “不要表现得像 know-it-all” 的原因/后果,otherwise you'll appear arrogant. 是答\n案信号。","paraphrase":"you'll appear arrogant. ↔To avoid appearing arrogant.\n条件-目的转换:otherwise you'll appear arrogant → to avoid appearing arrogant","explanation":"【信号】因果连接词 otherwise 后的结果。男人在 P11 用 “otherwise you'll appear arrogant” 直\n接给出 “不要表现得像 know-it-all” 的原因/后果,otherwise you'll appear arrogant. 是答\n案信号。\n【替换】you'll appear arrogant. ↔To avoid appearing arrogant.\n条件-目的转换:otherwise you'll appear arrogant → to avoid appearing arrogant\n【排除】A"}]},{"id":"2026-06-1-s2","section":"Section A","title":"Conversation 2 (Q5–8)","qRange":[5,8],"audio":"audio/listening/202606_set1.mp3","fullTrack":true,"bilingual":[{"en":"W: I think we first need to decide how to divide up the presentation responsibilities. From what I recall, the presentation consists of five parts, not including the introduction and conclusion. That would mean altogether, we need to allocate seven parts between the two of us.","zh":"W: 我觉得我们首先需要决定如何分配演示的任务。据我所记得,这次演示由五个部分组成,不包括开头和结尾。也就是说,我们总共需要在我们两个人之间分配七个部分。"},{"en":"M: So, we have the abstract, background research, the project design, the results and the discussion portions. As the abstract section only applies to the article, we needn't include it in the presentation. How would you suggest we dole out the rest?","zh":"M: 所以,我们有摘要、背景研究、项目设计、结果和讨论这几个部分。由于摘要部分只适用于文章,我们不必把它包括在演示中。你建议我们如何分配剩下的部分?"},{"en":"W: How do you feel about handling the background bit? In this way, we can both discuss the part of the project that we devoted most of our time to.","zh":"W: 你觉得由你来负责背景研究部分怎么样?这样一来,我们就都可以讲述自己投入最多时间的项目部分了。"},{"en":"M: Hold on a minute. You want me, the one who did the bulk of the task, to also do the majority of the presentation? The background research which was so meticulous took more than a month.","zh":"M: 等一下。你是想让我这个承担了大部分任务的人,再负责演示的大部分内容?那份一丝不苟的背景研究花了一个多月的时间。"},{"en":"W: OK. OK. I get it. Quit your moaning. I appreciate the rigorous work ethic you applied to the research, but not the sarcasm that comes up every time I mention it. What do you think would be a fair arrangement?","zh":"W: 好了,好了。我明白了。别再抱怨了。我认可你在研究中所表现出的严谨工作态度,但不欣赏每次我提到这件事时你表现出的讽刺。你觉得怎样分配才公平?"},{"en":"M: I think the best arrangement would be to split the research into two parts: before-1980 and afterward. I would take the before-portion and you would be assigned the after-1980, leaving the project and results. I volunteer to describe the project. But as I struggled a bit with the statistics in the results section, how about you handling that?","zh":"M: 我觉得最好的安排是把研究分成两部分:1980年以前和之后。我负责1980年以前的部分,你负责1980年以后的部分,项目设计和结果部分则另行分配。我自愿介绍项目设计。不过,我在结果部分的统计数据方面有些吃力,你来负责那一部分怎么样?"},{"en":"W: That's agreeable to me. I propose we both handle the discussion section in parts along with the question and answer afterward, leaving only the introduction and conclusion.","zh":"W: 我觉得这样可以。我提议我们分段负责讨论部分,之后的问答环节也由我们共同完成,这样就只剩下开头和结尾了。"},{"en":"M: I will take responsibility for the conclusion and put you in charge of the introduction. This will make it so that we alternate presenting, so as to avoid sounding monotonous to the audience.","zh":"M: 我来负责结尾,你来负责开头。这样我们就可以交替进行演示,避免让听众觉得单调。"}],"questions":[{"no":5,"type":"细节题","prompt":"What does the woman say they first need to do?","options":[{"label":"A","text":"Decide how to divide up the presentation tasks.","zh":"决定如何分配演示任务。"},{"label":"B","text":"Investigate the available background research.","zh":"调查现有的背景研究。"},{"label":"C","text":"Complete the project design together.","zh":"共同完成项目设计。"},{"label":"D","text":"Find a suitable topic for their article.","zh":"为他们的文章寻找一个合适的主题。"}],"answer":"A","evidence":"I think we first need to decide how to divide up the presentation responsibilities.\n我认为我们首先需要决定如何分配展示任务。","signal":"first need to 给出动作起点。答案句以 first need to decide 开头,『first need to』是时\n间顺序与任务起点的双重信号,直接回答题干中的 first need to do。","paraphrase":"decide how to divide up the presentation responsibilities ↔\nDecide how to divide up the presentation tasks.\nresponsibilities 与 tasks 同义替换","explanation":"【信号】first need to 给出动作起点。答案句以 first need to decide 开头,『first need to』是时\n间顺序与任务起点的双重信号,直接回答题干中的 first need to do。\n【替换】decide how to divide up the presentation responsibilities ↔\nDecide how to divide up the presentation tasks.\nresponsibilities 与 tasks 同义替换\n【排除】B"},{"no":6,"type":"细节题","prompt":"Why does the man refuse to handle the background part?","options":[{"label":"A","text":"He wants to devote his time to other portions.","zh":"他想把时间投入到其他部分。"},{"label":"B","text":"He believes the woman is better able to handle it.","zh":"他认为这位女士更有能力处理这部分。"},{"label":"C","text":"He claims to have done most of the work already.","zh":"他声称自己已经完成了大部分工作。"},{"label":"D","text":"He finds the woman more meticulous about details.","zh":"他认为这位女士对细节更加仔细。"}],"answer":"C","evidence":"Hold on a minute. You want me, the one who did the bulk of the task, to also do the majority\nof the presentation? The background research which was so meticulous took more than\na month.\n等一下。你想让我这个做了大部分工作的人,还要做展示的大部分?那份非常细致的背景研\n究花了一个多月。","signal":"反问语气+the one who 自我强调。男士用 Hold on a minute 打断,并以反问 You want\nme, the one who did the bulk of the task, to also do the majority of the\npresentation? 强调自己已经做了大量工作,这是拒绝的核心信号。","paraphrase":"the one who did the bulk of the task ↔He claims to have done most of the work already.\nbulk of the task 与 most of the work 同义","explanation":"【信号】反问语气+the one who 自我强调。男士用 Hold on a minute 打断,并以反问 You want\nme, the one who did the bulk of the task, to also do the majority of the\npresentation? 强调自己已经做了大量工作,这是拒绝的核心信号。\n【替换】the one who did the bulk of the task ↔He claims to have done most of the work already.\nbulk of the task 与 most of the work 同义\n【排除】A"},{"no":7,"type":"细节题","prompt":"What does the woman urge the man to stop doing?","options":[{"label":"A","text":"Questioning.","zh":"提出质疑。"},{"label":"B","text":"Complaining.","zh":"抱怨。"},{"label":"C","text":"Arguing.","zh":"争论。"},{"label":"D","text":"Worrying.","zh":"担心。"}],"answer":"B","evidence":"OK. OK. I get it. Quit your moaning.\n好了好了,我明白了。别抱怨了。","signal":"Quit your moaning 是直接劝阻。女士先说 OK. OK. I get it 表示理解,紧接着用祈使句\nQuit your moaning 直接要求男士停止某种行为,这是答案句的核心信号。","paraphrase":"Quit your moaning ↔Complaining\nmoaning 与 complaining 同义","explanation":"【信号】Quit your moaning 是直接劝阻。女士先说 OK. OK. I get it 表示理解,紧接着用祈使句\nQuit your moaning 直接要求男士停止某种行为,这是答案句的核心信号。\n【替换】Quit your moaning ↔Complaining\nmoaning 与 complaining 同义\n【排除】A"},{"no":8,"type":"细节题","prompt":"Why does the man suggest he present the conclusion and the woman do\nthe introduction?","options":[{"label":"A","text":"To avoid sounding monotonous to the listeners.","zh":"为了避免让听众觉得单调乏味。"},{"label":"B","text":"To make the division of labor more reasonable.","zh":"为了使分工更加合理。"},{"label":"C","text":"To keep himself from being overburdened.","zh":"为了避免自己负担过重。"},{"label":"D","text":"To bring their capabilities fully into play.","zh":"为了充分发挥他们各自的能力。"}],"answer":"A","evidence":"I will take responsibility for the conclusion and put you in charge of the introduction.\nThis will make it so that we alternate presenting, so as to avoid sounding monotonous to\nthe audience.\n我负责结论部分,你负责开头部分。这样我们就会交替展示,以免让听众感到单调乏味。","signal":"so as to 给出目的。男士先提出分工安排,然后用 This will make it so that...so as to... 给\n出目的,so as to 是典型的目的信号词,直接回答 why。","paraphrase":"avoid sounding monotonous to the audience ↔To avoid sounding monotonous to the listeners.\naudience 与 listeners 同义","explanation":"【信号】so as to 给出目的。男士先提出分工安排,然后用 This will make it so that...so as to... 给\n出目的,so as to 是典型的目的信号词,直接回答 why。\n【替换】avoid sounding monotonous to the audience ↔To avoid sounding monotonous to the listeners.\naudience 与 listeners 同义\n【排除】B"}]},{"id":"2026-06-1-s3","section":"Section B","title":"Passage 1 (Q9–11)","qRange":[9,11],"audio":"audio/listening/202606_set1.mp3","fullTrack":true,"bilingual":[{"en":"Makeup can do more than just change your appearance—it can also alter others' perceptions of you, for better or for worse. According to new research from the University of Stirling in Scotland, although both men and women perceive women who wear makeup as being of a higher status, men associate makeup with prestigious, positive qualities, while women view other women wearing makeup as being dominant and a potential threat.","zh":"化妆不仅能改变你的外表,还能改变他人对你的看法,结果可能更好,也可能更糟。根据苏格兰斯特灵大学的一项新研究,虽然男性和女性都认为化妆的女性地位更高,但男性会将化妆与有声望、积极的品质联系起来,而女性则认为化妆的其他女性更具支配性,并可能构成威胁。"},{"en":"The research showed that men and women both rated the faces with cosmetics as being more attractive, but only women rated made-up faces as being more dominant, while only men rated made-up faces as being higher in prestige.","zh":"研究表明,男性和女性都认为化妆后的面孔更具吸引力,但只有女性认为化妆后的面孔更具支配性,只有男性认为化妆后的面孔具有更高的声望。"},{"en":"A follow-up study investigated the root cause behind these differences in perception, and found that female-on-female jealousy seemed to be the main cause of the differences in perception. Women rating women with makeup said they would be more jealous of them and thought they would be more attractive to men than their non-makeup wearing counterparts.","zh":"一项后续研究探究了这些认知差异背后的根本原因,发现女性之间的嫉妒似乎是造成这种认知差异的主要原因。对化妆女性进行评价的女性表示,她们会更嫉妒这些女性,并认为相比不化妆的女性,她们对男性更具吸引力。"},{"en":"Cosmetic products are good for more than just giving you a pretty face. It can be particularly useful for women to understand how wearing makeup alters others' perceptions of them in situations where they are trying to gain others' trust and admiration. At a job interview, knowing whether the hiring committee will consist of men or women might influence a female candidate's decision about wearing makeup. Whether the interviewers will view her as attractive, dominant and prestigious can affect the interviewers' actions and perhaps the outcome of the interview itself.","zh":"化妆品的作用不只是让你拥有一张漂亮的脸。对于女性而言,了解化妆如何改变他人对自己的看法,尤其是在试图赢得他人的信任和钦佩时,可能非常有用。在求职面试中,了解招聘委员会由男性还是女性组成,可能会影响女性求职者是否化妆的决定。面试官是否会认为她具有吸引力、支配性和声望,可能会影响面试官的行为,甚至可能影响面试本身的结果。"}],"questions":[{"no":9,"type":"细节题","prompt":"What can makeup do according to new research from the University of Stirling\nin Scotland?","options":[{"label":"A","text":"Alter others' perceptions of the wearer.","zh":"改变他人对化妆者的看法。"},{"label":"B","text":"Win others' admiration for the wearer.","zh":"赢得他人对化妆者的赞赏。"},{"label":"C","text":"Enhance the wearer's confidence.","zh":"增强化妆者的自信。"},{"label":"D","text":"Change the wearer's appearance.","zh":"改变化妆者的外貌。"}],"answer":"A","evidence":"Makeup can do more than just change your appearance—it can also alter others' perceptions\nof you, for better or for worse. According to new research from the University of Stirling in\nScotland, although both men and women perceive women who wear makeup as being of a\nhigher status, men associate makeup with prestigious, positive qualities, while women view\nother women wearing makeup as being dominant and a potential threat.\n化妆不仅能改变你的外貌——它还能改变他人对你的看法,无论好坏。根据苏格兰斯特林大\n学的新研究,尽管男性和女性都认为化妆的女性地位更高,但男性将化妆与有声望的积极品\n质联系在一起,而女性则认为化妆的其他女性更具主导性且是一种潜在威胁。","signal":"主题句 + 研究来源句。答案信号来自段落开头的主题句 'Makeup can do more than just\nchange your appearance—it can also alter others' perceptions of you',其中 'it can\nalso alter others' perceptions of you' 直接回应题干 'What can makeup do';随后\n'According to new research from the University of Stirling in Scotland' 进一步给出具\n体研究发现。","paraphrase":"alter others' perceptions of you ↔Alter others' perceptions of the wearer.\n同义改写:第二人称转第三人称","explanation":"【信号】主题句 + 研究来源句。答案信号来自段落开头的主题句 'Makeup can do more than just\nchange your appearance—it can also alter others' perceptions of you',其中 'it can\nalso alter others' perceptions of you' 直接回应题干 'What can makeup do';随后\n'According to new research from the University of Stirling in Scotland' 进一步给出具\n体研究发现。\n【替换】alter others' perceptions of you ↔Alter others' perceptions of the wearer.\n同义改写:第二人称转第三人称\n【排除】B"},{"no":10,"type":"细节题","prompt":"How did both men and women rate the faces with cosmetics in the new research?","options":[{"label":"A","text":"As being a greater threat.","zh":"认为这些面孔具有更大的威胁性。"},{"label":"B","text":"As being of higher prestige.","zh":"认为这些面孔具有更高的声望。"},{"label":"C","text":"As being more dominant.","zh":"认为这些面孔更具支配性。"},{"label":"D","text":"As being more attractive.","zh":"认为这些面孔更有吸引力。"}],"answer":"D","evidence":"The research showed that men and women both rated the faces with cosmetics as being more\nattractive, but only women rated made-up faces as being more dominant, while only men\nrated made-up faces as being higher in prestige.\n研究显示,男性和女性都认为化妆后的脸更具吸引力,但只有女性认为化妆后的脸更具主导\n性,只有男性认为化妆后的脸更有声望。","signal":"对比结构 'both...but only...while only...'。答案信号是对比结构 'men and women\nboth... but only women... while only men...',题干问 'both men and women',因此答\n案落在 'both' 引导的分句里,即 'more attractive'。","paraphrase":"men and women both rated the faces with cosmetics as being more attractive ↔\nAs being more attractive.\n直接对应:原句谓语改写为选项表语","explanation":"【信号】对比结构 'both...but only...while only...'。答案信号是对比结构 'men and women\nboth... but only women... while only men...',题干问 'both men and women',因此答\n案落在 'both' 引导的分句里,即 'more attractive'。\n【替换】men and women both rated the faces with cosmetics as being more attractive ↔\nAs being more attractive.\n直接对应:原句谓语改写为选项表语\n【排除】A"},{"no":11,"type":"细节题","prompt":"Why does a female candidate need to know the gender of the hiring\ncommittee members?","options":[{"label":"A","text":",","zh":"这可能会影响她介绍自己的方式。"},{"label":"B","text":",","zh":"这可能会影响她为这一场合选择的着装风格。"},{"label":"C","text":"and","zh":"这可能会影响她是否使用化妆品的决定。"},{"label":"D","text":". Then mark the corresponding letter on Answer Sheet 1 with a single line through the centre.","zh":"这可能会左右她对面试官问题的看法。"}],"answer":"C","evidence":"At a job interview, knowing whether the hiring committee will consist of men or women\nmight influence a female candidate's decision about wearing makeup.\n在工作面试中,知道招聘委员会将由男性还是女性组成可能会影响女性候选人是否化妆的\n决定。","signal":"应用举例中的 'might influence... decision about wearing makeup'。答案信号来自段\n落中的应用举例句:'At a job interview, knowing whether... might influence a female\ncandidate's decision about wearing makeup',其中 'knowing whether the hiring\ncommittee will consist of men or women' 直接对应题干的 'know the gender of the\nhiring committee members','might influence... decision about wearing makeup' 直\n接回答 why。","paraphrase":"influence a female candidate's decision about wearing makeup ↔\nIt might affect her decision on applying cosmetics.\n同义改写:动词、名词、人称三处对应","explanation":"【信号】应用举例中的 'might influence... decision about wearing makeup'。答案信号来自段\n落中的应用举例句:'At a job interview, knowing whether... might influence a female\ncandidate's decision about wearing makeup',其中 'knowing whether the hiring\ncommittee will consist of men or women' 直接对应题干的 'know the gender of the\nhiring committee members','might influence... decision about wearing makeup' 直\n接回答 why。\n【替换】influence a female candidate's decision about wearing makeup ↔\nIt might affect her decision on applying cosmetics.\n同义改写:动词、名词、人称三处对应\n【排除】A"}]},{"id":"2026-06-1-s4","section":"Section B","title":"Passage 2 (Q12–15)","qRange":[12,15],"audio":"audio/listening/202606_set1.mp3","fullTrack":true,"bilingual":[{"en":"You may have seen advertisements trumpeting methods of changing a habit that require absolutely no willpower whatsoever. But can you really change a bad habit or create a good one without willpower? To answer this question, we first have to ask: \"What is willpower?\" Most people, sadly, think of it only as the ability to clench their teeth and resist attractive temptations. In this view, willpower means self- denial and no fun. No wonder people hope to make changes without it.","zh":"你可能见过一些广告大肆宣扬无需任何意志力就能改变习惯的方法。但你真的能够在没有意志力的情况下改掉坏习惯或养成好习惯吗?要回答这个问题,我们首先必须问:“什么是意志力?”遗憾的是,大多数人只把它看作咬紧牙关、抵制诱人诱惑的能力。在这种看法中,意志力意味着自我克制和毫无乐趣。难怪人们希望不借助意志力就能做出改变。"},{"en":"I define willpower as \"using only the thought of your motivators to control your actions.\" Let's say your motivators are \"prevent diabetes\" and \"reach a healthy weight\". So if you are at the all-you-can-eat buffet, you think about your motivator—avoid diabetes through weight loss—and you take small portions and avoid the dessert table.","zh":"我把意志力定义为“仅凭想到自己的动机来控制行为”。假设你的动机是“预防糖尿病”和“达到健康体重”。那么,当你在自助餐厅面对不限量供应的食物时,你会想到自己的动机——通过减重来避免糖尿病——于是少量取食,并避开甜点区。"},{"en":"So, amazingly enough, willpower begins with a thought—a bright idea—some way to improve your life or contribute to others. This bright idea is your motivator.","zh":"所以,令人惊讶的是,意志力始于一个想法——一个改善生活或为他人做出贡献的好主意。这个好主意就是你的动机。"},{"en":"Doctor Walter Mischel, an expert on willpower skills, uses the expressive term \"a burning goal\". Whether you call it a motivator, a burning goal, or a bright idea, this idea is the force behind your willpower.","zh":"意志力技能专家沃尔特·米歇尔博士使用了“一个燃烧的目标”这一生动的说法。无论你把它称为动机、燃烧的目标,还是好主意,这个想法都是意志力背后的力量。"},{"en":"What sort of bright ideas—motivators—make for effective willpower? In fact, any goal that you value strongly counts. The list may include good health, self-respect, a better future for your family, a personal mission and being a role model for your child. All these can certainly drive a positive change.","zh":"什么样的好主意——也就是动机——能够产生有效的意志力?事实上,任何一个你高度重视的目标都算在内。这个清单可能包括良好的健康状况、自尊、为家人创造更美好的未来、个人使命,以及成为孩子的榜样。所有这些都确实能够推动积极的改变。"}],"questions":[{"no":12,"type":"细节题","prompt":"What methods do some advertisements trumpet about changing a habit?","options":[{"label":"A","text":"Those involving no self-recognition.","zh":"不涉及自我认知的方法。"},{"label":"B","text":"Those forcing us to clench our teeth.","zh":"迫使我们咬紧牙关的方法。"},{"label":"C","text":"Those resisting various temptations.","zh":"抵制各种诱惑的方法。"},{"label":"D","text":"Those requiring no willpower at all.","zh":"完全不需要意志力的方法。"}],"answer":"D","evidence":"You may have seen advertisements trumpeting methods of changing a habit that require\nabsolutely no willpower whatsoever.\n你可能见过一些广告,大肆宣扬改变习惯的方法完全不需要任何意志力。","signal":"开篇直接陈述广告内容。录音开头用 advertisements trumpeting methods of changing\na habit that require absolutely no willpower whatsoever 直接抛出广告的说法,随后才\n设问反驳,故首句即答案句。","paraphrase":"require absolutely no willpower whatsoever ↔Those requiring no willpower at all.\n同义替换:absolutely no ... whatsoever = no ... at all","explanation":"【信号】开篇直接陈述广告内容。录音开头用 advertisements trumpeting methods of changing\na habit that require absolutely no willpower whatsoever 直接抛出广告的说法,随后才\n设问反驳,故首句即答案句。\n【替换】require absolutely no willpower whatsoever ↔Those requiring no willpower at all.\n同义替换:absolutely no ... whatsoever = no ... at all\n【排除】A"},{"no":13,"type":"细节题","prompt":"What does the speaker define willpower as?","options":[{"label":"A","text":"Regulating one's actions for the sake of good health.","zh":"为了身体健康而调节自己的行为。"},{"label":"B","text":"Controlling one's actions with a motivating thought.","zh":"用激励性的想法控制自己的行为。"},{"label":"C","text":"Using practical examples to guide one's behavior.","zh":"用实际案例指导自己的行为。"},{"label":"D","text":"Denying oneself any comfort to prevent diseases.","zh":"拒绝给自己任何舒适享受,以预防疾病。"}],"answer":"B","evidence":"I define willpower as \"using only the thought of your motivators to control your actions.\"\n我把意志力定义为“只用你的动力念头来控制你的行为”。","signal":"定义句 I define ... as。原文用 I define willpower as 明确给出说话者的定义,其后引号内\n容即为答案。","paraphrase":"using only the thought of your motivators to control your actions ↔\nControlling one's actions with a motivating thought.\n同义替换:thought of your motivators = motivating thought;control your actions =\ncontrolling one's actions","explanation":"【信号】定义句 I define ... as。原文用 I define willpower as 明确给出说话者的定义,其后引号内\n容即为答案。\n【替换】using only the thought of your motivators to control your actions ↔\nControlling one's actions with a motivating thought.\n同义替换:thought of your motivators = motivating thought;control your actions =\ncontrolling one's actions\n【排除】A"},{"no":14,"type":"细节题","prompt":"What may sound amazing enough as regards willpower?","options":[{"label":"A","text":"It equips us with an expert skill.","zh":"它赋予我们一项专业技能。"},{"label":"B","text":"It exerts an enduring force on us.","zh":"它对我们施加持久的力量。"},{"label":"C","text":"It leads to a burning goal.","zh":"它促成一个强烈的目标。"},{"label":"D","text":"It begins with a bright idea.","zh":"它始于一个绝妙的想法。"}],"answer":"D","evidence":"So, amazingly enough, willpower begins with a thought—a bright idea—some way to\nimprove your life or contribute to others.\n因此,令人惊讶的是,意志力始于一个念头——一个绝妙的想法——某种改善你生活或帮助\n他人的方式。","signal":"评价副词 amazingly enough + 结论动词 begins with。原文用 amazingly enough,\nwillpower begins with a thought 直接回应题干的 sound amazing,其后 a bright idea\n是同位解释。","paraphrase":"willpower begins with a thought—a bright idea ↔It begins with a bright idea.\n同义替换:a thought—a bright idea 概括为 a bright idea","explanation":"【信号】评价副词 amazingly enough + 结论动词 begins with。原文用 amazingly enough,\nwillpower begins with a thought 直接回应题干的 sound amazing,其后 a bright idea\n是同位解释。\n【替换】willpower begins with a thought—a bright idea ↔It begins with a bright idea.\n同义替换:a thought—a bright idea 概括为 a bright idea\n【排除】A"},{"no":15,"type":"细节题","prompt":"What does the speaker say may make for effective willpower?","options":[{"label":"A","text":"Any cherished goal.","zh":"任何珍视的目标。"},{"label":"B","text":"Any positive mindset.","zh":"任何积极的心态。"},{"label":"C","text":"Any personal instinct.","zh":"任何个人本能。"},{"label":"D","text":"Any valued role model.","zh":"任何受重视的榜样。"}],"answer":"A","evidence":"What sort of bright ideas—motivators—make for effective willpower? In fact, any goal that\nyou value strongly counts.\n什么样的绝妙想法——动力——能造就有效的意志力?事实上,任何你强烈珍视的目标都\n算数。","signal":"设问自答 + in fact 强调。原文先用 What sort of bright ideas—motivators—make for\neffective willpower? 抛出题干,再用 In fact, any goal that you value strongly counts\n给出答案,in fact 是答案信号。","paraphrase":"any goal that you value strongly counts ↔Any cherished goal.\n同义替换:value strongly = cherished;goal 直接对应","explanation":"【信号】设问自答 + in fact 强调。原文先用 What sort of bright ideas—motivators—make for\neffective willpower? 抛出题干,再用 In fact, any goal that you value strongly counts\n给出答案,in fact 是答案信号。\n【替换】any goal that you value strongly counts ↔Any cherished goal.\n同义替换:value strongly = cherished;goal 直接对应\n【排除】B"}]},{"id":"2026-06-1-s5","section":"Section C","title":"Recording 1 (Q16–18)","qRange":[16,18],"audio":"audio/listening/202606_set1.mp3","fullTrack":true,"bilingual":[{"en":"For many pregnant women, understanding what seafood is safe and healthy and what should be avoided because of mercury concerns comes with a lot of worrying. In part, that's because the federal government's advice on the matter, first issued in 2004, has long been criticized as vague. That guidance has included advice on how much seafood to eat, and which species pregnant and breastfeeding women should avoid over concerns about mercury contamination. But critics say the government advisory has done more harm than good, scaring many pregnant and breastfeeding women away from eating seafood altogether.","zh":"对许多孕妇来说,了解哪些海产品安全且有益健康,以及哪些海产品因担心汞而应当避免,会带来许多忧虑。部分原因在于,联邦政府首次于2004年发布的相关建议长期以来一直被批评含糊不清。该指导意见包括关于应食用多少海产品,以及孕妇和哺乳期女性因担心汞污染而应避免哪些种类的建议。但批评者表示,政府的这份指导意见弊大于利,使许多孕妇和哺乳期女性彻底不敢食用海产品。"},{"en":"The problem is real. According to a spokesman for the Food and Drug Administration, or FDA for short, the agency analyzed fish consumption data from more than 1,000 pregnant women in the US and found that 21 per cent of them ate no fish whatsoever in the previous month. And those who did eat fish consumed far less than recommended by the dietary guidelines. Some 50 per cent ate less than two ounces a week and 75 per cent ate less than four ounces.","zh":"这个问题确实存在。据美国食品药品监督管理局(简称FDA)一位发言人介绍,该机构分析了美国一千多名孕妇的鱼类食用数据,发现其中21%在前一个月完全没有吃鱼。而那些吃鱼的人,摄入量也远低于膳食指南的建议。约50%的人每周摄入量少于两盎司,75%的人少于四盎司。"},{"en":"This week the FDA issued an update to the advice, listing more than sixty species in a chart that ranks fish as A Best Choice, Good Choice and Choices to Avoid. The goal is to make it easier for mothers-to-be to feel confident about the type of seafood they include in their diets. The new advice recommends consumers choose a variety of fish to eat, and it comes with an easy-to-understand illustration of what an appropriate portion size should be—four ounces for an adult and two ounces for children aged four to seven.","zh":"本周,FDA更新了相关建议,在一张图表中列出六十多种鱼类,并将其分为“最佳选择”“不错的选择”和“应避免的选择”。此举旨在让准妈妈更容易对自己饮食中所摄入的海产品种类感到放心。新建议推荐消费者食用多种鱼类,并配有一幅易于理解的图示,说明适当的食用分量应为多少:成年人四盎司,四至七岁的儿童两盎司。"},{"en":"And while expectant mothers have long been warned to stay away from shark and four other particular types of fish from the Gulf of Mexico, now there are three new species on the list of what to avoid. But not everyone is thrilled with the new advice. Critics say the new advice doesn't always agree with the agency's own scientific findings. While mercury is of great concern when people are talking about pregnant women and seafood, it's not the only factor contributing to anxiety.","zh":"长期以来,准妈妈一直被告诫要避开鲨鱼以及另外四种来自墨西哥湾的特定鱼类,而现在,又有三种鱼类被列入应避免食用的名单。但并非所有人都对这份新建议感到满意。批评者表示,新建议并不总是与该机构自己的科学研究结果一致。人们谈论孕妇和海产品时,汞确实是非常令人担忧的因素,但它并不是导致焦虑的唯一因素。"},{"en":"The FDA maintains that its final consumption recommendations were based on thorough scientific analysis. Agency spokesman Cassell says the FDA believes their recommendations will increase confidence, not uncertainty. But critics disagree. They think the FDA's advice is not based on the evidence in its own detailed report, and so it confuses everyone.","zh":"FDA坚持认为,其最终的食用建议是基于全面的科学分析制定的。该机构发言人Cassell表示,FDA相信这些建议将增强信心,而不是增加不确定性。但批评者对此并不认同。他们认为,FDA的建议并没有以其自身那份详细报告中的证据为依据,因此让所有人都感到困惑。"}],"questions":[{"no":16,"type":"细节题","prompt":"What does the speaker say about the federal government's advice on seafood safety?","options":[{"label":"A","text":"It has long been criticized as unclear.","zh":"长期以来一直被批评为表述不清。"},{"label":"B","text":"It has long been ignored by the public.","zh":"长期以来一直被公众忽视。"},{"label":"C","text":"It has caused much panic among women.","zh":"在女性中引发了极大的恐慌。"},{"label":"D","text":"It has resulted in different understandings.","zh":"导致了不同的理解。"}],"answer":"A","evidence":"In part, that's because the federal government's advice on the matter, first issued in 2004, has\nlong been criticized as vague.\n部分原因在于,联邦政府关于这一问题的建议(2004年首次发布)长期以来一直被批评为含\n糊不清。","signal":"篇章首段点题+评价词vague。录音开篇先讲孕妇的困扰,随后用the federal\ngovernment's advice...has long been criticized as vague直接点出建议的评价,正是题\n干所问。","paraphrase":"has long been criticized as vague ↔It has long been criticized as unclear.\nvague=unclear同义替换\nthe federal government's advice ↔It\n机构名词用代词回指","explanation":"【信号】篇章首段点题+评价词vague。录音开篇先讲孕妇的困扰,随后用the federal\ngovernment's advice...has long been criticized as vague直接点出建议的评价,正是题\n干所问。\n【替换】has long been criticized as vague ↔It has long been criticized as unclear.\nvague=unclear同义替换\nthe federal government's advice ↔It\n机构名词用代词回指\n【排除】B"},{"no":17,"type":"细节题","prompt":"What did the Food and Drug Administration do this week?","options":[{"label":"A","text":"It warned consumers not to eat fish from the Gulf of Mexico.","zh":"警告消费者不要食用来自墨西哥湾的鱼。"},{"label":"B","text":"It called on expectant mothers to pay attention to food safety.","zh":"呼吁孕妇关注食品安全。"},{"label":"C","text":"It issued an update to the advice on seafood consumption.","zh":"发布了关于食用海产品建议的更新内容。"},{"label":"D","text":"It listed more than sixty species of fish as \"choices to avoid\".","zh":"将六十多种鱼列为“应避免的选择”。"}],"answer":"C","evidence":"This week the FDA issued an update to the advice, listing more than sixty species in a chart\nthat ranks fish as A Best Choice, Good Choice and Choices to Avoid.\n本周FDA发布了对该建议的更新,列出60多种鱼类,并按'最佳选择'、'良好选择'和'应避免\n选择'进行分级。","signal":"时间信号this week+动作issued。题干问this week FDA做了什么,录音用This week\nthe FDA issued an update to the advice直接给出答案,this week与issued构成强定位\n信号。","paraphrase":"the FDA issued an update to the advice ↔\nIt issued an update to the advice on seafood consumption.\n动作短语原词复现+主题范畴概括","explanation":"【信号】时间信号this week+动作issued。题干问this week FDA做了什么,录音用This week\nthe FDA issued an update to the advice直接给出答案,this week与issued构成强定位\n信号。\n【替换】the FDA issued an update to the advice ↔\nIt issued an update to the advice on seafood consumption.\n动作短语原词复现+主题范畴概括\n【排除】A"},{"no":18,"type":"细节题","prompt":"According to the speaker, what are people concerned about regarding pregnant women\nand seafood?","options":[{"label":"A","text":"The impact of the FDA's analysis.","zh":"美国食品药品监督管理局分析的影响。"},{"label":"B","text":"Multiple factors including mercury.","zh":"包括汞在内的多种因素。"},{"label":"C","text":"Critics' conclusions.","zh":"批评者的结论。"},{"label":"D","text":"The prices of seafood. 懒笔记 · https://english-exam.lazynote.cn/cet6/paper/2026-06-1/?f=p · 在线使用效果更好 blank from a list of choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each choice in the bank is identified by a letter. Please mark the corresponding","zh":"海产品的价格。"}],"answer":"B","evidence":"While mercury is of great concern when people are talking about pregnant women and\nseafood, it's not the only factor contributing to anxiety.\n当人们谈论孕妇与海鲜时,汞固然备受关注,但它并非造成焦虑的唯一因素。","signal":"让步while+否定not the only factor。录音先用mercury is of great concern让步,再用\nit's not the only factor contributing to anxiety转折强调'还有其他因素',正好对应题干\nconcerned about的内容。","paraphrase":"it's not the only factor contributing to anxiety ↔Multiple factors including mercury.\nnot the only factor → multiple factors 同义替换\nmercury is of great concern ↔including mercury\nmercury原词保留","explanation":"【信号】让步while+否定not the only factor。录音先用mercury is of great concern让步,再用\nit's not the only factor contributing to anxiety转折强调'还有其他因素',正好对应题干\nconcerned about的内容。\n【替换】it's not the only factor contributing to anxiety ↔Multiple factors including mercury.\nnot the only factor → multiple factors 同义替换\nmercury is of great concern ↔including mercury\nmercury原词保留\n【排除】A"}]},{"id":"2026-06-1-s6","section":"Section C","title":"Recording 2 (Q19–21)","qRange":[19,21],"audio":"audio/listening/202606_set1.mp3","fullTrack":true,"bilingual":[{"en":"I know you're busy with work, but you also need to take some time off to recharge those batteries. So, should you plan one big vacation for the year, or should you take multiple short vacations throughout? Quantity can sometimes beat quality. First and foremost, regardless of how you use your vacation days, you need to be using them, and soon. The longer you put off your time off, the worse you're making things for yourself.","zh":"我知道你忙于工作,但你也需要抽出一些时间休息,让自己的精力得到恢复。那么,你应该为这一年安排一次长假,还是应该在全年安排多次短假?数量有时胜过质量。首先,无论你如何使用假期,都需要真正使用它们,而且要尽快使用。你越是推迟休假,就越是在让自己的处境变得糟糕。"},{"en":"One 9-year-long study published in Psychosomatic Medicine suggests not taking at least one vacation a year may increase your risk of mortality due to heart disease. So, not only are you killing your joy, you're possibly killing yourself. Give yourself a break, folks.","zh":"《心身医学》发表的一项为期9年的研究表明,每年至少不休一次假,可能会增加因心脏病死亡的风险。所以,你不仅是在扼杀自己的快乐,也可能是在置自己于死地。各位,给自己放个假吧。"},{"en":"When you should take those breaks, however, depends on a few factors: how many days you have available to use, what activities bring you joy, whether you have a family or not, and other variables come into play. Because of that, there's no perfect formula that works for everyone, but there are still a few things everyone can try to shoot for. We know that in terms of maximizing relaxation, you should aim for vacations that range somewhere between 7 and 11 days long. That gives you enough time to let go of your stress at work, completely loosen up, and achieve full-on calm.","zh":"不过,你应该在什么时候休假,取决于几个因素:你有多少天可用假期、哪些活动能给你带来快乐、你是否有家庭,以及其他会产生影响的变量。正因为如此,并不存在适用于所有人的完美公式,但还是有几件事是每个人都可以努力做到的。我们知道,就最大限度地放松而言,你应该争取安排7到11天的假期。这样你就有足够的时间摆脱工作压力,彻底放松下来,达到完全平静的状态。"},{"en":"That above-mentioned study also recommends you space out your vacations evenly instead of using up all of your days at once. Eight days might sound like a lot for someone who only gets 10 days of vacation a year. But if you frame them with weekends, you can manage two evenly spaced 8-day vacations a year. If you have 14 days of paid leave, that's almost three separate 8-day vacations you can use to split your year into thirds.","zh":"上述研究还建议你把假期均匀地分散开来,而不是一次性用完所有假期。对于一年只有10天假期的人来说,8天听起来可能很多。但如果把周末安排在假期前后,你一年就可以安排两次间隔均匀的8天假期。如果你有14天带薪休假,那几乎可以安排三次分别为8天的假期,用来把一年分成三个阶段。"},{"en":"As tempting as it might be to use all your days to take one long summer break, your overall goal should be to achieve the perfect balance between length plus joy and frequency. Vacation frequency is important because planning multiple breaks throughout the year means you always have something to look forward to. Planning things and the anticipation that comes with it tend to make us happier. If you only take one long vacation every year, the excitement builds much more slowly and seems so far off that it can actually lead to feelings of despair.","zh":"尽管把所有假期都用来享受一次漫长的暑假可能很有吸引力,但你的总体目标应该是在假期长度、愉悦感和休假频率之间取得完美平衡。休假频率很重要,因为在全年安排多次休息意味着你总有值得期待的事情。筹划事情以及随之而来的期待往往会让我们更加快乐。如果你每年只休一次长假,兴奋感会积累得慢得多,而且由于假期看起来遥不可及,实际上可能会让人产生绝望感。"}],"questions":[{"no":19,"type":"细节题","prompt":"What does the speaker say about people not taking any vacation?","options":[{"label":"A","text":"They will suffer a breakdown soon.","zh":"他们很快就会崩溃。"},{"label":"B","text":"They will be losing both joy and life.","zh":"他们会同时失去快乐和生活。"},{"label":"C","text":"They will be putting themselves and family at risk.","zh":"他们会将自己和家人置于危险之中。"},{"label":"D","text":"They will make things worse for people around them.","zh":"他们会让身边人的处境变得更糟。"}],"answer":"B","evidence":"One 9-year-long study published in Psychosomatic Medicine suggests not taking at least one\nvacation a year may increase your risk of mortality due to heart disease. So, not only are you\nkilling your joy, you're possibly killing yourself.\n《心理医学》发表的一项长达9年的研究表明,每年至少不休假一次可能会增加死于心脏病\n的风险。所以,你不仅扼杀了自己的快乐,还可能葬送自己的性命。","signal":"研究结论 + so 递进。录音先用 One 9-year-long study suggests... 抛出研究结论,再用\nSo, not only are you killing your joy, you're possibly killing yourself 递进强调后果,其\n中 not only...but(also)结构把 joy 和 life(killing yourself)并置,正是答案句。","paraphrase":"not only are you killing your joy, you're possibly killing yourself ↔\nThey will be losing both joy and life\n同义替换:killing joy → losing joy;possibly killing yourself → losing life","explanation":"【信号】研究结论 + so 递进。录音先用 One 9-year-long study suggests... 抛出研究结论,再用\nSo, not only are you killing your joy, you're possibly killing yourself 递进强调后果,其\n中 not only...but(also)结构把 joy 和 life(killing yourself)并置,正是答案句。\n【替换】not only are you killing your joy, you're possibly killing yourself ↔\nThey will be losing both joy and life\n同义替换:killing joy → losing joy;possibly killing yourself → losing life\n【排除】A"},{"no":20,"type":"细节题","prompt":"What does the 9-year study recommend people do when planning vacations?","options":[{"label":"A","text":"Spend 14 days for vacation every year.","zh":"每年花14天度假。"},{"label":"B","text":"Aim for three separate vacations yearly.","zh":"每年争取安排三次彼此分开的假期。"},{"label":"C","text":"Space out their vacations evenly instead of taking one long vacation.","zh":"把假期均匀分散开来,而不是一次休一个长假。"},{"label":"D","text":"Use all their days off for a long summer break to achieve full-on calm.","zh":"把所有休假日都用来享受一个漫长的暑假,以获得彻底的放松。"}],"answer":"C","evidence":"That above-mentioned study also recommends you space out your vacations evenly instead of\nusing up all of your days at once.\n上述研究还建议你不要把假期一次性用完,而是均匀地分散开来安排。","signal":"recommends + instead of 建议结构。录音中 recommends you space out your\nvacations evenly instead of using up all of your days at once 直接给出研究建议,\nrecommends 与 instead of 的对照标志答案落点。","paraphrase":"space out your vacations evenly instead of using up all of your days at once ↔\nSpace out their vacations evenly instead of taking one long vacation\n同义改写:space out evenly 直接对应;using up all days at once 转述为 taking one long\nvacation","explanation":"【信号】recommends + instead of 建议结构。录音中 recommends you space out your\nvacations evenly instead of using up all of your days at once 直接给出研究建议,\nrecommends 与 instead of 的对照标志答案落点。\n【替换】space out your vacations evenly instead of using up all of your days at once ↔\nSpace out their vacations evenly instead of taking one long vacation\n同义改写:space out evenly 直接对应;using up all days at once 转述为 taking one long\nvacation\n【排除】A"},{"no":21,"type":"细节题","prompt":"Why is vacation frequency important according to the speaker?","options":[{"label":"A","text":"Expecting to have more vacations in a year will boost one's work efficiency.","zh":"期待一年中有更多假期会提高一个人的工作效率。"},{"label":"B","text":"Anticipating more vacations would reduce one's feelings of despair at work.","zh":"期待有更多假期会减轻一个人在工作中的绝望感。"},{"label":"C","text":"Taking more than three vacations yearly would prolong one's excitement.","zh":"每年休假超过三次会延长一个人的兴奋感。"},{"label":"D","text":"Planning multiple breaks throughout the year will add to one's happiness.","zh":"计划在一年中安排多次休息会增加一个人的幸福感。"}],"answer":"D","evidence":"Vacation frequency is important because planning multiple breaks throughout the year means\nyou always have something to look forward to. Planning things and the anticipation that\ncomes with it tend to make us happier.\n休假频率之所以重要,是因为一年中计划多次休息意味着你总有盼头。计划事情以及随之而\n来的期待往往会让我们更快乐。","signal":"because 直接解释原因 + 评价词 happier。录音先以 Vacation frequency is important\nbecause planning multiple breaks throughout the year means you always have\nsomething to look forward to 点明因果,再用 the anticipation that comes with it\ntend to make us happier 给出积极评价,because 后内容即答案。","paraphrase":"planning multiple breaks throughout the year means you always have something to look forward to\n↔Planning multiple breaks throughout the year will add to one's happiness\n同义改写:planning multiple breaks throughout the year 原样对应;have something to look\nforward to + make us happier → add to one's happiness\nthe anticipation that comes with it tend to make us happier ↔\nPlanning multiple breaks throughout the year will add to one's happiness\n同义改写:anticipation/tend to make us happier 对应 add to one's happiness","explanation":"【信号】because 直接解释原因 + 评价词 happier。录音先以 Vacation frequency is important\nbecause planning multiple breaks throughout the year means you always have\nsomething to look forward to 点明因果,再用 the anticipation that comes with it\ntend to make us happier 给出积极评价,because 后内容即答案。\n【替换】planning multiple breaks throughout the year means you always have something to look forward to\n↔Planning multiple breaks throughout the year will add to one's happiness\n同义改写:planning multiple breaks throughout the year 原样对应;have something to look\nforward to + make us happier → add to one's happiness\nthe anticipation that comes with it tend to make us happier ↔\nPlanning multiple breaks throughout the year will add to one's happiness\n同义改写:anticipation/tend to make us happier 对应 add to one's happiness\n【排除】A"}]},{"id":"2026-06-1-s7","section":"Section C","title":"Recording 3 (Q22–25)","qRange":[22,25],"audio":"audio/listening/202606_set1.mp3","fullTrack":true,"bilingual":[{"en":"Autonomous cars that can take over from drivers if they are tired or caught in the heat of an argument are being developed in Sweden. Researchers working as part of the European Union's €77 billion research program are developing sensor-based systems that monitor whether a driver is distracted, anxious or tired. If a driver is not in a fit state to be on the road, the car automatically takes control of the wheel to prevent accidents. Doctor Anna Anund from the Swedish National Road and Transport Research Institute, who is leading the project, said a driver's state can be measured using a number of sensors, including heart rate monitors and eye sensors, which track where a driver's gaze is. She said the aim was to really make sure that the transition from the driver to the vehicle is done in a safe way, so we can take into consideration the driver's state, and so we do not give control to a driver who is under pressure of fatigue, stress, anxiety, and so on.","zh":"在瑞典,人们正在研发能够在驾驶员疲劳或陷入激烈争论时接替其驾驶的自动驾驶汽车。作为欧盟770亿欧元研究计划一部分开展工作的研究人员,正在开发基于传感器的系统,用于监测驾驶员是否分心、焦虑或疲劳。如果驾驶员的状态不适合上路,汽车会自动接管方向盘,以防止发生事故。负责该项目的瑞典国家道路与运输研究所安娜·阿农博士表示,可以利用多种传感器测量驾驶员的状态,包括心率监测器和眼部传感器,后者可以追踪驾驶员的视线方向。她说,目标是真正确保从驾驶员到车辆的控制权转换以安全的方式完成,这样我们就能考虑到驾驶员的状态,也不会把控制权交给正承受疲劳、压力、焦虑等影响的驾驶员。"},{"en":"According to data from the European Commission, Sweden has the safest roads in the EU, with the UK a close second. However, the number of road accidents in both has largely levelled out since 2010. Driver fatigue is thought to be responsible for as many as a fifth of road crashes across the EU, although there are certain times of the day when more accidents happen. At 6:00 a.m., for example, drivers are said to be 20 times more likely to have an accident than at 10:00 a.m. While most experts agree driverless technology should help bring down accident numbers in the long term, some have questioned whether it is safe.","zh":"根据欧盟委员会的数据,瑞典拥有欧盟最安全的道路,英国紧随其后。不过,自2010年以来,两国的道路事故数量基本趋于平稳。据认为,驾驶员疲劳要对欧盟范围内多达五分之一的道路事故负责,尽管一天中某些时段发生的事故更多。例如,据称驾驶员在早上6点发生事故的可能性是在上午10点时的20倍。尽管大多数专家都认为,从长远来看,无人驾驶技术应有助于降低事故数量,但一些人质疑其是否安全。"},{"en":"The researchers have said the technology they are developing is seeking to bridge the gap between Level 3 on the autonomy scale, in which drivers have to be ready to take control of the car at any point, and Level 4, in which driving is automated.","zh":"研究人员表示,他们正在开发的技术旨在弥合自动驾驶等级体系中第3级与第4级之间的差距:在第3级,驾驶员必须随时准备接管汽车;而在第4级,驾驶过程实现自动化。"},{"en":"Daniel Ruiz, the chief executive of the UK's connected and autonomous vehicle programme Meridian, said: \"there is a strong debate going on about how it is possible to make a Level 3 car completely safe.\" Despite advances in technology, we still have some way to go in shifting public sentiment. With an increase in attention-grabbing accidents recently, drivers now view self-driving cars as less safe than they used to.","zh":"英国互联与自动驾驶汽车项目Meridian的首席执行官丹尼尔·鲁伊斯说:“关于如何让第3级汽车完全安全,目前正在展开激烈的讨论。”尽管技术取得了进步,但要改变公众的看法,我们仍有一段路要走。随着近期引人关注的事故增多,如今驾驶员认为自动驾驶汽车不如过去安全。"}],"questions":[{"no":22,"type":"细节题","prompt":"What are researchers doing in Sweden?","options":[{"label":"A","text":"Surveying when drivers are caught in the heat of arguments.","zh":"调查驾驶员陷入激烈争论时的情况。"},{"label":"B","text":"Designing devices to prevent drivers from being distracted.","zh":"设计防止驾驶员分心的设备。"},{"label":"C","text":"Testing models for monitoring drivers easily getting tired.","zh":"测试用于监测容易疲劳驾驶员的模型。"},{"label":"D","text":"Developing sensor-based systems for autonomous vehicles.","zh":"开发用于自动驾驶车辆的基于传感器的系统。"}],"answer":"D","evidence":"Researchers working as part of the European Union's €77 billion research program are\ndeveloping sensor-based systems that monitor whether a driver is distracted, anxious or tired.\n作为欧盟 770 亿欧元研究项目的一部分,研究人员正在开发传感系统,用以监测驾驶员是否\n分心、焦虑或疲劳。","signal":"题干关键词原词复现+直接动作句。题干中的 researchers 与 doing 在 Researchers\nworking as part of the European Union's €77 billion research program are\ndeveloping sensor-based systems 中原词出现,developing 直接回答“做什么”,因此该\n句即为答案句。","paraphrase":"developing sensor-based systems that monitor whether a driver is distracted, anxious or tired ↔\nDeveloping sensor-based systems for autonomous vehicles.\n核心动宾原词复现+目的同义","explanation":"【信号】题干关键词原词复现+直接动作句。题干中的 researchers 与 doing 在 Researchers\nworking as part of the European Union's €77 billion research program are\ndeveloping sensor-based systems 中原词出现,developing 直接回答“做什么”,因此该\n句即为答案句。\n【替换】developing sensor-based systems that monitor whether a driver is distracted, anxious or tired ↔\nDeveloping sensor-based systems for autonomous vehicles.\n核心动宾原词复现+目的同义\n【排除】A"},{"no":23,"type":"目的题","prompt":"What did the researchers' project aim to do according to Dr. Anna Anund?","options":[{"label":"A","text":"Make sure the autonomous vehicle operates in the simplest manner.","zh":"确保自动驾驶车辆以最简便的方式运行。"},{"label":"B","text":"Ensure the transition from the driver to the vehicle is safely made.","zh":"确保从驾驶员驾驶过渡到车辆驾驶能够安全完成。"},{"label":"C","text":"Alleviate the driver's pressure as much as possible.","zh":"尽可能减轻驾驶员的压力。"},{"label":"D","text":"Record the driver's state as accurately as possible.","zh":"尽可能准确地记录驾驶员的状态。"}],"answer":"B","evidence":"She said the aim was to really make sure that the transition from the driver to the vehicle is\ndone in a safe way, so we can take into consideration the driver's state, and so we do not give\ncontrol to a driver who is under pressure of fatigue, stress, anxiety, and so on.\n她说,项目的目标是真正确保从驾驶员到车辆的接管过程以安全方式完成,从而把驾驶员状\n态纳入考量,避免把控制权交给处于疲劳、压力、焦虑等状态下的驾驶员。","signal":"the aim was to 目的信号+make sure 强调。the aim was to really make sure that the\ntransition from the driver to the vehicle is done in a safe way 中,the aim was to 直\n接对应题干 aim,make sure 强调目标,其后内容即为答案。","paraphrase":"the transition from the driver to the vehicle is done in a safe way ↔\nEnsure the transition from the driver to the vehicle is safely made.\n同义改写+主被动转换","explanation":"【信号】the aim was to 目的信号+make sure 强调。the aim was to really make sure that the\ntransition from the driver to the vehicle is done in a safe way 中,the aim was to 直\n接对应题干 aim,make sure 强调目标,其后内容即为答案。\n【替换】the transition from the driver to the vehicle is done in a safe way ↔\nEnsure the transition from the driver to the vehicle is safely made.\n同义改写+主被动转换\n【排除】A"},{"no":24,"type":"细节题","prompt":"What is thought to be responsible for a fifth of road accidents across the\nEuropean Union?","options":[{"label":"A","text":"Driver fatigue.","zh":"驾驶员疲劳。"},{"label":"B","text":"Dreadful traffic.","zh":"糟糕的交通状况。"},{"label":"C","text":"Drunk driving.","zh":"酒后驾车。"},{"label":"D","text":"Driving time.","zh":"驾驶时间。"}],"answer":"A","evidence":"Driver fatigue is thought to be responsible for as many as a fifth of road crashes across the\nEU, although there are certain times of the day when more accidents happen.\n据认为,驾驶员疲劳导致了欧盟多达五分之一的道路撞车事故,尽管一天中某些时段事故\n更多。","signal":"题干关键词原词复现+主语即答案。responsible for as many as a fifth of road crashes\nacross the EU 与题干 responsible for a fifth of road accidents across the European\nUnion 几乎原词对应,其主语 Driver fatigue 就是答案。","paraphrase":"Driver fatigue is thought to be responsible for as many as a fifth of road crashes across the EU ↔\nDriver fatigue.\n主语直接对应,其余为题干已知信息","explanation":"【信号】题干关键词原词复现+主语即答案。responsible for as many as a fifth of road crashes\nacross the EU 与题干 responsible for a fifth of road accidents across the European\nUnion 几乎原词对应,其主语 Driver fatigue 就是答案。\n【替换】Driver fatigue is thought to be responsible for as many as a fifth of road crashes across the EU ↔\nDriver fatigue.\n主语直接对应,其余为题干已知信息\n【排除】B"},{"no":25,"type":"细节题","prompt":"Why do drivers now view self-driving cars as less safe than they used to?","options":[{"label":"A","text":"There has been a strong debate on the feasibility of Level 3 cars.","zh":"围绕3级自动驾驶汽车的可行性展开了激烈争论。"},{"label":"B","text":"There have been few remarkable advances in auto technology.","zh":"汽车技术方面鲜有显著进步。"},{"label":"C","text":"There has been a rise in attention-grabbing accidents recently.","zh":"近期引人关注的事故有所增加。"},{"label":"D","text":"There have been few feasible ways to shift public sentiment.","zh":"转变公众看法的可行方法很少。"}],"answer":"C","evidence":"With an increase in attention-grabbing accidents recently, drivers now view self-driving cars\nas less safe than they used to.\n随着近期引人注目的交通事故增多,驾驶员现在认为自动驾驶汽车不如以前安全。","signal":"With 引导原因状语,直接解释结果。With an increase in attention-grabbing accidents\nrecently 位于结果句 “drivers now view self-driving cars as less safe than they used to”\n之前,with 短语说明原因。","paraphrase":"an increase in attention-grabbing accidents recently ↔\nThere has been a rise in attention-grabbing accidents recently.\n同义替换:increase→rise","explanation":"【信号】With 引导原因状语,直接解释结果。With an increase in attention-grabbing accidents\nrecently 位于结果句 “drivers now view self-driving cars as less safe than they used to”\n之前,with 短语说明原因。\n【替换】an increase in attention-grabbing accidents recently ↔\nThere has been a rise in attention-grabbing accidents recently.\n同义替换:increase→rise\n【排除】A"}]}]},{"id":"2026-06-2","title":"2026年6月 六级第2套（最新真题 · 含逐段双语听稿）","year":"2026.06","exam":"六级 CET-6","totalQuestions":25,"audioMode":"full","fullAudio":"audio/listening/202606_set2.mp3","sections":[{"id":"2026-06-2-s1","section":"Section A","title":"Conversation 1 (Q1–4)","qRange":[1,4],"audio":"audio/listening/202606_set2.mp3","fullTrack":true,"bilingual":[{"en":"W: Hi, Frank, are you working through your lunch hour again?","zh":"W: 嗨,弗兰克,你又在午餐时间工作吗?"},{"en":"M: No, not at all. It's my 10th wedding anniversary next week, and I promised Jane that I would book a city break for us, as I have annual leave to take, and it would be nice to celebrate somewhere warm. So, I'm trying to book something in Barcelona.","zh":"M: 不,完全不是。我和简下周要过结婚十周年纪念日了,我答应过她要为我们预订一次城市短途旅行,因为我还有年假要休,而且能找个温暖的地方庆祝一下也不错。所以,我正在设法预订去巴塞罗那的行程。"},{"en":"W: That sounds so romantic. I adore Barcelona. It's such a fabulous cosmopolitan city. There's so much to do there, excellent food, and that cathedral that they are still building after about 150 years. Very cool.","zh":"W: 听起来真浪漫。我非常喜欢巴塞罗那。那是一座非常棒的国际化城市。那里有很多事情可做,美食也很棒,还有那座已经修建了大约150年、至今仍在建造的教堂。太酷了。"},{"en":"M: I know. But the anniversary is looming, and I'm still scrambling to find accommodation. Everything is either wildly expensive or already fully booked. I'm starting to feel a bit frantic.","zh":"M: 我知道。但纪念日就要到了,我还在手忙脚乱地找住宿。要么贵得离谱,要么已经全部订满。我开始有点慌了。"},{"en":"W: Well, if you are going for a whole week, why don't you do a couple of nights in somewhere really glamorous, and then do the rest of the week a bit further up the coast, where the accommodation is cheaper, and that will offset the cost of the expensive place?","zh":"W: 这样吧,如果你们要去整整一周,为什么不先在一个非常豪华的地方住几个晚上,然后把剩下的时间安排在海岸线再往北一点的地方,那里住宿更便宜,这样就能抵消住昂贵地方的费用了?"},{"en":"M: That might be a good plan. It's not too expensive to rent a car, so we could still drive into the city. Yes, there are lots of places outside the city that have pools and are all inclusive, so we wouldn't even need to pay for food or drinks. I'll send a query now about the dates we're interested in.","zh":"M: 这或许是个不错的计划。租车也不算太贵,所以我们还是可以开车进城。对了,城外有很多地方带游泳池,而且提供全包服务,这样我们连吃饭和饮料的钱都不用另外付了。我现在就发个咨询,问问我们感兴趣的日期是否有空。"},{"en":"W: That sounds perfect. I'm sure that Jane will be absolutely thrilled to bits. I really do recommend visiting that cathedral. You can go all the way up to the top of it, but you need to go up a really steep spiral staircase to get there.","zh":"W: 听起来太完美了。我相信简一定会高兴坏的。我真的很推荐去参观那座教堂。你们可以一直登到顶部,但要到那里必须爬一段非常陡的螺旋楼梯。"},{"en":"M: Considering Jane is terrified of heights, I think if I tried to make her do that, I would come back divorced. Thanks for the help though; it was turning into a logistical nightmare.","zh":"M: 考虑到简恐高,我要是想让她去爬那个,我回来时可能就已经离婚了。不过还是谢谢你的帮助;这件事本来都快变成一场后勤噩梦了。"}],"questions":[{"no":1,"type":"细节题","prompt":"What is the man planning to do?","options":[{"label":"A","text":"Celebrate his 10th wedding anniversary.","zh":"庆祝他的结婚十周年纪念日。"},{"label":"B","text":"Celebrate his promotion in Barcelona.","zh":"在巴塞罗那庆祝他的升职。"},{"label":"C","text":"Give his wife a pleasant surprise.","zh":"给他的妻子一个惊喜。"},{"label":"D","text":"Ask for leave to visit Barcelona.","zh":"请假去巴塞罗那。"}],"answer":"A","evidence":"It's my 10th wedding anniversary next week, and I promised Jane that I would book\na city break for us, as I have annual leave to take, and it would be nice to celebrate\nsomewhere warm.\n下周是我结婚十周年纪念日,我答应 Jane 会给我们订一次城市短途旅行,因为我有年假要\n休,而且去个暖和的地方庆祝会很好。","signal":"承诺句+原因铺陈。男士用 I promised Jane that I would book a city break for us 直接\n说明自己的计划,后面 as 引出原因;这是典型的'被问者应答',直接承载答案。","paraphrase":"It's my 10th wedding anniversary next week ↔Celebrate his 10th wedding anniversary.\n事件同义概括\nI promised Jane that I would book a city break for us ↔Celebrate his 10th wedding anniversary.\n计划句→事件目的","explanation":"【信号】承诺句+原因铺陈。男士用 I promised Jane that I would book a city break for us 直接\n说明自己的计划,后面 as 引出原因;这是典型的'被问者应答',直接承载答案。\n【替换】It's my 10th wedding anniversary next week ↔Celebrate his 10th wedding anniversary.\n事件同义概括\nI promised Jane that I would book a city break for us ↔Celebrate his 10th wedding anniversary.\n计划句→事件目的\n【排除】B"},{"no":2,"type":"细节题","prompt":"Why is the man starting to feel a bit frantic?","options":[{"label":"A","text":"He is unable to find some inexpensive accommodation.","zh":"他找不到价格便宜的住宿。"},{"label":"B","text":"There are few warm places to go at this time of the year.","zh":"每年的这个时候,适合去的温暖地方很少。"},{"label":"C","text":"There is so much for him to do before going on vacation.","zh":"在度假之前,他有太多事情要做。"},{"label":"D","text":"He is afraid Barcelona may not be so fabulous as expected.","zh":"他担心巴塞罗那可能没有预期的那么棒。"}],"answer":"A","evidence":"But the anniversary is looming, and I'm still scrambling to find accommodation. Everything is\neither wildly expensive or already fully booked. I'm starting to feel a bit frantic.\n但纪念日越来越近,我还在拼命找住宿。要么贵得离谱,要么已经订满。我开始有点慌了。","signal":"问题铺陈+情绪词。I'm still scrambling to find accommodation 点明困难,Everything\nis either wildly expensive or already fully booked 具体说明,I'm starting to feel a bit\nfrantic 直接回应题干情绪。","paraphrase":"I'm still scrambling to find accommodation ↔\nHe is unable to find some inexpensive accommodation.\n动作+结果同义改写\nEverything is either wildly expensive or already fully booked ↔\nHe is unable to find some inexpensive accommodation.\n反向同义替换","explanation":"【信号】问题铺陈+情绪词。I'm still scrambling to find accommodation 点明困难,Everything\nis either wildly expensive or already fully booked 具体说明,I'm starting to feel a bit\nfrantic 直接回应题干情绪。\n【替换】I'm still scrambling to find accommodation ↔\nHe is unable to find some inexpensive accommodation.\n动作+结果同义改写\nEverything is either wildly expensive or already fully booked ↔\nHe is unable to find some inexpensive accommodation.\n反向同义替换\n【排除】B"},{"no":3,"type":"细节题","prompt":"What does the woman suggest the man do?","options":[{"label":"A","text":"Rent a car to drive into the city and scenic spots so as to save the expenses on transportation.","zh":"租一辆车开进市区并前往景点,以节省交通费用。"},{"label":"B","text":"Spend a couple of nights in a glamorous hotel and the rest of the week in inexpensive places.","zh":"在豪华酒店住几个晚上,其余时间住在价格便宜的地方。"},{"label":"C","text":"Find all-inclusive accommodation to eliminate the need to pay for food and drinks.","zh":"寻找包含所有费用的住宿,这样就不必另外支付食物和饮料的费用。"},{"label":"D","text":"Stay in a hotel away from the coast where the accommodation is less expensive.","zh":"住在远离海岸的酒店,那里的住宿费用较低。"}],"answer":"B","evidence":"Well, if you are going for a whole week, why don't you do a couple of nights in somewhere\nreally glamorous, and then do the rest of the week a bit further up the coast, where the\naccommodation is cheaper, and that will offset the cost of the expensive place?\n嗯,如果你要去一整周,为什么不先找家很华丽的地方住两晚,然后剩下的时间住到海岸更\n北一点的地方,那里住宿更便宜,可以抵消贵地方的费用。","signal":"建议句型 why don't you。why don't you do a couple of nights in somewhere really\nglamorous 是典型的建议句,且该句包含具体方案(住两晚贵的+其余住便宜的),直接对\n应题干。","paraphrase":"do a couple of nights in somewhere really glamorous ↔\nSpend a couple of nights in a glamorous hotel and the rest of the week in inexpensive places.\n同义替换:地点下位化+动词替换\ndo the rest of the week a bit further up the coast, where the accommodation is cheaper ↔\nSpend a couple of nights in a glamorous hotel and the rest of the week in inexpensive places.\n同义替换: cheaper accommodation = inexpensive places","explanation":"【信号】建议句型 why don't you。why don't you do a couple of nights in somewhere really\nglamorous 是典型的建议句,且该句包含具体方案(住两晚贵的+其余住便宜的),直接对\n应题干。\n【替换】do a couple of nights in somewhere really glamorous ↔\nSpend a couple of nights in a glamorous hotel and the rest of the week in inexpensive places.\n同义替换:地点下位化+动词替换\ndo the rest of the week a bit further up the coast, where the accommodation is cheaper ↔\nSpend a couple of nights in a glamorous hotel and the rest of the week in inexpensive places.\n同义替换: cheaper accommodation = inexpensive places\n【排除】A"},{"no":4,"type":"细节题","prompt":"What does the man say about his wife Jane?","options":[{"label":"A","text":",","zh":"她肯定会喜欢那座大教堂。"},{"label":"B","text":",","zh":"她内心是个浪漫的人。"},{"label":"C","text":"and","zh":"她不擅长安排事务。"},{"label":"D","text":". Then mark the corresponding letter on Answer Sheet 1 with a single line through the centre.","zh":"她恐高。"}],"answer":"D","evidence":"Considering Jane is terrified of heights, I think if I tried to make her do that, I would come\nback divorced.\n考虑到 Jane 恐高,我觉得如果我硬让她上去,回来就得离婚了。","signal":"人物评价形容词 terrified。Jane is terrified of heights 直接给出 Jane 的特征,是题干所\n问的答案句。","paraphrase":"Jane is terrified of heights ↔She is scared of heights.\n近义形容词替换","explanation":"【信号】人物评价形容词 terrified。Jane is terrified of heights 直接给出 Jane 的特征,是题干所\n问的答案句。\n【替换】Jane is terrified of heights ↔She is scared of heights.\n近义形容词替换\n【排除】A"}]},{"id":"2026-06-2-s2","section":"Section A","title":"Conversation 2 (Q5–8)","qRange":[5,8],"audio":"audio/listening/202606_set2.mp3","fullTrack":true,"bilingual":[{"en":"W: Hey there, Paul. How's it going?","zh":"W: 嗨,保罗。最近怎么样?"},{"en":"M: Hi, Suzanne. Just keeping busy with the usual stuff, filling prescriptions, talking to patients about their medications, that kind of thing. How about you?","zh":"M: 嗨,苏珊。就是忙着做平常的事,开处方药、和患者聊聊他们的用药情况之类的。你呢?"},{"en":"W: Same here, although I did have an interesting case come in this morning. A patient came in, inquiring about a medication that had a potential interaction with another medication she was already taking.","zh":"W: 我也一样,不过今天早上来了一个挺有意思的病例。一位患者来咨询一种药,而这种药可能会和她已经在服用的另一种药产生相互作用。"},{"en":"M: Oh, that's always tricky. What did you do?","zh":"M: 哦,这种情况总是很棘手。你怎么处理的?"},{"en":"W: I explained the issue to her as best I could, and recommended she double-check with her doctor. And you know what? She actually followed my advice, and the doctor ended up switching the patient's medication.","zh":"W: 我尽可能向她解释了这个问题,并建议她再向医生确认一下。你猜怎么着?她真的听从了我的建议,最后医生给这位患者换了药。"},{"en":"M: Ah, that's great. You must feel quite accomplished.","zh":"M: 啊,那太好了。你一定很有成就感。"},{"en":"W: Totally. These moments are the highlights of my routine work, employing my pharmaceutical expertise to the benefit of people's health and well-being.","zh":"W: 完全是。这些时刻是我日常工作中最精彩的部分,运用我的药学专业知识来促进人们的健康和福祉。"},{"en":"M: I fully agree. Unfortunately, the opposite is true when the patient is too stubborn and they refuse to listen to us.","zh":"M: 我完全同意。遗憾的是,当患者太固执、不肯听我们的话时,情况就正好相反。"},{"en":"W: So true. In other developments, we've had a lot of people coming in to get their flu shots, which is always good to see.","zh":"W: 确实如此。另外,最近有很多人来接种流感疫苗,这总是件令人高兴的事。"},{"en":"M: Good, good. I've been working on a new medication therapy management program for our patients with chronic conditions. It helps patients manage their medications more effectively.","zh":"M: 很好,很好。我一直在为患有慢性疾病的患者制定一个新的药物治疗管理项目,帮助患者更有效地管理他们的用药。"},{"en":"W: That sounds interesting.","zh":"W: 听起来很有意思。"},{"en":"M: We review all of their medications, and make sure that they're taking them as prescribed. We also look for any potential drug interactions or side effects. Patient response has so far been very positive. Some have reported seeing improvements in their health, which is really rewarding to see.","zh":"M: 我们会检查他们所有的药物,确保他们按照处方服用。我们还会查找任何潜在的药物相互作用或副作用。到目前为止,患者的反响非常积极。有些人说自己的健康状况有所改善,看到这一点真的很令人欣慰。"},{"en":"W: That's great to hear. Do you use text message reminders?","zh":"W: 听到这个真好。你们会使用短信提醒吗?"},{"en":"M: Yes, absolutely.","zh":"M: 是的,当然会。"},{"en":"W: It's a great idea. Medication non-adherence is a big problem, especially for older patients.","zh":"W: 这是个很好的主意。用药依从性差是个大问题,尤其是对老年患者来说。"},{"en":"M: We're still in the early stages of the program, but I'm hopeful that it will make a real difference for our patients.","zh":"M: 这个项目还处于早期阶段,但我希望它能真正改善我们患者的情况。"}],"questions":[{"no":5,"type":"细节题","prompt":"What do we learn about the speakers?","options":[{"label":"A","text":"They often share each other's experiences.","zh":"他们经常分享彼此的经历。"},{"label":"B","text":"They enjoy interacting with patients.","zh":"他们喜欢与患者互动。"},{"label":"C","text":"They always do things tricky.","zh":"他们总是把事情做得很棘手。"},{"label":"D","text":"They are both pharmacists.","zh":"他们都是药剂师。"}],"answer":"D","evidence":"Hi, Suzanne. Just keeping busy with the usual stuff, filling prescriptions, talking to patients\nabout their medications, that kind of thing.\n嗨,苏珊娜。就是忙着平常的活儿,配药、跟病人聊他们的用药情况,诸如此类的事。","signal":"工作内容即身份。男性说话者在开场问候后直接描述日常工作:filling prescriptions,\ntalking to patients about their medications,这些正是药剂师的典型职责,从而泄露两\n人身份。","paraphrase":"filling prescriptions, talking to patients about their medications ↔They are both pharmacists\n下位职责→上位职业","explanation":"【信号】工作内容即身份。男性说话者在开场问候后直接描述日常工作:filling prescriptions,\ntalking to patients about their medications,这些正是药剂师的典型职责,从而泄露两\n人身份。\n【替换】filling prescriptions, talking to patients about their medications ↔They are both pharmacists\n下位职责→上位职业\n【排除】A"},{"no":6,"type":"细节题","prompt":"What does the woman say about an interesting case she had?","options":[{"label":"A","text":"The doctor ended up admitting his mistake.","zh":"医生最终承认了自己的错误。"},{"label":"B","text":"The patient consulted another doctor.","zh":"患者向另一位医生进行了咨询。"},{"label":"C","text":"The patient actually took her advice.","zh":"患者实际上采纳了她的建议。"},{"label":"D","text":"The doctor double-checked with her.","zh":"医生向她进行了再次确认。"}],"answer":"C","evidence":"I explained the issue to her as best I could, and recommended she double-check with her\ndoctor. And you know what? She actually followed my advice, and the doctor ended up\nswitching the patient's medication.\n我尽可能向她解释了这个问题,并建议她和医生再确认一下。你知道吗?她真的听从了我的\n建议,医生最终更换了病人的药物。","signal":"强调词后出结果。女士先说建议内容,然后用 And you know what? 引出关键结果,再用\nactually 强调 She actually followed my advice,这是答案落点。","paraphrase":"She actually followed my advice ↔The patient actually took her advice\n同义替换+代词还原","explanation":"【信号】强调词后出结果。女士先说建议内容,然后用 And you know what? 引出关键结果,再用\nactually 强调 She actually followed my advice,这是答案落点。\n【替换】She actually followed my advice ↔The patient actually took her advice\n同义替换+代词还原\n【排除】A"},{"no":7,"type":"细节题","prompt":"What does the man say he has been working on?","options":[{"label":"A","text":"A proposal for applying flu shots more effectively.","zh":"一份关于如何更有效地接种流感疫苗的提案。"},{"label":"B","text":"A new medication therapy management program.","zh":"一个新的药物治疗管理项目。"},{"label":"C","text":"A novel strategy to persuade stubborn patients.","zh":"一种说服固执患者的新策略。"},{"label":"D","text":"A therapy for patients with similar conditions.","zh":"一种针对病情相似患者的治疗方案。"}],"answer":"B","evidence":"Good, good. I've been working on a new medication therapy management program for our\npatients with chronic conditions. It helps patients manage their medications more effectively.\n好,好。我一直在为我们的慢性病病人开发一个新的药物治疗管理项目。它帮助病人更有效\n地管理他们的药物。","signal":"题干关键词复现。题干中的 has been working on 与录音中的 I've been working on 直接\n对应,这是典型的问答同构定位信号,紧跟其后的宾语就是答案。","paraphrase":"I've been working on a new medication therapy management program ↔\nA new medication therapy management program\n直接对应,去掉主谓","explanation":"【信号】题干关键词复现。题干中的 has been working on 与录音中的 I've been working on 直接\n对应,这是典型的问答同构定位信号,紧跟其后的宾语就是答案。\n【替换】I've been working on a new medication therapy management program ↔\nA new medication therapy management program\n直接对应,去掉主谓\n【排除】A"},{"no":8,"type":"细节题","prompt":"What is a big problem, especially for older patients according to the woman?","options":[{"label":"A","text":"Inability to send text messages.","zh":"无法发送短信。"},{"label":"B","text":"Distrust in pharmaceutical experts.","zh":"不信任药学专家。"},{"label":"C","text":"Medication non-adherence.","zh":"不按医嘱服药。"},{"label":"D","text":"Need for constant reminding.","zh":"需要不断提醒。"}],"answer":"C","evidence":"Medication non-adherence is a big problem, especially for older patients.\n用药不依从是一个大问题,尤其对老年患者来说。","signal":"判断句与题干一一对应。女士直接说 Medication non-adherence is a big problem,\nespecially for older patients,与题干 What is a big problem, especially for older\npatients according to the woman? 几乎逐词对应。","paraphrase":"Medication non-adherence is a big problem, especially for older patients ↔\nMedication non-adherence\n原词复现","explanation":"【信号】判断句与题干一一对应。女士直接说 Medication non-adherence is a big problem,\nespecially for older patients,与题干 What is a big problem, especially for older\npatients according to the woman? 几乎逐词对应。\n【替换】Medication non-adherence is a big problem, especially for older patients ↔\nMedication non-adherence\n原词复现\n【排除】A"}]},{"id":"2026-06-2-s3","section":"Section B","title":"Passage 1 (Q9–11)","qRange":[9,11],"audio":"audio/listening/202606_set2.mp3","fullTrack":true,"bilingual":[{"en":"In America, at least, passion is a word that often comes up on job descriptions and in interviews. On the whole, passionate people are thought of in a positive light and considered likely to achieve their goals. But when it comes to predicting achievement, has the importance of passion been overstated?","zh":"至少在美国,求职描述和面试中经常会提到“热情”一词。总的来说,人们对有热情的人持正面看法,认为他们很可能实现自己的目标。但说到预测成就时,热情的重要性是否被夸大了?"},{"en":"According to a new study from Stanford University, passion may be less important in certain cultures, and the fact that passion is often seen as a key to achievement may reflect a distinctly Western model of motivation. The chief factor explored in the study was how individualistic a society was. In individualistic cultures, the researchers assert, people are more motivated by pursuing paths related to their passions, but those in collectivistic cultures are more likely to see themselves as part of a network. They often place fulfilling obligations to others above focusing on their own interests.","zh":"根据斯坦福大学的一项新研究,热情在某些文化中的重要性可能较低,而热情常被视为成就关键这一事实,或许反映了一种明显具有西方特色的动机模式。研究考察的主要因素是一个社会的个人主义程度。研究人员断言,在个人主义文化中,人们更容易受到追求与自身热情相关道路的激励;而集体主义文化中的人则更可能将自己视为某个社会网络的一部分。他们往往更重视履行对他人的义务,而不是专注于自身的兴趣。"},{"en":"The researchers looked at data from nearly 60 countries. They found that in science subjects, passion was positively correlated with academic achievements. Higher levels of enjoyment and interest also bolstered test scores.","zh":"研究人员考察了来自近60个国家的数据。他们发现,在科学类学科中,热情与学业成就呈正相关。更高程度的愉悦感和兴趣也会提高测试成绩。"},{"en":"But the strength of this correlation wasn't the same across cultures. Those in individualistic societies such as the U.S., Australia, and the UK showed a stronger link between passion and achievement. The effect of passion on performance was more subtle for those in more collectivistic societies such as Colombia or Thailand.","zh":"但这种相关性的强度在不同文化之间并不相同。在美国、澳大利亚和英国等个人主义社会中,热情与成就之间的联系更为紧密。而对于哥伦比亚或泰国等更加集体主义的社会而言,热情对表现的影响则更为微妙。"},{"en":"These findings were mirrored in achievement in both mathematics and reading. It's clear from the findings that passion isn't the only thing that motivates people to achieve their goals.","zh":"数学和阅读方面的成就也呈现出同样的情况。从这些研究结果可以清楚看出,热情并不是激励人们实现目标的唯一因素。"}],"questions":[{"no":9,"type":"细节题","prompt":"What are passionate people considered likely to do in America?","options":[{"label":"A","text":"Accomplish their goals.","zh":"实现自己的目标。"},{"label":"B","text":"View things positively.","zh":"积极地看待事物。"},{"label":"C","text":"Overstate their importance.","zh":"夸大自身的重要性。"},{"label":"D","text":"Dominate job interviews.","zh":"在求职面试中占据主导地位。"}],"answer":"A","evidence":"On the whole, passionate people are thought of in a positive light and considered likely to\nachieve their goals.\n总体而言,有热情的人被认为形象正面,且被认为很可能实现他们的目标。","signal":"直接描述句。passionate people are thought of in a positive light and considered\nlikely to achieve their goals是对passionate people的直接定义式描述,题干中的\n『considered likely to』几乎原文复现了该句结构。","paraphrase":"achieve their goals ↔Accomplish their goals.\n同义词替换","explanation":"【信号】直接描述句。passionate people are thought of in a positive light and considered\nlikely to achieve their goals是对passionate people的直接定义式描述,题干中的\n『considered likely to』几乎原文复现了该句结构。\n【替换】achieve their goals ↔Accomplish their goals.\n同义词替换\n【排除】B"},{"no":10,"type":"细节题","prompt":"What does a new study from Stanford show about the importance of passion in\npredicting achievement?","options":[{"label":"A","text":"It reflects a strong sense of obligation to others.","zh":"这反映出对他人有强烈的责任感。"},{"label":"B","text":"It signifies a universal model of motivation.","zh":"这意味着一种普遍适用的动机模式。"},{"label":"C","text":"It may differ in various cultures.","zh":"它可能因文化不同而有所差异。"},{"label":"D","text":"It may have been underestimated.","zh":"它的重要性可能一直被低估。"}],"answer":"C","evidence":"According to a new study from Stanford University, passion may be less important in certain\ncultures, and the fact that passion is often seen as a key to achievement may reflect a\ndistinctly Western model of motivation.\n根据斯坦福大学的一项新研究,热情在某些文化中可能不那么重要,而且热情常被视为成就\n关键这一事实,可能反映的是一种明显西方化的动机模式。","signal":"研究来源+结论句。According to a new study from Stanford University是典型的研究结\n论引导语,其后『passion may be less important in certain cultures』直接回应题干中\n『the importance of passion in predicting achievement』。","paraphrase":"passion may be less important in certain cultures ↔It may differ in various cultures.\n具体→概括\nreflect a distinctly Western model of motivation ↔It may differ in various cultures.\n西方模式≠普世模式","explanation":"【信号】研究来源+结论句。According to a new study from Stanford University是典型的研究结\n论引导语,其后『passion may be less important in certain cultures』直接回应题干中\n『the importance of passion in predicting achievement』。\n【替换】passion may be less important in certain cultures ↔It may differ in various cultures.\n具体→概括\nreflect a distinctly Western model of motivation ↔It may differ in various cultures.\n西方模式≠普世模式\n【排除】A"},{"no":11,"type":"细节题","prompt":"What did the researchers find about the effect of passion on academic achievement for\nthose in more collectivistic societies?","options":[{"label":"A","text":",","zh":"对这方面的研究并不充分。"},{"label":"B","text":",","zh":"这种影响更容易预测。"},{"label":"C","text":"and","zh":"这种影响被视为理所当然。"},{"label":"D","text":". Then mark the corresponding letter on Answer Sheet I with a single line through the centre.","zh":"这种影响更加微妙。"}],"answer":"D","evidence":"The effect of passion on performance was more subtle for those in more collectivistic\nsocieties such as Colombia or Thailand.\n对于那些更具集体主义文化的社会(如哥伦比亚或泰国)的人来说,热情对表现的影响更为\n微妙。","signal":"对比结论句。The effect of passion on performance was more subtle for those in\nmore collectivistic societies直接回应题干中的『the effect of passion on academic\nachievement for those in more collectivistic societies』,『more subtle』是结论\n落点。","paraphrase":"The effect of passion on performance was more subtle for those in more collectivistic societies ↔\nIt was more subtle.\n同义复现","explanation":"【信号】对比结论句。The effect of passion on performance was more subtle for those in\nmore collectivistic societies直接回应题干中的『the effect of passion on academic\nachievement for those in more collectivistic societies』,『more subtle』是结论\n落点。\n【替换】The effect of passion on performance was more subtle for those in more collectivistic societies ↔\nIt was more subtle.\n同义复现\n【排除】A"}]},{"id":"2026-06-2-s4","section":"Section B","title":"Passage 2 (Q12–15)","qRange":[12,15],"audio":"audio/listening/202606_set2.mp3","fullTrack":true,"bilingual":[{"en":"Why does nature create patterns? The reason patterns often appear in nature is simple: the same basic physical or chemical processes occur in many pattern substances and organisms as they form. Whether in plants and animals or rocks, foams and ice crystals, the intricate patterns that happen in nature come down to what's happening at the level of atoms and molecules.","zh":"为什么自然界会形成各种图案?图案之所以经常出现在自然界中,原因很简单:在许多形成图案的物质和生物中,相同的基本物理或化学过程会反复发生。无论是在植物和动物中,还是在岩石、泡沫和冰晶中,自然界中出现的复杂图案,归根结底都与原子和分子层面发生的事情有关。"},{"en":"A pattern in nature is any regularly repeated arrangement of shapes or colors. Some of the most striking examples include the six-sided arrays of rocks at Giant's Causeway in the United Kingdom, and the colorful stripes and spots on tropical fish. Patterns like these begin to form at a small scale when materials undergo processes like drying, freezing, wrinkling, diffusing and reacting. Those changes then give rise to complex patterns at a larger scale that people can see.","zh":"自然界中的图案,是指形状或颜色有规律地重复排列的任何形式。其中一些最引人注目的例子包括英国巨人之路上六边形的岩石阵列,以及热带鱼身上色彩斑斓的条纹和斑点。这类图案在材料经历干燥、冻结、起皱、扩散和反应等过程时,会先在微小尺度上开始形成。随后,这些变化会在更大尺度上产生人们能够看见的复杂图案。"},{"en":"Imagine delicate frozen crystals on a window during winter. What creates that pattern? When water freezes, its molecules begin clustering together. Water molecules have a particular bent shape that causes them to stack into clusters as they freeze. As the cluster grows, many outside factors, including humidity and temperature, begin to affect its overall shape. If the water is freezing on a window, for example, random imperfections on the glass surface affect the stacking and create the larger pattern.","zh":"想象一下冬天窗户上精致的冰晶。是什么形成了这种图案?水结冰时,其中的分子开始聚集在一起。水分子具有特殊的弯曲形状,这使它们在冻结时会堆叠成团。随着团簇不断增大,包括湿度和温度在内的许多外部因素开始影响它的整体形状。例如,如果水是在窗户上结冰,玻璃表面的随机瑕疵就会影响分子的堆叠,并形成更大的图案。"},{"en":"But scientists do not always know the purpose of a pattern, or even if there is one. The molecular processes involved are simple enough that they might generate a pattern by coincidence.","zh":"但科学家并不总是知道某种图案的作用,甚至不知道它是否具有作用。相关的分子过程足够简单,因此它们可能只是偶然形成了某种图案。"}],"questions":[{"no":12,"type":"细节题","prompt":"What does the passage say is a pattern in nature?","options":[{"label":"A","text":"It is any incidental happening in plants and animals or ice crystals.","zh":"它是植物、动物或冰晶中任何偶然发生的现象。"},{"label":"B","text":"It is any basic physical or chemical work in designing substances.","zh":"它是设计物质时进行的任何基本物理或化学过程。"},{"label":"C","text":"It is any symmetrical and colorful stripes or spots on organisms.","zh":"它是生物体上任何对称且色彩斑斓的条纹或斑点。"},{"label":"D","text":"It is any regularly repeated arrangement of shapes or colors.","zh":"它是形状或色彩有规律地重复排列形成的图案。"}],"answer":"D","evidence":"A pattern in nature is any regularly repeated arrangement of shapes or colors.\n自然界中的图案是指形状或颜色的任何有规律重复排列。","signal":"定义句直接作答。句中 A pattern in nature is 是典型的下定义句式,题干问 what is a\npattern,答案直接落在 is 后的表语。","paraphrase":"any regularly repeated arrangement of shapes or colors ↔\nany regularly repeated arrangement of shapes or colors\n原词复现","explanation":"【信号】定义句直接作答。句中 A pattern in nature is 是典型的下定义句式,题干问 what is a\npattern,答案直接落在 is 后的表语。\n【替换】any regularly repeated arrangement of shapes or colors ↔\nany regularly repeated arrangement of shapes or colors\n原词复现\n【排除】A"},{"no":13,"type":"细节题","prompt":"What gives rise to complex patterns at a larger scale?","options":[{"label":"A","text":"Materials undergoing certain processes.","zh":"经历某些过程的材料。"},{"label":"B","text":"Materials exposed to various natural forces.","zh":"受到各种自然力量作用的材料。"},{"label":"C","text":"Materials impacted by any change of molecules.","zh":"受到分子任何变化影响的材料。"},{"label":"D","text":"Materials going through extremely radical transformations.","zh":"经历极其剧烈转变的材料。"}],"answer":"A","evidence":"Patterns like these begin to form at a small scale when materials undergo processes like\ndrying, freezing, wrinkling, diffusing and reacting. Those changes then give rise to complex\npatterns at a larger scale that people can see.\n这类图案在小尺度上开始形成,当材料经历干燥、冻结、起皱、扩散和反应等过程时。这些\n变化随后产生了人们能看到的大尺度复杂图案。","signal":"过程链中的因果承接。前句讲 materials undergo processes,后句用 Those changes\nthen give rise to 承接,说明正是这些过程/变化导致了大尺度复杂图案。","paraphrase":"materials undergo processes like drying, freezing, wrinkling, diffusing and reacting ↔\nMaterials undergoing certain processes\n概括性同义替换\nThose changes then give rise to complex patterns at a larger scale ↔\nMaterials undergoing certain processes\n因果对应","explanation":"【信号】过程链中的因果承接。前句讲 materials undergo processes,后句用 Those changes\nthen give rise to 承接,说明正是这些过程/变化导致了大尺度复杂图案。\n【替换】materials undergo processes like drying, freezing, wrinkling, diffusing and reacting ↔\nMaterials undergoing certain processes\n概括性同义替换\nThose changes then give rise to complex patterns at a larger scale ↔\nMaterials undergoing certain processes\n因果对应\n【排除】B"},{"no":14,"type":"细节题","prompt":"What does the example of frozen crystals on a window show?","options":[{"label":"A","text":"The beauty of molecular clustering.","zh":"分子聚集之美。"},{"label":"B","text":"The way for appreciating patterns.","zh":"欣赏图案的方法。"},{"label":"C","text":"The creation of patterns.","zh":"图案的形成。"},{"label":"D","text":"The factors affecting clusters.","zh":"影响聚集的因素。"}],"answer":"C","evidence":"Imagine delicate frozen crystals on a window during winter. What creates that pattern? When\nwater freezes, its molecules begin clustering together. Water molecules have a particular bent\nshape that causes them to stack into clusters as they freeze. As the cluster grows, many\noutside factors, including humidity and temperature, begin to affect its overall shape. If the\nwater is freezing on a window, for example, random imperfections on the glass surface affect\nthe stacking and create the larger pattern.\n想象冬天窗户上精致的冰晶。是什么创造了那种图案?水结冰时,其分子开始聚集。水分子\n具有特殊的弯曲形状,使它们在结冰时堆叠成簇。随着簇的生长,包括湿度和温度在内的许\n多外部因素开始影响其整体形状。例如,如果水在窗户上结冰,玻璃表面的随机缺陷会影响\n堆叠并创造出更大的图案。","signal":"设问句引出例子主旨。段落以 What creates that pattern? 设问,随后整段解释水分子\n聚集、外部因素、玻璃缺陷如何共同 create the larger pattern,说明例子服务于'图案的\n创造'。","paraphrase":"What creates that pattern? ↔The creation of patterns\n同义概括\ncreate the larger pattern ↔The creation of patterns\n首尾呼应","explanation":"【信号】设问句引出例子主旨。段落以 What creates that pattern? 设问,随后整段解释水分子\n聚集、外部因素、玻璃缺陷如何共同 create the larger pattern,说明例子服务于'图案的\n创造'。\n【替换】What creates that pattern? ↔The creation of patterns\n同义概括\ncreate the larger pattern ↔The creation of patterns\n首尾呼应\n【排除】A"},{"no":15,"type":"推断题","prompt":"What might molecular processes produce, according to the passage?","options":[{"label":"A","text":"A pattern by accident.","zh":"偶然形成的图案。"},{"label":"B","text":"Patterns for specific purposes.","zh":"为特定目的形成的图案。"},{"label":"C","text":"Patterns with random imperfections.","zh":"带有随机瑕疵的图案。"},{"label":"D","text":"A pattern with artificial intervention.","zh":"经过人为干预形成的图案。"}],"answer":"A","evidence":"But scientists do not always know the purpose of a pattern, or even if there is one. The\nmolecular processes involved are simple enough that they might generate a pattern\nby coincidence.\n但科学家并不总是知道某种图案的目的,甚至不知道它是否有目的。所涉及的分子过程足够\n简单,以至于它们可能偶然产生一种图案。","signal":"转折后给可能性结论。But scientists do not always know the purpose of a pattern, or\neven if there is one 先让步,随后 might generate a pattern by coincidence 用 might\n给出可能性结论。","paraphrase":"generate a pattern by coincidence ↔A pattern by accident\n同义替换","explanation":"【信号】转折后给可能性结论。But scientists do not always know the purpose of a pattern, or\neven if there is one 先让步,随后 might generate a pattern by coincidence 用 might\n给出可能性结论。\n【替换】generate a pattern by coincidence ↔A pattern by accident\n同义替换\n【排除】B"}]},{"id":"2026-06-2-s5","section":"Section C","title":"Recording 1 (Q16–18)","qRange":[16,18],"audio":"audio/listening/202606_set2.mp3","fullTrack":true,"bilingual":[{"en":"Many people, myself included, have multiple areas of life they would like to improve. For example, I would like to reach more people with my writing, to lift heavier weights at the gym, and to start practising mindfulness more consistently. Those are just a few of the goals I find desirable, and you probably have a long list yourself. The problem is, even if we are committed to working hard on our goals, our natural tendency is to return to our old habits at some point. Making a permanent lifestyle change is really difficult.","zh":"包括我在内,许多人都希望改善生活中的多个方面。例如,我希望通过写作让更多人读到我的作品,希望在健身房举起更重的重量,也希望开始更加持续地练习正念。这些只是我认为值得追求的几个目标,而你自己可能也列有一长串目标。问题在于,即使我们决心为目标努力奋斗,我们的自然倾向仍然是在某个时候回到旧有习惯。要永久改变生活方式确实非常困难。"},{"en":"Recently I've come across a few studies that will make these difficult lifestyle changes a bit easier. As you'll see, however, the approach to mastering many areas of life is somewhat counterintuitive. Research has shown that you are two to three times more likely to stick with your habits if you make a specific plan for when, where, and how you will perform the behavior. For example, in one study, scientists asked people to fill out a sentence to specify during the next week they would do at least 20 minutes of vigorous exercise on which day, at what time of day, and at or in what place. Researchers found that people who filled out this sentence were two to three times more likely to actually exercise compared to a control group who did not make plans for their future behavior. Psychologists call these specific plans implementation intentions because they state when, where, and how you intend to implement a particular behavior.","zh":"最近,我接触到了一些研究,这些研究将使这些艰难的生活方式改变变得稍微容易一些。不过,正如你将看到的,掌握生活中许多方面的方法有些违背直觉。研究表明,如果你针对自己将在何时、何地以及如何实施某种行为制订具体计划,那么坚持这些习惯的可能性会提高到原来的两到三倍。例如,在一项研究中,科学家要求人们填写一个句子,具体说明自己将在下一周的哪一天、一天中的什么时间,以及在什么地点进行至少20分钟的剧烈运动。研究人员发现,与没有为未来行为制订计划的对照组相比,填写了这个句子的人实际进行锻炼的可能性高出两到三倍。心理学家将这些具体计划称为“执行意图”,因为它们说明了你打算在何时、何地以及如何实施某种特定行为。"},{"en":"However, follow-up research has discovered implementation intentions only work when you focus on one thing at a time. In fact, researchers found that people who tried to accomplish multiple goals were less committed and less likely to succeed than those who focused on a single goal.","zh":"然而,后续研究发现,执行意图只有在你一次专注于一件事时才会奏效。事实上,研究人员发现,试图实现多个目标的人,比专注于单一目标的人投入程度更低,成功的可能性也更小。"},{"en":"Another science-based reason to focus on one thing at a time is that when you begin practising a new habit, it requires a lot of conscious effort to remember to do it. After a while, however, the pattern of behavior becomes easier. Eventually, your new habit becomes a normal routine, and the process is more or less mindless and automatic. The most important thing to note is that there is some tipping point at which new habits become more or less automatic. The time it takes to build a habit depends on many factors, including how difficult the habit is, your genetics, and more.","zh":"一次专注于一件事还有一个基于科学的理由,那就是当你开始练习一种新习惯时,记得去做这件事需要付出大量有意识的努力。然而,过一段时间之后,这种行为模式会变得更加容易。最终,你的新习惯会成为一种日常惯例,而这一过程或多或少会变得无需意识参与,并且自动进行。需要注意的最重要一点是,存在这样一个临界点:在此之后,新习惯会或多或少地变得自动化。养成一个习惯所需的时间取决于许多因素,包括习惯的难度、你的遗传因素,以及其他因素。"}],"questions":[{"no":16,"type":"细节题","prompt":"What does the speaker say is really difficult?","options":[{"label":"A","text":"Eliminating all the old habits at once.","zh":"一下子改掉所有旧习惯。"},{"label":"B","text":"Making a permanent lifestyle change.","zh":"永久改变生活方式。"},{"label":"C","text":"Realizing all the life goals one has set.","zh":"实现自己设定的所有人生目标。"},{"label":"D","text":"Improving multiple areas of one's life.","zh":"改善生活的多个方面。"}],"answer":"B","evidence":"The problem is, even if we are committed to working hard on our goals, our natural\ntendency is to return to our old habits at some point. Making a permanent lifestyle change is\nreally difficult.\n问题是,即使我们致力于努力实现目标,我们的自然倾向还是在某个时刻回到旧习惯。永久\n改变生活方式真的很难。","signal":"题眼词复现 + 总结句。题干中的 difficult 在 Making a permanent lifestyle change is\nreally difficult 中直接复现;这是段落末尾的总结句,前面用 The problem is 铺垫,信息\n落点在 really difficult 上。","paraphrase":"Making a permanent lifestyle change is really difficult ↔Making a permanent lifestyle change\n同义复现","explanation":"【信号】题眼词复现 + 总结句。题干中的 difficult 在 Making a permanent lifestyle change is\nreally difficult 中直接复现;这是段落末尾的总结句,前面用 The problem is 铺垫,信息\n落点在 really difficult 上。\n【替换】Making a permanent lifestyle change is really difficult ↔Making a permanent lifestyle change\n同义复现\n【排除】A"},{"no":17,"type":"细节题","prompt":"What did researchers find about people with implementation intentions?","options":[{"label":"A","text":"They were more likely to implement a particular behavior.","zh":"他们更有可能实施某种特定行为。"},{"label":"B","text":"They were more likely to make plans for their future.","zh":"他们更有可能为自己的未来制订计划。"},{"label":"C","text":"They tended to be committed to a single goal.","zh":"他们往往致力于实现单一目标。"},{"label":"D","text":"They tended to focus on one thing at a time.","zh":"他们往往一次专注于一件事。"}],"answer":"A","evidence":"Researchers found that people who filled out this sentence were two to three times more\nlikely to actually exercise compared to a control group who did not make plans for their\nfuture behavior.\n研究人员发现,填写了这句话的人真正去锻炼的可能性是对照组的两到三倍,而对照组没有\n为他们未来的行为制定计划。","signal":"研究结论标志词。题干问 researchers find,原文 Researchers found that 正是结论信\n号;其后 two to three times more likely to actually exercise 给出量化结果。","paraphrase":"two to three times more likely to actually exercise ↔\nmore likely to implement a particular behavior\n具体实例概括为行为实施\nhow you intend to implement a particular behavior ↔implement a particular behavior\n词组复现","explanation":"【信号】研究结论标志词。题干问 researchers find,原文 Researchers found that 正是结论信\n号;其后 two to three times more likely to actually exercise 给出量化结果。\n【替换】two to three times more likely to actually exercise ↔\nmore likely to implement a particular behavior\n具体实例概括为行为实施\nhow you intend to implement a particular behavior ↔implement a particular behavior\n词组复现\n【排除】B"},{"no":18,"type":"细节题","prompt":"According to the speaker, what is required of you when you begin practising a\nnew habit?","options":[{"label":"A","text":"The ability to make the process automatic.","zh":"使这一过程自动化的能力。"},{"label":"B","text":"A practical timetable for implementation.","zh":"一份切实可行的实施时间表。"},{"label":"C","text":"A lot of conscious effort to remember to do it.","zh":"需要付出大量有意识的努力来提醒自己去做这件事。"},{"label":"D","text":"Concentration on the benefits it will provide. 懒笔记 · https://english-exam.lazynote.cn/cet6/paper/2026-06-2/?f=p · 在线使用效果更好 blank from a list of choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each choice in the bank is identified by a letter. Please mark the corresponding","zh":"专注于它将带来的好处。"}],"answer":"C","evidence":"Another science-based reason to focus on one thing at a time is that when you begin\npractising a new habit, it requires a lot of conscious effort to remember to do it.\n另一个一次只专注一件事的科学依据是,当你开始练习一个新习惯时,你需要付出大量有意\n识的努力去记住去做这件事。","signal":"时间状语 + 需求动词。题干中的 when you begin practising a new habit 在 when you\nbegin practising a new habit 中原样复现,紧随其后的 requires a lot of conscious\neffort to remember to do it 就是答案所在。","paraphrase":"requires a lot of conscious effort to remember to do it ↔\nA lot of conscious effort to remember to do it\n名词短语截取","explanation":"【信号】时间状语 + 需求动词。题干中的 when you begin practising a new habit 在 when you\nbegin practising a new habit 中原样复现,紧随其后的 requires a lot of conscious\neffort to remember to do it 就是答案所在。\n【替换】requires a lot of conscious effort to remember to do it ↔\nA lot of conscious effort to remember to do it\n名词短语截取\n【排除】A"}]},{"id":"2026-06-2-s6","section":"Section C","title":"Recording 2 (Q19–21)","qRange":[19,21],"audio":"audio/listening/202606_set2.mp3","fullTrack":true,"bilingual":[{"en":"It was a lazy, hazy, crazy day on the dwarf planet Pluto when New Horizons, a spacecraft from Earth, flew by at a speed of 31,000 mph (miles per hour) two years ago. The spacecraft took a bunch of photos, made some quick measurements of Pluto's atmosphere, and sent them all back here, giving planetary scientists their first up-close look of the distant dwarf planet.","zh":"两年前,在新视野号这艘来自地球的航天器以每小时31,000英里(英里/小时)的速度飞掠而过时,矮行星冥王星度过了慵懒、朦胧而疯狂的一天。这艘航天器拍摄了大量照片,对冥王星的大气层进行了一些快速测量,并将这些数据全部传回地球,使行星科学家们首次近距离观察到这颗遥远的矮行星。"},{"en":"One of the more bizarre things they found was that the haze in Pluto's atmosphere was much thicker than previously thought. The planet also had an atmosphere much cooler than earlier estimates, topping out at −333.4°F.","zh":"他们发现的较为奇异的现象之一,是冥王星大气层中的霾比先前认为的厚得多。这颗行星的大气层也比早先估计的冷得多,最高温度仅为−333.4°F。"},{"en":"Now, a study published in Nature links those two atmospheric observations. A computer model developed by planetary scientist Xi Zhang and colleagues shows the haze of tiny droplets in the upper atmosphere is likely scattering light from the Sun, preventing heat from reaching the planet below. We see hazy skies on Earth too, from time to time, whenever solid particles get suspended in the air—from water-based fogs, to ash from fires, to the toxic droplets that make up a thick smog. But on Earth, the overall temperature of the planet is dominated by the distribution of gases in our atmosphere.","zh":"如今,《自然》杂志发表的一项研究将这两项大气观测结果联系了起来。行星科学家张希及其同事开发的一种计算机模型显示,高层大气中由微小液滴形成的霾很可能会散射来自太阳的光,阻止热量抵达下方的行星。地球上也会不时出现雾霾天气,每当固体颗粒悬浮在空气中时,就可能形成这种现象,从含水雾气到火灾产生的灰烬,再到构成浓重烟雾的有毒液滴,都是如此。但在地球上,行星的整体温度主要由大气层中气体的分布决定。"},{"en":"On Pluto, the authors suggest, haze might be more influential. Particles can reflect light from the Sun here on Earth: It happens after volcanoes erupt, emitting clouds of particles that reflect the Sun's rays into the atmosphere. Some people even propose imitating this phenomenon to alleviate the effects of climate change. But our planet isn't dominated by that process, or at least it hasn't been for a few billion years.","zh":"作者认为,在冥王星上,霾的影响可能更大。在地球上,颗粒物能够反射来自太阳的光:火山喷发后会释放出由颗粒物组成的云团,将太阳光线反射回大气层。有些人甚至提出模仿这一现象,以减轻气候变化的影响。但我们的行星并不是由这一过程主导的,至少在过去几十亿年里不是如此。"},{"en":"If Pluto's atmosphere is very different from ours and from that of other nearby planets, it could help scientists expand their understanding of planetary atmospheres. But right now, this is just a good guess based on data from New Horizons and a sophisticated computer model, not direct observations of the haze's composition.","zh":"如果冥王星的大气层与地球以及其他邻近行星的大气层截然不同,这将有助于科学家拓展对行星大气层的认识。但目前,这只是基于新视野号获得的数据和一个复杂计算机模型提出的合理推测,而不是对霾的成分进行直接观测所得出的结论。"},{"en":"There are other theories floating around to explain Pluto's cool temperatures, including blaming the cold air on gases in the atmosphere.","zh":"关于解释冥王星低温的理论还有其他一些,包括把寒冷的空气归因于大气层中的气体。"},{"en":"Luckily, the authors will get a chance to test their notions when the James Webb Space Telescope launches later. That observatory can detect different spectrums of light, which the hazy Plutonian atmosphere would be positively glowing with as it scattered sunlight. The researchers just have to wait and see if the light from the telescope validates their bright idea.","zh":"幸运的是,詹姆斯·韦布空间望远镜稍后发射后,作者们将有机会检验他们的观点。这座天文台能够探测不同光谱的光,而冥王星朦胧的大气层在散射阳光时很可能会发出大量这样的光。研究人员只需等待并观察望远镜接收到的光是否会验证他们的这个妙想。"}],"questions":[{"no":19,"type":"细节题","prompt":"What was one of the more bizarre findings about Pluto's atmosphere?","options":[{"label":"A","text":"It resembles that of Earth in many inconceivable ways.","zh":"它以许多难以想象的方式与地球大气层相似。"},{"label":"B","text":"It has a haze much thicker than previously believed.","zh":"它的大气霾层比先前认为的厚得多。"},{"label":"C","text":"It is 333.4°F cooler than earlier estimates.","zh":"它比早先估计的温度低333.4华氏度。"},{"label":"D","text":"It is far beyond any quick measurements.","zh":"它远远超出了任何快速测量的范围。"}],"answer":"B","evidence":"One of the more bizarre things they found was that the haze in Pluto's atmosphere was much\nthicker than previously thought.\n他们发现的一件更离奇的事情是,冥王星大气中的霾层比之前认为的要厚得多。","signal":"题干关键词复现 + 比较级信息。录音中 One of the more bizarre things they found 与题\n干中的 finding 直接呼应,随后 was much thicker than previously thought 给出具体特\n征,正是答案所在。","paraphrase":"the haze in Pluto's atmosphere was much thicker than previously thought ↔\nIt has a haze much thicker than previously believed.\n同义词 + 主谓压缩","explanation":"【信号】题干关键词复现 + 比较级信息。录音中 One of the more bizarre things they found 与题\n干中的 finding 直接呼应,随后 was much thicker than previously thought 给出具体特\n征,正是答案所在。\n【替换】the haze in Pluto's atmosphere was much thicker than previously thought ↔\nIt has a haze much thicker than previously believed.\n同义词 + 主谓压缩\n【排除】A"},{"no":20,"type":"细节题","prompt":"What is said to determine the overall temperature on Earth?","options":[{"label":"A","text":"The accumulation of solid particles in the air.","zh":"空气中固体颗粒的积聚。"},{"label":"B","text":"The distribution of gases in its atmosphere.","zh":"其大气层中气体的分布。"},{"label":"C","text":"The clouds of particles reflecting sun rays.","zh":"反射太阳光线的颗粒云。"},{"label":"D","text":"The aggravated effects of climate change.","zh":"气候变化加剧的影响。"}],"answer":"B","evidence":"But on Earth, the overall temperature of the planet is dominated by the distribution of gases in\nour atmosphere.\n但在地球上,行星的整体温度是由大气中气体的分布所主导的。","signal":"转折后给出地球情况的结论。录音先用 Pluto 的 haze 机制做铺垫,随后用 But on Earth\n一转,指出 the overall temperature of the planet is dominated by the distribution\nof gases in our atmosphere,直接回答题干中的 determine the overall temperature\non Earth。","paraphrase":"the overall temperature of the planet is dominated by the distribution of gases in our atmosphere ↔\nThe distribution of gases in its atmosphere.\n主被动转换 + 同义替换","explanation":"【信号】转折后给出地球情况的结论。录音先用 Pluto 的 haze 机制做铺垫,随后用 But on Earth\n一转,指出 the overall temperature of the planet is dominated by the distribution\nof gases in our atmosphere,直接回答题干中的 determine the overall temperature\non Earth。\n【替换】the overall temperature of the planet is dominated by the distribution of gases in our atmosphere ↔\nThe distribution of gases in its atmosphere.\n主被动转换 + 同义替换\n【排除】A"},{"no":21,"type":"细节题","prompt":"What does the speaker say the researchers have to wait and see?","options":[{"label":"A","text":"If spectrums of light can be better detected by telescope.","zh":"望远镜能否更好地探测到光谱。"},{"label":"B","text":"If Pluto's hazy atmosphere can be more easily observed.","zh":"能否更容易地观测到冥王星的霾状大气层。"},{"label":"C","text":"If Pluto's hazy atmosphere scatters strong sunlight.","zh":"冥王星的霾状大气层是否会散射强烈的阳光。"},{"label":"D","text":"If the light from the telescope confirms their idea.","zh":"望远镜接收到的光是否证实他们的想法。"}],"answer":"D","evidence":"The researchers just have to wait and see if the light from the telescope validates their\nbright idea.\n研究者们只能等待并观察,来自望远镜的光线是否会证实他们那个不错的想法。","signal":"题干关键词 wait and see 原词复现。录音末句 The researchers just have to wait and\nsee 与题干中的 wait and see 完全对应,随后的 if 从句就是答案所在。","paraphrase":"if the light from the telescope validates their bright idea ↔\nIf the light from the telescope confirms their idea.\n同义词替换 + 形容词省略","explanation":"【信号】题干关键词 wait and see 原词复现。录音末句 The researchers just have to wait and\nsee 与题干中的 wait and see 完全对应,随后的 if 从句就是答案所在。\n【替换】if the light from the telescope validates their bright idea ↔\nIf the light from the telescope confirms their idea.\n同义词替换 + 形容词省略\n【排除】A"}]},{"id":"2026-06-2-s7","section":"Section C","title":"Recording 3 (Q22–25)","qRange":[22,25],"audio":"audio/listening/202606_set2.mp3","fullTrack":true,"bilingual":[{"en":"Parents have a small window where they can influence their 8- to 10-year-old children's music taste, researchers have concluded. The 24-month time frame comes at an age when youngsters are old enough to appreciate poetic lyrics and snappy tunes, but have not yet started to be embarrassed by their mother and father's preferences. Dr. Hauke Egermann, a lecturer in music at the University of York, carried out a literature review into more than a dozen studies looking at parental musical influence. \"Children have an openness to new music, and this means parents have an important role to play in developing the musical preferences of their kids,\" he said.","zh":"研究人员得出结论,父母有一个短暂的窗口期,可以影响8至10岁孩子的音乐品味。这段24个月的时期处于这样一个年龄阶段:孩子已经足够大,能够欣赏富有诗意的歌词和朗朗上口的曲调,但还没有开始因父母的音乐偏好而感到尴尬。约克大学音乐讲师豪克·埃格尔曼博士对十多项有关父母音乐影响的研究进行了文献综述。他说:“孩子对新音乐持开放态度,这意味着父母在培养孩子的音乐偏好方面扮演着重要角色。”"},{"en":"However, time is of the essence as parental influence is most likely to be effective during the critical time period before age ten. During adolescence, children tend to gravitate away from their parents' choices and are more influenced by their peers. A separate survey of 2,000 British parents by music streaming service Deezer also found that nearly four-fifths of parents agreed that their children were far more receptive to their musical suggestions before the age of ten. In contrast, just 10 percent of parents reported positive reactions from their teenage children when they shared their favorite music. Some 79 percent of fathers said they had tried to influence their children's music, but just 69 percent of mothers. However, mothers were more effective, with 38 percent reporting that their kids loved the tunes they shared, compared to 30 percent of dads who, in some cases, said their children cried or even fell asleep.","zh":"然而,时间至关重要,因为父母的影响最有可能在十岁以前这一关键时期发挥作用。进入青春期后,孩子往往会逐渐远离父母的选择,并更多地受到同龄人的影响。音乐流媒体服务Deezer对2000名英国父母进行的另一项调查也发现,近五分之四的父母认为,孩子在十岁以前更容易接受他们的音乐建议。相比之下,只有10%的父母表示,孩子进入青少年时期后,在他们分享自己喜爱的音乐时会作出积极反应。约79%的父亲表示曾试图影响孩子的音乐选择,而母亲的这一比例仅为69%。不过,母亲的影响更有效:38%的母亲表示孩子喜欢她们分享的曲调,而父亲中只有30%的人得到这样的反馈;有些父亲甚至表示,孩子听着听着哭了起来,或者睡着了。"},{"en":"Dr. Egermann claims introducing children to a variety of musical styles is the key to fostering good taste in later life. \"By playing children a variety of genres before this critical period, research on familiarization suggests they will enjoy lots of different types of music as adults,\" he added. The benefits of having a wider taste in music include the ability to manage their emotions more effectively, socialize and bond with others more easily, and to have a better understanding of other cultures as well.","zh":"埃格尔曼博士认为,让孩子接触各种各样的音乐风格,是培养他们日后良好音乐品味的关键。他补充说:“有关熟悉化的研究表明,在这一关键时期之前让孩子聆听多种音乐类型,他们成年后将会喜欢许多不同种类的音乐。”拥有更广泛的音乐品味所带来的益处包括更有效地管理情绪、更容易与他人交往并建立联系,以及更好地理解其他文化。"},{"en":"Dr. Egermann advises parents not to push their favorite music too hard on their children, but instead play it as background music while a child is playing. They can also help create positive memories about artists and bands by going to concerts and live music events together.","zh":"埃格尔曼博士建议,父母不要过分强迫孩子接受自己喜爱的音乐,而应在孩子玩耍时将其作为背景音乐播放。他们还可以通过一起参加音乐会和现场音乐活动,帮助孩子对音乐家和乐队形成积极的记忆。"}],"questions":[{"no":22,"type":"细节题","prompt":"What do we learn from researchers' conclusion at the beginning of the talk?","options":[{"label":"A","text":"Parents can play a decisive role in cultivating their children's musical talent.","zh":"父母可以在培养孩子的音乐天赋方面发挥决定性作用。"},{"label":"B","text":"Children are embarrassed by parents' failure to appreciate their music.","zh":"孩子们因父母不欣赏自己的音乐而感到难堪。"},{"label":"C","text":"Parents can mould their 8- to 10-year-old children's music taste.","zh":"父母可以塑造8至10岁孩子的音乐品味。"},{"label":"D","text":"Children aged 8 to 10 are old enough to produce poetic lyrics.","zh":"8至10岁的孩子已经足够大,能够创作富有诗意的歌词。"}],"answer":"C","evidence":"Parents have a small window where they can influence their 8- to 10-year-old children's\nmusic taste, researchers have concluded.\n研究人员得出结论:父母有一个短暂的窗口期,可以影响8到10岁孩子的音乐品味。","signal":"研究结论标志词。答案句以researchers have concluded结尾,是典型的研究结论标志;同\n时句首直接给出结论内容,符合篇章开头'先给结论'的常见结构。","paraphrase":"influence their 8- to 10-year-old children's music taste ↔\nmould their 8- to 10-year-old children's music taste\ninfluence与mould同义替换\nParents have a small window where they can ↔Parents can\nsmall window限定为可能性","explanation":"【信号】研究结论标志词。答案句以researchers have concluded结尾,是典型的研究结论标志;同\n时句首直接给出结论内容,符合篇章开头'先给结论'的常见结构。\n【替换】influence their 8- to 10-year-old children's music taste ↔\nmould their 8- to 10-year-old children's music taste\ninfluence与mould同义替换\nParents have a small window where they can ↔Parents can\nsmall window限定为可能性\n【排除】A"},{"no":23,"type":"细节题","prompt":"What does Dr. Hauke Egermann say about adolescents?","options":[{"label":"A","text":"They start to show their own musical preference.","zh":"他们开始表现出自己的音乐偏好。"},{"label":"B","text":"They tend to be more influenced by their peers.","zh":"他们往往更容易受到同龄人的影响。"},{"label":"C","text":"They tend to gravitate away from their homes.","zh":"他们往往会逐渐离开家。"},{"label":"D","text":"They are more open to new genres of music.","zh":"他们更愿意接受新的音乐流派。"}],"answer":"B","evidence":"During adolescence, children tend to gravitate away from their parents' choices and are more\ninfluenced by their peers.\n在青春期,孩子们往往会偏离父母的选择,更受同龄人的影响。","signal":"题干关键词复现+比较级。原文During adolescence与题干adolescents直接对应,句中\nmore influenced by their peers用比较级点明影响来源的变化,是答案信号。","paraphrase":"During adolescence ↔adolescents\n名词化同义\nare more influenced by their peers ↔tend to be more influenced by their peers\nbe动词添加趋向性","explanation":"【信号】题干关键词复现+比较级。原文During adolescence与题干adolescents直接对应,句中\nmore influenced by their peers用比较级点明影响来源的变化,是答案信号。\n【替换】During adolescence ↔adolescents\n名词化同义\nare more influenced by their peers ↔tend to be more influenced by their peers\nbe动词添加趋向性\n【排除】A"},{"no":24,"type":"细节题","prompt":"What is the key to fostering good taste in later life, according to Dr. Hauke Egermann?","options":[{"label":"A","text":"Enabling children to be receptive to music experts' suggestions.","zh":"让孩子能够接受音乐专家的建议。"},{"label":"B","text":"Helping children develop the ability to manage their emotions.","zh":"帮助孩子培养管理情绪的能力。"},{"label":"C","text":"Familiarising children with different schools of music.","zh":"让孩子熟悉不同的音乐流派。"},{"label":"D","text":"Introducing children to a variety of musical styles.","zh":"让孩子接触各种音乐风格。"}],"answer":"D","evidence":"Dr. Egermann claims introducing children to a variety of musical styles is the key to fostering\ngood taste in later life.\n埃格曼博士称,让孩子接触多种多样的音乐风格是培养其日后良好品味的关键。","signal":"专家观点+the key to结构。原文Dr. Egermann claims是专家观点标志,紧接着出现is the\nkey to fostering good taste in later life,与题干中的the key to fostering good taste in\nlater life完全对应。","paraphrase":"introducing children to a variety of musical styles ↔\nIntroducing children to a variety of musical styles\n核心名词短语保留\nclaims ↔according to Dr. Hauke Egermann\nclaims与according to同义","explanation":"【信号】专家观点+the key to结构。原文Dr. Egermann claims是专家观点标志,紧接着出现is the\nkey to fostering good taste in later life,与题干中的the key to fostering good taste in\nlater life完全对应。\n【替换】introducing children to a variety of musical styles ↔\nIntroducing children to a variety of musical styles\n核心名词短语保留\nclaims ↔according to Dr. Hauke Egermann\nclaims与according to同义\n【排除】A"},{"no":25,"type":"细节题","prompt":"How can parents help children create positive memories about artists and bands?","options":[{"label":"A","text":"By enhancing children's appreciation of their music.","zh":"通过提高孩子对其音乐的鉴赏力。"},{"label":"B","text":"By pushing their music hard enough upon children.","zh":"通过强行让孩子接受他们的音乐。"},{"label":"C","text":"By attending their concerts and live music events with children.","zh":"通过和孩子一起参加他们的音乐会和现场音乐活动。"},{"label":"D","text":"By introducing their music to children as early as possible.","zh":"通过尽早向孩子介绍他们的音乐。"}],"answer":"C","evidence":"They can also help create positive memories about artists and bands by going to concerts and\nlive music events together.\n他们还可以通过带孩子一起去听音乐会和现场音乐演出来帮助创造关于艺人和乐队的积极\n记忆。","signal":"题干关键词复现+by doing方式状语。原文help create positive memories about artists\nand bands与题干完全复现,其后的by going to concerts and live music events\ntogether就是具体方式。","paraphrase":"by going to concerts and live music events together ↔\nBy attending their concerts and live music events with children\ngoing to与attending同义,together与with children同义","explanation":"【信号】题干关键词复现+by doing方式状语。原文help create positive memories about artists\nand bands与题干完全复现,其后的by going to concerts and live music events\ntogether就是具体方式。\n【替换】by going to concerts and live music events together ↔\nBy attending their concerts and live music events with children\ngoing to与attending同义,together与with children同义\n【排除】A"}]}]},{"id":"2023-12-1","title":"2023年12月 六级第1套（外研社全稿精讲）","year":"2023.12","exam":"六级 CET-6","totalQuestions":25,"audioMode":"sliced","sections":[{"id":"2023-12-1-s1","section":"Section A","title":"Conversation 1 · 医生问诊与职场压力 (Q1–4)","qRange":[1,4],"audio":"audio/listening/202312_s1.mp3","durationSec":189.0,"segments":[{"t0":0.0,"t1":0.81,"text":"through the centre."},{"t0":0.81,"t1":2.81,"text":"Conversation 1"},{"t0":2.81,"t1":3.81,"text":"Hello Doctor."},{"t0":3.81,"t1":5.45,"text":"Hello, please take a seat."},{"t0":5.45,"t1":8.61,"text":"I have your test results here and it's good news."},{"t0":8.61,"t1":10.81,"text":"The blood test came back clear."},{"t0":10.81,"t1":14.33,"text":"There is no indication of any digestive issues."},{"t0":14.33,"t1":17.41,"text":"So then, why do I feel so poorly all the time?"},{"t0":17.41,"t1":20.33,"text":"It's probably due to overwork and stress."},{"t0":20.33,"t1":21.81,"text":"No, it can't be."},{"t0":21.81,"t1":25.41,"text":"I've always been working hard but I've never felt stress."},{"t0":25.41,"t1":28.49,"text":"Other people's suffering complain about that but I don't."},{"t0":28.49,"t1":30.21,"text":"It must be something else."},{"t0":30.21,"t1":33.57,"text":"What you have just described is a common sentiment."},{"t0":33.57,"t1":37.37,"text":"Many people who suffer from stress fail to recognise it."},{"t0":37.37,"t1":40.61,"text":"You told me you often work long into the night, right?"},{"t0":40.61,"t1":42.97,"text":"Yes, most days in fact."},{"t0":42.97,"t1":46.29,"text":"But I've been doing that for about 20 years now."},{"t0":46.29,"t1":47.45,"text":"That doesn't matter."},{"t0":47.45,"t1":52.29,"text":"You could have been suffering from stress for 20 years without knowing it and now it's catching"},{"t0":52.29,"t1":53.65,"text":"up to you."},{"t0":53.65,"t1":58.73,"text":"But what about my feeling tired all the time and not being able to sleep well at night?"},{"t0":58.73,"t1":63.69,"text":"Those are common consequences of stress and if you don't sleep well then of course you"},{"t0":63.69,"t1":65.41,"text":"will feel fatigued."},{"t0":65.41,"t1":68.81,"text":"I'm going to prescribe some special sleeping pills for you."},{"t0":68.81,"t1":73.57,"text":"They have a soft, gentle effect and are made from natural ingredients so your stomach"},{"t0":73.57,"t1":78.17,"text":"should tolerate them fine and there shouldn't be any negative side effects."},{"t0":78.17,"t1":81.41,"text":"Take one with your dinner and come see me after a month."},{"t0":81.41,"t1":84.89,"text":"If there is no improvement I'll give you something stronger."},{"t0":84.89,"t1":85.89,"text":"Thank you doctor."},{"t0":85.89,"t1":87.09,"text":"That's not all."},{"t0":87.09,"t1":89.01,"text":"You should try and work less."},{"t0":89.01,"t1":91.85,"text":"Is there any way you can decrease your workload?"},{"t0":91.85,"t1":94.33,"text":"Erm, I'd have to think about it."},{"t0":94.33,"t1":97.97,"text":"I'm a restaurant manager and this industry is very competitive."},{"t0":97.97,"t1":100.85,"text":"There are many things to keep track of and stay on top of."},{"t0":100.85,"t1":105.29,"text":"I recommend you think about delegating some responsibilities to someone else."},{"t0":105.29,"t1":108.81,"text":"I'm not asking you to retire just to slow down a bit."},{"t0":108.81,"t1":111.65,"text":"It's for your own health."},{"t0":111.65,"t1":116.01,"text":"Questions one to four are based on the conversation you have just heard."},{"t0":116.01,"t1":134.1,"text":"Question one, what do we learn about the man from his test results?"},{"t0":134.1,"t1":153.14,"text":"Question two, what does the woman think is a common phenomenon among many people?"},{"t0":153.14,"t1":170.61,"text":"Question three, what does the woman say she will do for the man?"},{"t0":170.61,"t1":189.0,"text":"Question four, what does the man say about the industry he is engaged in?"}],"questions":[{"no":1,"type":"细节/推断题","prompt":"What do we learn about the man from his test results?","options":[{"label":"A","text":"It is clear that he is expected to enjoy a healthy life."},{"label":"B","text":"There is nothing wrong with his digestive system."},{"label":"C","text":"There is some indication of an issue with his blood circulation."},{"label":"D","text":"He doesn't know he has long been suffering from poor health."}],"answer":"B","evidence":"消化系统检查无异常","explanation":"此题考查男士的检查结果如何。对话开头医生就告知了男士的检查结果,医生对男士说:“你的检查结果来了,是个好消息,验血结果没有问题,没有任何消化系统疾病的指征。”选项B是对录音的同义转述,故为答案。"},{"no":2,"type":"细节/推断题","prompt":"What does the woman think is a common phenomenon among many people?","options":[{"label":"A","text":"Mistaking symptoms of illness for stress."},{"label":"B","text":"Complaining they are being overworked."},{"label":"C","text":"Being unaware of the stress they are under."},{"label":"D","text":"Suffering from illness without recognizing it."}],"answer":"C","evidence":"未意识到压力","explanation":"此题考查在女士看来,很多人身上普遍存在的现象是什么。对话中女士表示男士感觉不舒服可能是因为过于繁重的工作压力,男士却说自己从没感到过压力,女士说男士的这种看法是普遍的,指出“许多承受压力的人没有意识到这一点”,选项C是对录音的同义转述,故为答案。"},{"no":3,"type":"细节/推断题","prompt":"What does the woman say she will do for the man?","options":[{"label":"A","text":"Prescribe some medication for him."},{"label":"B","text":"Give him another physical check-up."},{"label":"C","text":"Explain to him the common consequence of stress."},{"label":"D","text":"Buy some sleeping pills for him from the drugstore."}],"answer":"A","evidence":"开药","explanation":"此题考查女士会为男士做什么。对话中男士询问女士自己总觉得很累,晚上睡不好觉是怎么回事,女士解释说这些症状都是压力带来的常见后果,并说:“我给你开一些特别的安眠药。”选项A与录音相符,故为答案。"},{"no":4,"type":"细节/推断题","prompt":"What does the man say about the industry he is engaged in?","options":[{"label":"A","text":"It calls for responsible management."},{"label":"B","text":"It proves to be quite profitable."},{"label":"C","text":"It is remarkably promising."},{"label":"D","text":"It is full of competition."}],"answer":"D","evidence":"餐饮行业竞争激烈","explanation":"此题考查男士如何看待自己所从事的行业。根据对话可知,女士建议男士应该少干点活,并询问男士有什么办法可以减少他的工作量,男士回答说:“我是一名餐厅经理,这个行业竞争非常激烈。”选项D与录音相符,故为答案。"}],"printedTranscript":"M: Hello, doctor.\nW: Hello, please take a seat. I have your test results here, and it's good news. The blood test came back\nclear. [1] There is no indication of any digestive issues.\nM: So then why do I feel so poorly all the time?\nW: It's probably due to overwork and stress.\nM: No, it can't be. I've always been working hard, but I've never felt stress. Other people suffering\ncomplain about that, but I don't. It must be something else.\nW: What you have just described is a common sentiment. [2] Many people who suffer from stress fail to\nrecognize it. You told me you often work long into the night, right?\nM: Yes, most days, in fact. But I've been doing that for about 20 years now.\nW: That doesn't matter. You could have been suffering from stress for 20 years without knowing it. And\nnow it's catching up to you.\nM: But what about my feeling tired all the time and not being able to sleep well at night?\nW: Those are common consequences of stress. And if you don't sleep well, then of course you will\nfeel fatigued. [3] I'm going to prescribe some special sleeping pills for you. They have a soft, gentle\neffect and are made from natural ingredients. So your stomach should tolerate them fine, and there\nshouldn't be any negative side effects. Take one with your dinner and come see me after a month. If\nthere is no improvement, I'll give you something stronger.\nM: Thank you, doctor.\nW: That's not all. You should try and work less. Is there any way you can decrease your workload?\nM: Um, I'd have to think about it. [4] I'm a restaurant manager and this industry is very competitive.\nThere are many things to keep track of and stay on top of.\nW: I recommend you think about delegating some responsibilities to someone else. I'm not asking you\nto retire, just to slow down a bit. It's for your own health."},{"id":"2023-12-1-s2","section":"Section A","title":"Conversation 2 · 退役篮球运动员 (Q5–8)","qRange":[5,8],"audio":"audio/listening/202312_s2.mp3","durationSec":199.5,"segments":[{"t0":0.0,"t1":0.41,"text":"Question four, what does the man say about the industry he is engaged in?"},{"t0":0.41,"t1":2.45,"text":"Conversation two."},{"t0":2.45,"t1":7.09,"text":"Today on People in the News, our guest is John Williams."},{"t0":7.09,"t1":13.53,"text":"The name may not sound familiar to you, but John was once an acclaimed basketball player."},{"t0":13.53,"t1":18.89,"text":"John, you stunned fans by leaving the sport at just 25."},{"t0":18.89,"t1":20.97,"text":"Why did you retire so early?"},{"t0":20.97,"t1":25.89,"text":"Meg, I loved being an athlete, but I didn't love being a celebrity."},{"t0":25.89,"t1":30.41,"text":"I was in the limelight when I was still a high school student and went professional right"},{"t0":30.41,"t1":34.05,"text":"after high school graduation, which was a mistake."},{"t0":34.05,"t1":38.29,"text":"I was a shy kid and I wasn't ready for all the media attention."},{"t0":38.29,"t1":43.09,"text":"But walking away from millions of dollars at the height of your career, most people"},{"t0":43.09,"t1":47.21,"text":"wouldn't be able to resist the lure of such a high salary."},{"t0":47.21,"t1":51.97,"text":"When you left the sport, there was speculation that you were having issues with your teammates"},{"t0":51.97,"t1":54.09,"text":"or even an injury."},{"t0":54.09,"t1":55.09,"text":"Not at all."},{"t0":55.09,"t1":56.25,"text":"It was hard to quit."},{"t0":56.25,"t1":61.57,"text":"I was tempted to stay in the game because I loved basketball and I loved my team."},{"t0":61.57,"t1":66.69,"text":"As for money, I turned professional at 18, so I'd actually earned a lot and saved most"},{"t0":66.69,"t1":70.05,"text":"of it because I had great financial advisors."},{"t0":70.05,"t1":74.45,"text":"I knew basketball wasn't a career with a lot of longevity for most players, so"},{"t0":74.45,"t1":77.73,"text":"I wanted to change careers while I was still young."},{"t0":77.73,"t1":82.53,"text":"Okay, that was 20 years ago and you're back in the news."},{"t0":82.53,"t1":87.37,"text":"You've created a foundation that works to get more kids playing team sports."},{"t0":87.37,"t1":88.61,"text":"Why?"},{"t0":88.61,"t1":92.85,"text":"I went to university and I studied public health and learned about the seriousness"},{"t0":92.85,"t1":98.97,"text":"of the obesity epidemic, particularly among kids and adolescents in poor communities."},{"t0":98.97,"t1":102.89,"text":"I've spent the last two decades trying to alleviate the problem."},{"t0":102.89,"t1":105.61,"text":"The foundation is just the latest attempt."},{"t0":105.61,"t1":111.73,"text":"The foundation uses private donations to support basketball teams for girls and boys in primary"},{"t0":111.73,"t1":113.13,"text":"school, right?"},{"t0":113.13,"t1":120.89,"text":"Actually, we support teams for secondary school students too and also have some public funding."},{"t0":120.89,"t1":125.45,"text":"Questions 5 to 8 are based on the conversation you have just heard."},{"t0":125.45,"t1":126.73,"text":"Question 5."},{"t0":126.73,"t1":144.37,"text":"Why did John Williams leave the sport of basketball at just 25?"},{"t0":144.49,"t1":145.65,"text":"Question 6."},{"t0":145.65,"t1":163.26,"text":"What does the man say about basketball as a career for most players?"},{"t0":163.26,"t1":164.58,"text":"Question 7."},{"t0":164.58,"t1":181.98,"text":"What do we learn from the woman about John Williams 20 years later?"},{"t0":181.98,"t1":183.22,"text":"Question 8."},{"t0":183.22,"t1":199.5,"text":"What has the man spent the last two decades trying to do?"}],"questions":[{"no":5,"type":"细节/推断题","prompt":"Why did John Williams leave the sport of basketball at just 25?","options":[{"label":"A","text":"To avoid being in the limelight."},{"label":"B","text":"To seek medical help for his injury."},{"label":"C","text":"To pursue a less competitive career."},{"label":"D","text":"To stay away from his hostile teammates."}],"answer":"A","evidence":"不愿身处聚光灯","explanation":"此题考查约翰·威廉姆斯25岁就从篮球运动退役的原因。根据对话可知,女士问男士为什么这么早退役,男士回答说自己不喜欢当名人,并说道:“我是一个害羞的孩子,而且我还没有准备好接受所有媒体的关注。”选项A是对录音的同义转述,故为答案。"},{"no":6,"type":"细节/推断题","prompt":"What does the man say about basketball as a career for most players?","options":[{"label":"A","text":"It has ups and downs."},{"label":"B","text":"It proves rewarding."},{"label":"C","text":"It does not last long."},{"label":"D","text":"It is not so profitable."}],"answer":"C","evidence":"职业持续不长","explanation":"此题考查对于大多数球员来说,男士认为篮球是怎样的职业。根据对话可知,对话中间,男士说:“我知道对大多数球员来说,(打)篮球并不是一项长久的职业,所以我想在还年轻的时候改变职业。”选项C是对录音的同义转述,故为答案。"},{"no":7,"type":"细节/推断题","prompt":"What do we learn from the woman about John Williams 20 years later?","options":[{"label":"A","text":"He was a financial advisor."},{"label":"B","text":"He suffered from poor health."},{"label":"C","text":"He became a basketball coach."},{"label":"D","text":"He was back in the news."}],"answer":"D","evidence":"重回新闻","explanation":"此题考查我们从女士那里能够了解到20年后的约翰·威廉姆斯的何种情况。根据对话可知,女士对男士说:“好吧,那是20年前的事了,现在你又上新闻了。你创建了一个基金会,吸引更多的青少年加入团体运动项目。”选项D与录音相符,故为答案。"},{"no":8,"type":"细节/推断题","prompt":"What has the man spent the last two decades trying to do?","options":[{"label":"A","text":","},{"label":"B","text":","},{"label":"C","text":"and"},{"label":"D","text":"."}],"answer":"B","evidence":"缓解肥胖","explanation":"此题考查在过去的20年里,男士一直在努力做什么。根据对话可知,男士说自己大学的专业是公共卫生,他了解到肥胖症流行的严重性,在过去的20年里,一直都致力于缓解这一问题。选项B与录音相符,故为答案。"}],"printedTranscript":"W: Today on People in the News, our guest is John Williams. The name may not sound familiar to you,\nbut John was once an acclaimed basketball player. John, you stunned fans by leaving the sport at just\n25. Why did you retire so early?\nM: Meg, I loved being an athlete, but I didn't love being a celebrity. I was in the limelight when I was\nstill a high school student and went professional right after high school graduation, which was a\nmistake. [5] I was a shy kid and I wasn't ready for all the media attention.\nW: But walking away from millions of dollars at the height of your career—most people wouldn't be\nable to resist the lure of such a high salary. When you left the sport, there was speculation that you\nwere having issues with your teammates or even an injury.\nM: Not at all. It was hard to quit. I was tempted to stay in the game, because I loved basketball and\nI loved my team. As for money, I turned professional at 18. So I'd actually earned a lot and saved\nmost of it, because I had great financial advisers. [6] I knew basketball wasn't a career with a lot of\nlongevity for most players, so I wanted to change careers while I was still young.\nW: [7] Okay, that was 20 years ago, and you're back in the news. You've created a foundation that works\nto get more kids playing team sports. Why?\nM: I went to university and I studied public health and learned about the seriousness of the obesity\nepidemic, particularly among kids and adolescents in poor communities. [8] I've spent the last two\ndecades trying to alleviate the problem. The foundation is just the latest attempt.\nW: The foundation uses private donations to support basketball teams for girls and boys in primary\nschool, right?\nM: Actually, we support teams for secondary school students, too, and also have some public funding."},{"id":"2023-12-1-s3","section":"Section B","title":"Passage 1 · 作家 Kate Atkinson (Q9–11)","qRange":[9,11],"audio":"audio/listening/202312_s3.mp3","durationSec":176.0,"segments":[{"t0":0.0,"t1":0.76,"text":"through the centre."},{"t0":0.76,"t1":2.24,"text":"Passage 1."},{"t0":2.24,"t1":7.08,"text":"Kate Atkinson was born in York, England in 1951."},{"t0":7.08,"t1":10.4,"text":"She worked hard to gain her credentials as an author."},{"t0":10.4,"t1":14.52,"text":"She studied English Literature at University in Scotland."},{"t0":14.52,"t1":20.16,"text":"After graduating in 1974, she researched a doctorate on American literature."},{"t0":20.16,"t1":28.0,"text":"Later, she taught at the university she graduated from and began writing short stories in 1981."},{"t0":28.0,"t1":33.88,"text":"She began writing for women's magazines after winning the 1986 Woman's Own Short"},{"t0":33.88,"t1":36.2,"text":"Story Competition."},{"t0":36.2,"t1":42.56,"text":"Her first novel, Behind the Scenes at the Museum, won the 1995 UK Book of the Year"},{"t0":42.56,"t1":43.92,"text":"Award."},{"t0":43.92,"t1":49.76,"text":"The book is set in Yorkshire and has been adapted for radio, theatre and TV."},{"t0":49.76,"t1":53.72,"text":"She has written two plays for a theatre in Edinburgh."},{"t0":53.72,"t1":59.2,"text":"The first was called Nice and the second, Abandonment, performed as part of the Edinburgh"},{"t0":59.2,"t1":62.64,"text":"Festival in August 2000."},{"t0":62.64,"t1":68.8,"text":"Over genre Atkinson writes in, her books touch on the themes of love and loss and how to carry"},{"t0":68.8,"t1":69.8,"text":"on."},{"t0":69.8,"t1":74.2,"text":"They are always presented with ingenuity and a wicked sense of humour."},{"t0":74.2,"t1":80.36,"text":"Her books tend to be populated by odd, sometimes sinful and generally flawed eccentrics who"},{"t0":80.36,"t1":84.76,"text":"become credible by virtue of being so fully realised."},{"t0":84.76,"t1":90.16,"text":"Her books have frequently been described as comedies of manners, that is to say,"},{"t0":90.16,"t1":96.0,"text":"comedies that represent the complex and sophisticated code of behaviour current in fashionable circles"},{"t0":96.0,"t1":101.64,"text":"of society, where appearances count more than true moral character."},{"t0":101.64,"t1":107.32,"text":"A comedy of manners tends to reward its clever and deceitful characters rather than punish"},{"t0":107.32,"t1":109.6,"text":"their bad deeds."},{"t0":109.6,"t1":116.16,"text":"The humour of a comedy of manners relies on verbal wit and playful teasing."},{"t0":116.16,"t1":120.76,"text":"Questions 9 to 11 are based on the passage you have just heard."},{"t0":120.76,"t1":121.92,"text":"Question 9."},{"t0":121.92,"t1":139.36,"text":"When did Kate Atkinson begin to write for women's magazines?"},{"t0":139.36,"t1":140.44,"text":"Question 10."},{"t0":140.44,"t1":156.38,"text":"What do Kate Atkinson's books touch on?"},{"t0":156.38,"t1":157.58,"text":"Question 11."},{"t0":157.58,"t1":176.0,"text":"What do we learn about the clever and deceitful characters in a comedy of manners?"}],"questions":[{"no":9,"type":"细节/推断题","prompt":"When did Kate Atkinson begin to write for women's magazines?","options":[{"label":"A","text":"When she started teaching at Edinburgh University in Scotland."},{"label":"B","text":"While she was doing her doctoral studies on American Literature."},{"label":"C","text":"After publishing her first novel Behind the Scenes at the Museum."},{"label":"D","text":"After winning the 1986 Woman's Own Short Story Competition."}],"answer":"D","evidence":"1986短篇比赛获奖后","explanation":"此题考查从何时开始凯特·阿特金森开始为女性杂志撰稿。文章开头部分提到,1986年,她在“女性自己的短篇小说比赛”中获奖之后开始为女性杂志写文章。选项D与录音相符,故为答案。10. What did Kate Atkinson's books touch on?此题考查凯特·阿特金森的作品涉及哪些方面的内容。文章中间部分提到,无论阿特金森以何种体裁写作,她的作品都涉及爱与失去,以及如何继续下去的主题,选项A是对录音的同义转述,故为答案。11. What do we learn about the clever and deceitful characters in a comedy of manners?此题考查对于风俗喜剧中聪明而又狡诈的人物的了解。文章介绍了阿特金森的文章风格被称为风俗喜剧,并在结尾处指出了风俗喜剧往往会奖励那些聪明而又狡诈的人物,而不是惩罚他们的恶行。选项C与录音相符,故为答案。"},{"no":10,"type":"细节/推断题","prompt":"What do Kate Atkinson's books touch on?","options":[{"label":"A","text":"The themes of love and loss."},{"label":"B","text":"The code of human behavior."},{"label":"C","text":"The sins and flaws of eccentrics."},{"label":"D","text":"The manners of fashionable circles."}],"answer":"A","evidence":"爱与失去","explanation":"答案 A。录音核心依据：爱与失去。"},{"no":11,"type":"细节/推断题","prompt":"What do we learn about the clever and deceitful characters in a comedy of manners?","options":[{"label":"A","text":"They are usually ignorant of complex human relations."},{"label":"B","text":"They successfully imitate the manners of celebrities."},{"label":"C","text":"They often get rewarded instead of being punished."},{"label":"D","text":"They are generally looked down upon in society."}],"answer":"C","evidence":"狡黠人物获奖励","explanation":"答案 C。录音核心依据：狡黠人物获奖励。"}],"printedTranscript":"Kate Atkinson was born in York, England in 1951. She worked hard to gain her credentials as\nan author. She studied English Literature at a university in Scotland. After graduating in 1974, she\nresearched a doctorate on American Literature. Later, she taught at the university she graduated from,\nand began writing short stories in 1981. [9] She began writing for women's magazines after winning the\n1986 Woman's Own Short Story Competition.\nHer first novel, Behind the Scenes at the Museum, won the 1995 UK Book of the Year award. The\nbook is set in Yorkshire and has been adapted for radio, theater, and TV. She has written two plays for a\ntheater in Edinburgh—the first was called Nice and the second Abandonment, performed as part of the\nEdinburgh Festival in August 2000.\n[10] Whatever genre Atkinson writes in, her books touch on the themes of love and loss and how to\ncarry on. They are always presented with ingenuity and a wicked sense of humor. Her books tend to be\npopulated by odd, sometimes sinful, and generally flawed eccentrics who become credible by virtue of\nbeing so fully realized. Her books have frequently been described as comedies of manners. That is to say,\ncomedies that represent the complex and sophisticated code of behavior current in fashionable circles of\nsociety, where appearances count more than true moral character. [11] A comedy of manners tends to\nreward its clever and deceitful characters, rather than punish their bad deeds. The humor of a comedy of\nmanners relies on verbal wit and playful teasing."},{"id":"2023-12-1-s4","section":"Section B","title":"Passage 2 · 职场适应力 (Q12–15)","qRange":[12,15],"audio":"audio/listening/202312_s4.mp3","durationSec":196.0,"segments":[{"t0":0.19,"t1":1.55,"text":"Passage 2."},{"t0":1.55,"t1":6.83,"text":"Why is adaptability an important skill to exercise in the workplace?"},{"t0":6.83,"t1":12.31,"text":"Simply put, adaptability is a skill employers are increasingly looking for."},{"t0":12.31,"t1":17.99,"text":"When you spend time learning a new task rather than resisting it, your productivity goes up."},{"t0":17.99,"t1":23.65,"text":"You can also serve as an example to your co-workers who may be having trouble adapting and can"},{"t0":23.65,"t1":26.63,"text":"help lead your team forward."},{"t0":26.63,"t1":30.27,"text":"Strategy consultant Dorrie Clark explains it to us this way."},{"t0":30.27,"t1":35.95,"text":"I'd say that adaptability is an important skill in the workplace because, frankly,"},{"t0":36.95,"t1":42.43,"text":"competitors introduce new products, the economy might enter a recession, customer preferences"},{"t0":42.43,"t1":44.95,"text":"differ over time, and more."},{"t0":44.95,"t1":49.15,"text":"If you shake your fist at the sky and say why can't it stay the same, that's not going"},{"t0":49.15,"t1":50.87,"text":"to do very much good."},{"t0":50.87,"t1":56.55,"text":"Instead, you need to recognise when circumstances have changed so you can take appropriate action"},{"t0":56.55,"t1":60.63,"text":"based on what is rather than how you wish the world would be."},{"t0":60.63,"t1":65.91,"text":"That enables you to make more accurate, informed and effective choices."},{"t0":65.91,"t1":68.99,"text":"So the workplace itself has been evolving."},{"t0":68.99,"t1":74.07,"text":"Today's work culture and management style is often based on teamwork rather than a rigid"},{"t0":74.07,"t1":75.43,"text":"hierarchy."},{"t0":75.43,"t1":81.47,"text":"Brainstorming which requires creativity, flexibility and emotional intelligence is a typical problem"},{"t0":81.47,"t1":83.83,"text":"solving technique."},{"t0":83.83,"t1":88.55,"text":"Employees who are unable or unwilling to participate will not easily move forward"},{"t0":88.55,"t1":90.91,"text":"in the company."},{"t0":90.91,"t1":94.31,"text":"Employees who are flexible demonstrate other skills too."},{"t0":94.31,"t1":100.07,"text":"They can reprioritise quickly when changes occur and suggest additional modifications when"},{"t0":100.07,"t1":102.15,"text":"something's not working."},{"t0":102.15,"t1":108.07,"text":"They can also regroup quickly when a setback occurs, adapting to the new situation confidently"},{"t0":108.07,"t1":111.39,"text":"and without overreacting."},{"t0":111.39,"t1":116.31,"text":"Questions 12 to 15 are based on the passage you have just heard."},{"t0":116.31,"t1":117.47,"text":"Question 12."},{"t0":117.47,"t1":122.87,"text":"Why does the speaker say adaptability is an important skill to exercise in the"},{"t0":122.87,"t1":136.64,"text":"workplace?"},{"t0":137.08,"t1":138.72,"text":"Question 13."},{"t0":138.72,"t1":157.98,"text":"What does adaptability enable us to do, according to strategy consultant Dory Clark?"},{"t0":157.98,"t1":159.42,"text":"Question 14."},{"t0":159.42,"t1":176.77,"text":"What do we learn about today's work culture from the passage?"},{"t0":176.77,"t1":178.17,"text":"Question 15."},{"t0":178.17,"t1":196.0,"text":"What are employees with adaptability able to do when changes occur?"}],"questions":[{"no":12,"type":"细节/推断题","prompt":"Why does the speaker say adaptability is an important skill to exercise in the workplace?","options":[{"label":"A","text":"It is what members use to alleviate tension in a team."},{"label":"B","text":"It is what employers are increasingly seeking after."},{"label":"C","text":"It is conducive to getting over a recession."},{"label":"D","text":"It is necessary for learning a new task."}],"answer":"B","evidence":"雇主越来越看重","explanation":"答案 B。录音核心依据：雇主越来越看重。"},{"no":13,"type":"细节/推断题","prompt":"What does adaptability enable us to do, according to strategy consultant Dory Clark?","options":[{"label":"A","text":"Make better choices."},{"label":"B","text":"Follow innovative ideas."},{"label":"C","text":"Achieve recognition duly."},{"label":"D","text":"Accumulate work experience."}],"answer":"A","evidence":"更明智有效选择","explanation":"答案 A。录音核心依据：更明智有效选择。"},{"no":14,"type":"细节/推断题","prompt":"What do we learn about today's work culture from the passage?","options":[{"label":"A","text":"Workers show more emotional intelligence."},{"label":"B","text":"Workers use brains more than muscles."},{"label":"C","text":"People usually work flexible hours."},{"label":"D","text":"People often work in teams."}],"answer":"D","evidence":"团队协作","explanation":"答案 D。录音核心依据：团队协作。"},{"no":15,"type":"细节/推断题","prompt":"What are employees with adaptability able to do when changes occur?","options":[{"label":"A","text":","},{"label":"B","text":","},{"label":"C","text":"and"},{"label":"D","text":". Then mark the corresponding letter on Answer Sheet 1 with a single line through the center."}],"answer":"C","evidence":"快速调整优先次序","explanation":"答案 C。录音核心依据：快速调整优先次序。"}],"printedTranscript":"Why is adaptability an important skill to exercise in the workplace? Simply put, [12] adaptability\nis a skill employers are increasingly looking for. When you spend time learning a new task rather than\nresisting it, your productivity goes up. You can also serve as an example to your co-workers who may\nbe having trouble adapting, and can help lead your team forward. [13] Strategy consultant, Dorie\nClark, explains it to us this way, “I'd say that adaptability is an important skill in the workplace because,\nfrankly, circumstances change—competitors introduce new products, the economy might enter a\nrecession, customer preferences differ over time, and more. If you shake your fist at the sky and say,\n'Why can't it stay the same?', that's not going to do very much good. Instead, you need to recognize when\ncircumstances have changed, so you can take appropriate action based on what is, rather than how you\nwish the world would be. [13] That enables you to make more accurate, informed and effective choices.”\nAlso, the workplace itself has been evolving. [14] Today's work culture and management style\nis often based on teamwork, rather than a rigid hierarchy. Brainstorming, which requires creativity,\nflexibility, and emotional intelligence, is a typical problem-solving technique. Employees who are unable\nor unwilling to participate will not easily move forward in the company. Employees who are flexible\ndemonstrate other skills, too. [15] They can reprioritize quickly when changes occur and suggest\nadditional modifications when something is not working. They can also regroup quickly when a setback\noccurs, adapting to the new situation confidently and without overreacting.\n12. Why does the speaker say adaptability is an important skill to exercise in the workplace?\n此题考查为什么适应能力是人们在职场中要锻炼的一项重要技能。短文开头提到,适应能力\n是雇主越来越追求的一项技能。选项B是对录音的同义转述,故为答案。\nB\n13. What does adaptability enable us to do according to strategy consultant Dorie Clark?\n此题考查在战略咨询师多里·克拉克看来,适应能力使我们能够做什么。短文提到适应能力\n能让我们根据实际情况采取适当的行动,做出更准确、更明智和更有效的选择。选项A与录音相\n符,故为答案。\nA\n14. What do we learn about today's work culture from the passage?\n此题考查从文章当中我们可以知道哪些如今的工作文化方面的内容。从录音中我们听到,如\n今的工作文化和管理方式往往基于团队合作,而不是过于严格的等级制度。选项D是对录音的同义\n转述,故为答案。\nD\n15. What are employees with adaptability able to do when changes occur?\n此题考查当变化发生时,有适应能力的员工能够做到什么。短文中提到,灵活的员工能在变\n化发生时迅速调整优先次序,并在某些事情行不通时提出额外的调整建议。选项C是对录音的同义\n转述,故为答案。\nC"},{"id":"2023-12-1-s5","section":"Section C","title":"Recording 1 · 人类创新能力 (Q16–18)","qRange":[16,18],"audio":"audio/listening/202312_s5.mp3","durationSec":240.0,"segments":[{"t0":0.0,"t1":0.57,"text":"through the centre."},{"t0":0.57,"t1":2.29,"text":"Recording 1."},{"t0":2.29,"t1":5.81,"text":"What makes humans different from other species?"},{"t0":5.81,"t1":9.37,"text":"Some philosophers argue its morals or ethics."},{"t0":9.37,"t1":13.93,"text":"While some scientists assert it's our greater cognitive development."},{"t0":13.93,"t1":19.01,"text":"But I argue that the main difference is our desire to combat routine."},{"t0":19.01,"t1":25.01,"text":"This makes being creative a biological mandate, as what we seek in art and technology is"},{"t0":25.01,"t1":30.01,"text":"surprise, not simply a fulfilment of expectations."},{"t0":30.01,"t1":35.69,"text":"As a result, a wild imagination has characterised the history of our species."},{"t0":35.69,"t1":42.21,"text":"We build intricate habitats, devise complex recipes for our food, wear clothes that reflect"},{"t0":42.21,"t1":49.29,"text":"constant changes in fashion, communicate with elaborate signs, symbols and sounds, and travel"},{"t0":49.29,"t1":54.29,"text":"between habitats on wings and wheels of our own design."},{"t0":54.29,"t1":58.81,"text":"To satisfy our appetite for novelty, innovation is key."},{"t0":58.81,"t1":60.93,"text":"But who innovates?"},{"t0":60.93,"t1":67.53,"text":"Now many people, both laymen and experts, believe that only geniuses innovate."},{"t0":67.53,"t1":72.21,"text":"But I believe that innovation is not something that only a few people do."},{"t0":72.21,"t1":77.13,"text":"The innovative drive lives in every human brain, and the resulting war against the"},{"t0":77.13,"t1":82.17,"text":"repetitive is what powers the massive changes that distinguish one generation from the"},{"t0":82.17,"t1":83.57,"text":"next."},{"t0":83.57,"t1":87.81,"text":"The drive to create the new is a trait of being human."},{"t0":87.81,"t1":92.53,"text":"We build cultures by the hundreds and tell new stories by the millions."},{"t0":92.53,"t1":98.17,"text":"We create and surround ourselves with things that have never existed before, while animals"},{"t0":98.17,"t1":100.01,"text":"do not."},{"t0":100.01,"t1":102.97,"text":"But where do our new ideas come from?"},{"t0":102.97,"t1":108.73,"text":"According to many, new ideas come from seemingly nowhere, to great minds."},{"t0":108.73,"t1":112.77,"text":"From this perspective, new ideas are almost like magic."},{"t0":112.77,"t1":116.61,"text":"They come in a flash of inspiration to a select few."},{"t0":116.73,"t1":123.69,"text":"However, the reality is that, across the spectrum of human activities, prior work propels the"},{"t0":123.69,"t1":125.73,"text":"creative process."},{"t0":125.73,"t1":131.37,"text":"We may think of innovation as being the result of inspiration or genius, but it's really"},{"t0":131.37,"t1":135.73,"text":"the result of developing the ideas of others further."},{"t0":135.73,"t1":141.69,"text":"This happens in technology where one invention enables or inspires further inventions,"},{"t0":141.69,"t1":148.25,"text":"and it happens in the arts, as writers, composers, and painters use the work of previous artists"},{"t0":148.25,"t1":150.37,"text":"in their own work."},{"t0":150.37,"t1":153.25,"text":"The human brain works from precedent."},{"t0":153.25,"t1":158.09,"text":"We take the ideas we've inherited and put them together into some new shape."},{"t0":158.09,"t1":160.21,"text":"What is a true creator?"},{"t0":160.21,"t1":163.89,"text":"Is a creator a genius who makes something out of nothing?"},{"t0":163.89,"t1":170.17,"text":"No, creators are simply humans who use what they inherit, who absorb the past and"},{"t0":170.17,"t1":173.29,"text":"manipulate it to create possible futures."},{"t0":173.29,"t1":178.69,"text":"Thus, humans are creators as a rule, rather than as an exception."},{"t0":179.69,"t1":184.57,"text":"Questions 16 to 18 are based on the recording you have just heard."},{"t0":184.57,"t1":186.37,"text":"Questions 16."},{"t0":186.37,"t1":202.98,"text":"What question does the speaker address in this talk?"},{"t0":202.98,"t1":204.58,"text":"Questions 17."},{"t0":204.58,"t1":221.49,"text":"What does the speaker believe about innovation?"},{"t0":221.49,"t1":222.69,"text":"Question 18."},{"t0":222.69,"t1":240.0,"text":"How does the human brain work according to the speaker?"}],"questions":[{"no":16,"type":"细节/推断题","prompt":"What question does the speaker address in this talk?","options":[{"label":"A","text":"What differentiates people from animals."},{"label":"B","text":"Why philosophers disagree with scientists."},{"label":"C","text":"Where humans' great cognitive capacity originates."},{"label":"D","text":"When being creative becomes a biological mandate."}],"answer":"A","evidence":"人类与其他物种区别","explanation":"答案 A。录音核心依据：人类与其他物种区别。"},{"no":17,"type":"细节/推断题","prompt":"What does the speaker believe about innovation?","options":[{"label":"A","text":"It is what tells apart two adjacent generations."},{"label":"B","text":"It is what sharpens our appetite for novelty."},{"label":"C","text":"It is something only geniuses can achieve."},{"label":"D","text":"It is something every human being can do."}],"answer":"D","evidence":"创新人人可做","explanation":"答案 D。录音核心依据：创新人人可做。"},{"no":18,"type":"细节/推断题","prompt":"How does the human brain work according to the speaker?","options":[{"label":"A","text":"It seeks inspiration for novel inventions."},{"label":"B","text":"It constantly absorbs new information."},{"label":"C","text":"It uses existing ideas to create new ones."},{"label":"D","text":"It repeats precedent on a regular basis."}],"answer":"C","evidence":"组合既有想法","explanation":"答案 C。录音核心依据：组合既有想法。"}],"printedTranscript":"[16] What makes humans different from other species? Some philosophers argue it's morals or\nethics, while some scientists assert it's our greater cognitive development. But I argue that the main\ndifference is our desire to combat routine. This makes being creative a biological mandate, as what we\nseek in art and technology is surprise, not simply a fulfillment of expectations.\nAs a result, a wild imagination has characterized the history of our species. We build intricate\nhabitats, devise complex recipes for our food, wear clothes that reflect constant changes in fashion,\ncommunicate with elaborate signs, symbols and sounds, and travel between habitats on wings and wheels\nof our own design. To satisfy our appetite for novelty, innovation is key. But who innovates?\nNow, many people, both laymen and experts, believe that only geniuses innovate. [17] But I believe\nthat innovation is not something that only a few people do. The innovative drive lives in every human\nbrain, and the resulting war against the repetitive is what powers the massive changes that distinguish\none generation from the next. The drive to create the new is a trait of being human. We build cultures by\nthe hundreds and tell new stories by the millions. We create and surround ourselves with things that have\nnever existed before, while animals do not. But where do our new ideas come from?\nAccording to many, new ideas come from seemingly nowhere to great minds. From this perspective,\nnew ideas are almost like magic. They come in a flash of inspiration to a select few. However, the reality\nis that, across the spectrum of human activities, prior work propels the creative process. We may think of\ninnovation as being the result of inspiration or genius, but it's really the result of developing the ideas of\nothers further. This happens in technology, where one invention enables or inspires further inventions.\nAnd it happens in the arts, as writers, composers, and painters use the work of previous artists in their\nown work. [18] The human brain works from precedent. We take the ideas we've inherited and put them\ntogether into some new shape.\nWhat is a true creator? Is a creator a genius who makes something out of nothing? No. Creators\nare simply humans who use what they inherit, who absorb the past and manipulate it to create possible\nfutures. Thus, humans are creators as a rule rather than as an exception.\n16. What question does the speaker address in this talk?\n此题考查演讲者在这篇讲座中强调了什么问题。讲座开头提到了“是什么让人类与其他物种\n不同”这个问题,接着围绕这个问题展开分析。选项A是对录音的同义转述,故为答案。\nA\n17. What does the speaker believe about innovation?\n此题考查说话人对创新有何看法。讲座中提到许多人都认为只有天才才能创新,但说话人相\n信创新不是只有少数人才能做到的事情。选项D与录音相符,故为答案。\nD\n18. How does the human brain work according to the speaker?\n此题考查在说话人看来,人类的大脑是如何工作的。说话人提到,人类的大脑是根据先例运\n作的。我们把继承下来的想法组合在一起,形成新的形态。由此可知,选项C是对录音的同义转\n述,故为答案。\nC"},{"id":"2023-12-1-s6","section":"Section C","title":"Recording 2 · 狗感知主人状态 (Q19–21)","qRange":[19,21],"audio":"audio/listening/202312_s6.mp3","durationSec":223.5,"segments":[{"t0":0.18,"t1":1.82,"text":"Recording 2."},{"t0":1.82,"t1":7.18,"text":"Many dog owners will tell you that their dog somehow knows when they're ill or upset,"},{"t0":7.18,"t1":13.58,"text":"and according to researchers who study dog cognition, those pet owners are right."},{"t0":13.58,"t1":17.78,"text":"Dogs do know when their human companions are having a rough time."},{"t0":17.78,"t1":22.3,"text":"Not only can your dog sense when you have a cold, but domestic dogs have shown an"},{"t0":22.3,"t1":28.26,"text":"aptitude for detecting both much smaller mood fluctuations and far more serious physical"},{"t0":28.26,"t1":29.58,"text":"conditions."},{"t0":29.58,"t1":33.9,"text":"This is because dogs are extremely sensitive to changes in the people they're familiar"},{"t0":33.9,"t1":37.02,"text":"with, and illness causes change."},{"t0":37.02,"t1":43.7,"text":"If a person is infected with a virus or bacteria, for example, their odor will be abnormal,"},{"t0":43.7,"t1":48.58,"text":"and dogs are able to smell that change even if the human can't, because dogs have"},{"t0":48.58,"t1":52.02,"text":"a much more powerful sense of smell than humans."},{"t0":52.02,"t1":57.18,"text":"Researchers have also found that a person's mood, which can be an indicator of a larger"},{"t0":57.18,"t1":60.58,"text":"illness, triggers a dog's sense of smell."},{"t0":60.58,"t1":65.94,"text":"Human emotions manifest physically in chemical signals that are emitted by the body, and"},{"t0":65.94,"t1":69.18,"text":"dogs are able to smell those as well."},{"t0":69.18,"t1":75.26,"text":"Beyond smell, dogs gather information from a person's voice in order to sense changes."},{"t0":75.26,"t1":81.26,"text":"In 2014, researchers discovered that dogs have an area of the brain similar to one"},{"t0":81.26,"t1":87.74,"text":"in humans that allows them to understand emotional cues in the tone of a speaker's voice, beyond"},{"t0":87.74,"t1":91.46,"text":"what they'd be able to pick up from familiar words alone."},{"t0":91.46,"t1":95.34,"text":"A person's voice can also carry indicators of illness."},{"t0":95.34,"t1":101.7,"text":"What's not understood quite so well is what dogs understand about these changes."},{"t0":101.7,"t1":106.9,"text":"Humans send out lots of cues, but whether dogs know some of these cues mean illness"},{"t0":106.9,"t1":108.42,"text":"isn't clear."},{"t0":108.42,"t1":114.46,"text":"What we perceive as concern on a dog's part might be more like increased curiosity or suspicion"},{"t0":114.46,"t1":119.98,"text":"that something is wrong with us, and sticking close by is a great way to gather more information"},{"t0":119.98,"t1":122.02,"text":"about the situation."},{"t0":122.02,"t1":127.7,"text":"Some researchers assert dogs will one day help doctors diagnose diseases, as some dogs"},{"t0":127.7,"t1":134.3,"text":"have already demonstrated the ability to detect an assortment of ailments, including diabetes"},{"t0":134.3,"t1":136.54,"text":"and certain types of cancer."},{"t0":136.54,"t1":140.62,"text":"But those researchers can see that's probably in the distant future."},{"t0":140.62,"t1":147.22,"text":"For now, research suggests dog ownership can have an array of benefits in and of itself."},{"t0":147.22,"t1":151.74,"text":"Keeping a pet dog has been shown to bolster health and boost mood."},{"t0":151.74,"t1":156.1,"text":"Dogs also help people relax, and they can be a particular comfort to those with chronic"},{"t0":156.1,"t1":158.46,"text":"diseases."},{"t0":158.46,"t1":163.82,"text":"Questions 19 to 21 are based on the recording you have just heard."},{"t0":163.82,"t1":184.86,"text":"Question 19, What view of many dog owners wins support from researchers studying dog cognition?"},{"t0":184.86,"t1":203.86,"text":"Question 20, Why can dogs detect their owner's abnormal odor according to the speaker?"},{"t0":203.86,"t1":223.5,"text":"Question 21, What does research suggest for now about dog ownership?"}],"questions":[{"no":19,"type":"细节/推断题","prompt":"What view of many dog owners wins support from researchers studying dog cognition?","options":[{"label":"A","text":"Dogs know when their owners are not feeling well."},{"label":"B","text":"Dogs have the cognition for telling right from wrong."},{"label":"C","text":"Dogs have an aptitude for developing skills to interact with humans."},{"label":"D","text":"Dogs know when their human companions can no longer stand them."}],"answer":"A","evidence":"狗察觉主人不适","explanation":"答案 A。录音核心依据：狗察觉主人不适。"},{"no":20,"type":"细节/推断题","prompt":"Why can dogs detect their owner's abnormal odor according to the speaker?","options":[{"label":"A","text":"They can readily detect different ill smells of viruses."},{"label":"B","text":"They can easily tell what bacteria cause odor change."},{"label":"C","text":"They are particularly sensitive to strange smells."},{"label":"D","text":"They have an extremely powerful sense of smell."}],"answer":"D","evidence":"嗅觉更强","explanation":"答案 D。录音核心依据：嗅觉更强。"},{"no":21,"type":"细节/推断题","prompt":"What does research suggest for now about dog ownership?","options":[{"label":"A","text":"It can ensure owners suffer fewer chronic diseases."},{"label":"B","text":"It can benefit owners both physically and mentally."},{"label":"C","text":"It can reduce owners' risk of getting cancer or diabetes."},{"label":"D","text":"It can alert owners to the seriousness of their conditions."}],"answer":"B","evidence":"身心受益","explanation":"答案 B。录音核心依据：身心受益。"}],"printedTranscript":"[19] Many dog owners would tell you that their dog somehow knows when they're ill or upset. And\naccording to researchers who study dog cognition, those pet owners are right. Dogs do know when their\nhuman companions are having a rough time. Not only can your dog sense when you have a cold, but\ndomestic dogs have shown an aptitude for detecting both much smaller mood fluctuations and far more\nserious physical conditions. This is because dogs are extremely sensitive to changes in the people they're\nfamiliar with, and illness causes change. [20] If a person is inflected with a virus or bacteria, for example,\ntheir odor will be abnormal. And dogs are able to smell that change even if the human can't, because dogs\nhave a much more powerful sense of smell than humans.\nResearchers have also found that a person's mood, which can be an indicator of a larger illness,\ntriggers a dog's sense of smell. Human emotions manifest physically in chemical signals that are emitted\nby the body, and dogs are able to smell those as well. Beyond smell, dogs gather information from a\nperson's voice in order to sense changes.\nIn 2014, researchers discovered that dogs have an area of the brain similar to one in humans that\nallows them to understand emotional cues in the tone of a speaker's voice, beyond what they'd be able\nto pick up from familiar words alone. A person's voice can also carry indicators of illness. What's not\nunderstood quite so well is what dogs understand about these changes. Humans send out lots of cues, but\nwhether dogs know some of these cues mean illness isn't clear. What we perceive as concern on a dog's\npart might be more like increased curiosity or suspicion that something is wrong with us, and sticking\nclose by is a great way to gather more information about the situation.\nSome researchers assert dogs will one day help doctors diagnose diseases, as some dogs have\nalready demonstrated the ability to detect an assortment of ailments, including diabetes and certain types\nof cancer. But those researchers concede that's probably in the distant future. [21] For now, research\nsuggests dog ownership can have an array of benefits in and of itself. Keeping a pet dog has been shown\nto bolster health and boost mood. Dogs also help people relax, and they can be a particular comfort to\nthose with chronic diseases.\n19. What view of many dog owners wins support from researchers studying dog cognition?\n此题考查许多狗主人的哪种观点得到了研究狗认知的研究人员的支持。讲话中提到,许多养\n狗人士会告诉你,当他们生病或心烦意乱时,他们的狗就会知道,而且根据研究狗认知的研究人员\n的说法,这些宠物主人的感觉是对的。选项A与录音相符,故为答案。\nA\n20. Why can dogs detect their owner's abnormal odor according to the speaker?\n此题考查为什么狗能察觉到主人的异常气味。讲话中提到,如果一个人感染了病毒或细菌,\n他们的气味就会有异常,即使人类不能,狗也能闻出这种气味的变化,因为狗的嗅觉比人类强大得\n多。选项D与录音相符,故为答案。\nD\n21. What does research suggest for now about dog ownership?\n此题考查关于养狗,目前的研究有何发现。讲话中提到,目前有研究表明养狗本身就有很多\n好处,包括可以促进健康和改善情绪。选项B与录音相符,故为答案。\nB"},{"id":"2023-12-1-s7","section":"Section C","title":"Recording 3 · 艺术学位与收入 (Q22–25)","qRange":[22,25],"audio":"audio/listening/202312_s7.mp3","durationSec":248.3,"segments":[{"t0":0.27,"t1":4.35,"text":"Recording 3 Earlier this month, the think tank called"},{"t0":4.35,"t1":10.31,"text":"Onward published a report, a question of degree, which argues that degrees and the creative"},{"t0":10.31,"t1":13.75,"text":"arts are not good value for money."},{"t0":13.75,"t1":19.39,"text":"Ministers, according to Onward, should crack down on courses that offer extremely limited"},{"t0":19.39,"t1":25.43,"text":"value for money to students 10 years after graduation, restricting the ability of such"},{"t0":25.43,"t1":31.31,"text":"courses to recruit new students if the average graduate earns below the student loan's"},{"t0":31.31,"t1":33.71,"text":"payment threshold."},{"t0":33.71,"t1":38.91,"text":"Studies like science, technology, engineering and math, and economics, where the average"},{"t0":38.91,"t1":41.91,"text":"graduate earns a lot, should be favored."},{"t0":41.91,"t1":47.31,"text":"The report provides insight into a government review, which looks at how to reform technical"},{"t0":47.31,"t1":52.43,"text":"education and how to ensure students get good value for money."},{"t0":52.43,"t1":57.03,"text":"At first glance, it might even seem like Onward have a point."},{"t0":57.03,"t1":62.31,"text":"According to their data, the majority of creative arts students earn less than 25,000"},{"t0":62.31,"t1":65.91,"text":"pounds a year, 10 years after graduation."},{"t0":65.91,"t1":71.59,"text":"The average male creative arts students, indeed, apparently earn much less than they would"},{"t0":71.59,"t1":74.73,"text":"had they simply never gone to university."},{"t0":74.73,"t1":79.33,"text":"This isn't really good for anyone, and it's certainly no good for graduates who are"},{"t0":79.33,"t1":84.43,"text":"forced to endure a lifestyle where they can never save up, never buy a house, never"},{"t0":84.43,"t1":86.39,"text":"hope to retire."},{"t0":86.39,"t1":89.75,"text":"Onward have identified a real problem."},{"t0":89.75,"t1":94.69,"text":"Creative arts graduates from top universities like Oxford, with a high proportion of privately"},{"t0":94.69,"t1":101.71,"text":"educated students, have fairly good work prospects, while 40% of all graduates, regardless"},{"t0":101.71,"t1":108.75,"text":"of their degree, are on less than 25,000 pounds a year, five years after graduation."},{"t0":108.75,"t1":113.27,"text":"This suggests that the problem isn't really to do with specific students studying"},{"t0":113.27,"t1":118.27,"text":"specific degrees, but really with the economy as a whole."},{"t0":118.27,"t1":122.47,"text":"Regardless of what they've studied, young people find it hard to get ahead, unless they're"},{"t0":122.47,"t1":126.31,"text":"lucky enough to be born with successful parents."},{"t0":126.31,"t1":131.07,"text":"If ministers want to make education pay for young people, they need to look beyond the"},{"t0":131.07,"t1":135.31,"text":"higher education sector, towards the wider world."},{"t0":135.31,"t1":138.79,"text":"The rewards that education gives us are not measurable."},{"t0":138.79,"t1":144.11,"text":"They are not always instantly obvious, and certainly not always direct."},{"t0":144.11,"t1":147.87,"text":"An education makes you a different person from the one you would have been if you"},{"t0":147.95,"t1":149.55,"text":"hadn't received it."},{"t0":149.55,"t1":154.27,"text":"We need to look at the value of education, not in the context of a bank balance, but of"},{"t0":154.27,"t1":155.51,"text":"a life."},{"t0":155.51,"t1":160.87,"text":"If we continue to allow ourselves to be distracted with talk of value for money, we will all"},{"t0":160.87,"t1":164.83,"text":"be made poorer as a result."},{"t0":164.83,"t1":170.23,"text":"Questions 22 to 25 are based on the recording you have just heard."},{"t0":170.23,"t1":171.71,"text":"Question 22."},{"t0":171.71,"t1":188.4,"text":"What does Onward's report propose ministers should do?"},{"t0":188.4,"t1":189.96,"text":"Question 23."},{"t0":189.96,"t1":206.28,"text":"What does the speaker think of Onward's arguments?"},{"t0":206.28,"t1":207.76,"text":"Question 24."},{"t0":207.76,"t1":226.14,"text":"What do we learn about British college graduates five years after graduation?"},{"t0":226.14,"t1":227.62,"text":"Question 25."},{"t0":227.62,"t1":245.96,"text":"What does the speaker say actually accounts for the problem identified by Onward?"},{"t0":245.96,"t1":248.12,"text":"That's the end of listening comprehension."}],"questions":[{"no":22,"type":"细节/推断题","prompt":"What does Onward's report propose ministers should do?","options":[{"label":"A","text":"Crack down on courses like science, technology, engineering and math."},{"label":"B","text":"Restrict the ability of creative arts courses to recruit new students."},{"label":"C","text":"Look at how to reform technical and vocational education."},{"label":"D","text":"Ensure creative arts students get better value for money."}],"answer":"B","evidence":"限制创意艺术课程招生","explanation":"答案 B。录音核心依据：限制创意艺术课程招生。"},{"no":23,"type":"细节/推断题","prompt":"What does the speaker think of Onward's arguments?","options":[{"label":"A","text":"Seemingly reasonable."},{"label":"B","text":"Clearly well-grounded."},{"label":"C","text":"Extremely irrational."},{"label":"D","text":"Apparently simplistic."}],"answer":"A","evidence":"表面合理","explanation":"答案 A。录音核心依据：表面合理。"},{"no":24,"type":"细节/推断题","prompt":"What do we learn about British college graduates five years after graduation?","options":[{"label":"A","text":"A high proportion of them haven't tried to save money."},{"label":"B","text":"Most of them never hope to buy a house or to retire."},{"label":"C","text":"Forty percent of them earn less than £25,000 a year."},{"label":"D","text":"The majority of them have fairly well-paying jobs."}],"answer":"C","evidence":"40%五年后年薪低于25000英镑","explanation":"答案 C。录音核心依据：40%五年后年薪低于25000英镑。"},{"no":25,"type":"细节/推断题","prompt":"What does the speaker say actually accounts for the problem identified by Onward?","options":[{"label":"A","text":"The context of a bank balance."},{"label":"B","text":"Britain's economy as a whole."},{"label":"C","text":"The specific degree a student earns."},{"label":"D","text":"Britain's defective educational system."}],"answer":"B","evidence":"整体经济","explanation":"答案 B。录音核心依据：整体经济。"}],"printedTranscript":"Earlier this month, the think-tank called Onward published a report, “A Question of Degree”,\nwhich argues that degrees in the creative arts are not good value for money. [22] Ministers, according\nto Onward, should “crack down on courses that offer extremely limited value for money to students\nten years after graduation”, restricting the ability of such courses to recruit new students, if the average\ngraduate earns below the student loans payment threshold. Courses like science, technology, engineering,\nand math, and economics, where the average graduate earns a lot, should be favored.\nThe report provides insights into a government review which looks at how to reform technical\neducation and how to ensure students get good value for money. [23] At first glance, it might even seem\nlike Onward have a point. According to their data, the majority of creative arts students earn less than\n£25,000 a year ten years after graduation. The average male creative arts students, indeed, apparently earn\nmuch less than they would, had they simply never gone to university. This isn't really good for anyone,\nand it's certainly no good for graduates who are forced to endure a lifestyle where they can never save up,\nnever buy a house, never hope to retire.\nOnward have identified a real problem. Creative arts graduates from top universities like Oxford,\nwith a high proportion of privately-educated students, have fairly good work prospects, [24] while\n40 percent of all graduates, regardless of their degree, are on less than £25,000 a year five years after\ngraduation. [25] This suggests that the problem isn't really to do with specific students studying specific\ndegrees, but really with the economy as a whole. Regardless of what they've studied, young people find it\nhard to get ahead unless they're lucky enough to be born with successful parents.\nIf ministers want to make education pay for young people, they need to look beyond the higher\neducation sector, towards the wider world. The rewards that education gives us are not measurable. They\nare not always instantly obvious, and certainly not always direct. An education makes you a different\nperson from the one you would have been if you hadn't received it. We need to look at the value of\neducation not in the context of a bank balance, but of a life. If we continue to allow ourselves to be\ndistracted with talk of “value for money”, we will all be made poorer as a result.\n22. What does Onward's report propose ministers should do?\n此题考查Onward的报告建议部长们应该做什么。讲座开头提到,Onward认为部长们应该\n“严厉打击那些为毕业10年后的学生提供的性价比极其有限的课程的行为”,如果毕业生的平均\n收入低于学生贷款支付门槛,就应该限制这类课程招收新生。由此可知,Onward认为创意艺术\n专业给学生提供的课程性价比极其有限,应该限制创意艺术课程招收新生,选项B与录音相符,\n故为答案。\nB\n23. What does the speaker think of Onward's arguments?\n此题考查讲话者如何看待 Onward 的观点。讲话中提到,“乍一看,Onward的观点似乎有道\n理”,故选项A为正确答案。其余三个选项在讲话中并未提及,可以排除。\nA\n24. What do we learn about British college graduates five years after graduation?\n此题考查我们对毕业5年后的英国大学毕业生有何了解。讲话中提到,40%的毕业生——无论\n获得什么样的学位——毕业5年后的年薪还不到2.5万英镑。选项C与录音相符,故为答案。\nC\n25. What does the speaker say actually accounts for the problem identified by Onward?\n此题考查在说话人看来,Onward 发现的问题究竟是什么原因造成的。说话人在录音后半部\n分提到,问题并不真正在于那些攻读特定学位的学生,而在于整个经济。选项B与录音相符,故为\n答案。\nB"}]},{"id":"2020-12-1","title":"2020年12月 六级第1套（全25题精听）","year":"2020.12","exam":"六级 CET-6","totalQuestions":25,"audioMode":"sliced","sections":[{"id":"2020-12-1-s1","section":"Section A","title":"Conversation 1 · 保险索赔纠纷 (Q1–4)","qRange":[1,4],"audio":"audio/listening/202012_s1.mp3","durationSec":189.0,"segments":[{"t0":0.0,"t1":1.0,"text":"Then mark the corresponding letter on answer sheet 1 with a single line through the centre."},{"t0":1.0,"t1":9.0,"text":"Conversation 1. Good morning. Safe house insurance. My name is Paul. How can I help you today?"},{"t0":9.0,"t1":21.0,"text":"Morning. I wouldn't say that it's good from where I am standing. This is Miss Wilson, and this is the third time I've called this week, since receiving your letter about our insurance claim."},{"t0":21.0,"t1":27.0,"text":"I'm getting a little fed up with my calls about my claim being completely disregarded."},{"t0":27.0,"t1":34.0,"text":"Miss Wilson, thank you for calling back. Can I take some details to help me look at your claim?"},{"t0":34.0,"t1":44.0,"text":"It's Miss May Wilson of 15 South C Road in Cornwall, and the details are that our village was extensively flooded two months ago."},{"t0":44.0,"t1":52.0,"text":"The entire ground floor of our cottage was submerged in water, and five of us have been living in a caravan ever since."},{"t0":52.0,"t1":60.0,"text":"You people are still withholding the money we are entitled to over a bizarre technical detail, and it's not acceptable, Paul."},{"t0":60.0,"t1":73.0,"text":"Miss Wilson, according to the notes on your account, the bizarre technical detail that you mentioned refers to the fact that you hadn't paid house insurance the month before the incident."},{"t0":73.0,"t1":84.0,"text":"That money left our account, and now that you should be paying out, you are suddenly saying that you didn't receive it on time. I'm really skeptical about this claim."},{"t0":84.0,"t1":94.0,"text":"The contract does say that any missed payment in a year will affect the terms and conditions of the insurance contract, and may affect claims."},{"t0":94.0,"t1":99.0,"text":"Of course, I can pass you on to my manager to talk to you more about this."},{"t0":99.0,"t1":110.0,"text":"I've already spoken to him, and you can tell him I'm furious now, and that your company has a lawsuit on its hands. You will be hearing from my lawyer. Goodbye."},{"t0":110.0,"t1":115.0,"text":"Questions one to four are based on the conversation you have just heard."},{"t0":115.0,"t1":119.0,"text":"Question one, what is the woman complaining about?"},{"t0":119.0,"t1":137.54,"text":"Question two, what is the problem the woman's family encountered?"},{"t0":137.54,"t1":158.08,"text":"Question three, what has caused the so-called bizarre technical detail, according to the man?"},{"t0":158.08,"t1":189.0,"text":"Question four, what does the woman say she will do at the end of the conversation?"}],"questions":[{"no":1,"type":"细节/推断题","prompt":"Question 1（请对照听稿录音）","options":[{"label":"A","text":"Her house has not been repaired in time."},{"label":"B","text":"She has failed to reach the manager again."},{"label":"C","text":"Her claim has been completely disregarded."},{"label":"D","text":"She has not received any letter from the man."}],"answer":"C","evidence":"索赔被忽视","explanation":"答案 C。录音核心依据：索赔被忽视。"},{"no":2,"type":"细节/推断题","prompt":"Whatistheproblemthewoman'sfamilyencountered? (女士一家遇到了什么问题?)","options":[{"label":"A","text":"The ground floor of their cottage was flooded."},{"label":"B","text":"Their caravan was washed away by the flood."},{"label":"C","text":"Their entire house was destroyed by the flood."},{"label":"D","text":"The roof of their cottage collapsed in the flood."}],"answer":"A","evidence":"底层房屋被洪水淹没","explanation":"答案 A。录音核心依据：底层房屋被洪水淹没。"},{"no":3,"type":"细节/推断题","prompt":"Whathascausedtheso-called“bizarretechnicaldetail”accordingtotheman? (据男士称,是什么导致","options":[{"label":"A","text":"The woman's misreading of the insurance company's letter."},{"label":"B","text":"The woman's ignorance of the insurance company's policy."},{"label":"C","text":"The woman's inaccurate description of the whole incident."},{"label":"D","text":"The woman's failure to pay her house insurance in time."}],"answer":"D","evidence":"事前一个月未缴保险费","explanation":"答案 D。录音核心依据：事前一个月未缴保险费。"},{"no":4,"type":"细节/推断题","prompt":"Whatdoesthewomansayshewoulddoattheendoftheconversation? (谈话最后,女士声称自己要做什么?)","options":[{"label":"A","text":"File a lawsuit against the insurance company."},{"label":"B","text":"Talk to the manager of Safe House Insurance."},{"label":"C","text":"Consult her lawyer about the insurance policy."},{"label":"D","text":"Revise the terms and conditions of the contract. Questions5to8arebasedontheconversationyouhavejustheard."}],"answer":"A","evidence":"将提起诉讼","explanation":"女士声称“你们公司有官司要打了。你们会收到我的律师函”,故A正确。"}]},{"id":"2020-12-1-s2","section":"Section A","title":"Conversation 2 · AI 前景与工作 (Q5–8)","qRange":[5,8],"audio":"audio/listening/202012_s2.mp3","durationSec":188.0,"segments":[{"t0":0.0,"t1":0.43,"text":"Question four, what does the woman say she will do at the end of the conversation?"},{"t0":0.43,"t1":9.43,"text":"Conversation two, how do you feel about the future of artificial intelligence? Personally, I feel quite optimistic about it."},{"t0":9.43,"t1":16.43,"text":"AI? I'm not so optimistic, actually. In fact, it's something we should be concerned about."},{"t0":16.43,"t1":25.43,"text":"Well, it will help us humans understand ourselves better, and when we have a better understanding of ourselves, we can improve the world."},{"t0":25.43,"t1":35.43,"text":"Well, one thing is for sure, technology is evolving faster than our ability to understand it, and in the future AI will make jobs kind of pointless."},{"t0":35.43,"t1":45.43,"text":"I think artificial intelligence will actually help create new kinds of jobs, which would require less of our time, and allow us to be centered on creative tasks."},{"t0":45.43,"t1":55.43,"text":"I doubt that very much. Probably the last job that will remain will be writing AI software, and then eventually AI will just write its own software."},{"t0":55.43,"t1":65.43,"text":"At that time we are going to have a lot of jobs which nobody will want to do, so we'll need artificial intelligence for the robots to take care of the old guys like us."},{"t0":65.43,"t1":72.43,"text":"I don't know. There's a risk that human civilization could be replaced by a superior type of digital life."},{"t0":72.43,"t1":81.43,"text":"AI will be able to completely simulate a person in every way possible. In fact, some people think we're in a simulation right now."},{"t0":81.43,"t1":91.43,"text":"That's impossible. Humans can't even make a mosquito. Computers only have chips. People have brains, and that's where the wisdom comes from."},{"t0":91.43,"t1":100.43,"text":"Once it's fully developed, AI will become tired of trying to communicate with humans as we would be much slower thinkers in comparison."},{"t0":100.43,"t1":106.43,"text":"I'm not so sure. A computer is a computer, and a computer is just a toy."},{"t0":106.43,"t1":116.43,"text":"Computers can easily communicate incredibly fast, so the computer will just get impatient talking to humans. It'll be barely getting any information out."},{"t0":116.43,"t1":124.43,"text":"Well, I believe there's a benevolent future with AI. I also think you watch too many science fiction films."},{"t0":124.43,"t1":128.43,"text":"Questions 5-8 are based on the conversation you have just heard."},{"t0":128.43,"t1":147.04,"text":"Question 5. What do we learn about the speakers from the conversation?"},{"t0":147.04,"t1":165.64,"text":"Question 6. What will new kinds of jobs be like according to the woman?"},{"t0":165.64,"t1":183.35,"text":"Question 7. What is the risk the man anticipates?"},{"t0":183.35,"t1":188.0,"text":"Question 8. What is the man's concern about AI technology?"}],"questions":[{"no":5,"type":"细节/推断题","prompt":"Whatdowelearnaboutthespeakersfromtheconversation? (根据对话,我们可了解到对话人的什么信息?)","options":[{"label":"A","text":"They work in different fields of AI technology."},{"label":"B","text":"They disagree about the future of AI technology."},{"label":"C","text":"They differ greatly in their knowledge of modern technology."},{"label":"D","text":"They are both worried about the negative impact of technology."}],"answer":"B","evidence":"对AI前景看法不同","explanation":"答案 B。录音核心依据：对AI前景看法不同。"},{"no":6,"type":"细节/推断题","prompt":"Whatwillnewkindsofjobsbelike,accordingtothewoman? (根据女士所说,新型工作是怎样的?)","options":[{"label":"A","text":"Simply writing AI software."},{"label":"B","text":"Stimulating and motivating."},{"label":"C","text":"Less time⁃consuming and focusing on creation."},{"label":"D","text":"More demanding and requiring special training."}],"answer":"C","evidence":"更少时间、更多创造","explanation":"答案 C。录音核心依据：更少时间、更多创造。"},{"no":7,"type":"细节/推断题","prompt":"Whatistheriskthemananticipates? (男士预见了怎样的风险?)","options":[{"label":"A","text":"There could be jobs nobody wants to do."},{"label":"B","text":"Digital life could replace human civilization."},{"label":"C","text":"Humans would be tired of communicating with one another."},{"label":"D","text":"Old people would be taken care of solely by unfeeling robots."}],"answer":"B","evidence":"数字生命替代文明","explanation":"答案 B。录音核心依据：数字生命替代文明。"},{"no":8,"type":"细节/推断题","prompt":"Whatistheman'sconcernaboutAItechnology? (男士对AI技术有怎样的担心?)","options":[{"label":"A","text":"Life will become like a science fiction film."},{"label":"B","text":","},{"label":"C","text":"andD).ThenmarkthecorrespondingletteronAnswerSheet1withasingleline throughthecentre. Questions9to11arebasedonthepassageyouhavejustheard."},{"label":"D","text":"It will be smarter than human beings. SectionB orfourquestions.Boththepassageandthequestionswillbespokenonlyonce.Afteryou hearaquestion,youmustchoosethebestanswerfromthefourchoicesmarkedA),"}],"answer":"D","evidence":"AI思考比人快","explanation":"D是对男士的担忧“AI发展成熟后,人类的思考速度会比计算机的思考速度慢很多”的合理推断。"}]},{"id":"2020-12-1-s3","section":"Section B","title":"Passage 1 · 储蓄与财务安全 (Q9–11)","qRange":[9,11],"audio":"audio/listening/202012_s3.mp3","durationSec":156.0,"segments":[{"t0":0.86,"t1":10.86,"text":"Passage 1. To achieve financial security, how much you save is always more important than the amount you earn or how shrewdly you invest."},{"t0":10.86,"t1":18.86,"text":"If you're under 30 years old, your goal should be to save 20% of your monthly income after tax deductions."},{"t0":18.86,"t1":28.86,"text":"This is irrespective of how much you earn. Approximately 50% should be reserved for essentials like food and accommodation."},{"t0":28.86,"t1":40.86,"text":"The remaining 30% is for recreation and entertainment. But for many young people, it'll be difficult to designate such a large proportion of their income for savings."},{"t0":40.86,"t1":47.86,"text":"If you find it hard to save any money at all, start by cutting all unnecessary spending."},{"t0":47.86,"t1":55.86,"text":"Allocate a tiny amount of 1 or 2% for savings and gradually increase that amount."},{"t0":55.86,"t1":65.86,"text":"Always keep that 20% goal in mind to prevent yourself from becoming complacent. It can be challenging to stick to such a strict plan."},{"t0":65.86,"t1":70.86,"text":"But if you adopt the right mindset, you should be able to make it work for you."},{"t0":70.86,"t1":74.86,"text":"So what should you be doing with the money that you are saving?"},{"t0":74.86,"t1":79.86,"text":"Some must be kept easily accessible in case you need some cash in an emergency."},{"t0":79.86,"t1":86.86,"text":"The largest proportion should be invested in retirement plans, either through your employer or privately."},{"t0":86.86,"t1":91.86,"text":"And you can keep some money for high risk but potentially lucrative investments."},{"t0":91.86,"t1":96.86,"text":"Dividends can be reinvested or used to purchase something you like."},{"t0":96.86,"t1":104.86,"text":"By following this plan, you should hopefully be able to enjoy your life now and still be financially secure in the future."},{"t0":104.86,"t1":109.86,"text":"Questions 9 to 11 are based on the passage you have just heard."},{"t0":109.86,"t1":116.86,"text":"Question 9. What are people under 30 advised to do to achieve financial security?"},{"t0":116.86,"t1":150.27,"text":"Question 10. What should people do if they find it difficult to follow the speaker's advice on their financial plan?"},{"t0":150.27,"t1":156.0,"text":"Question 11. What does the speaker think is important for achieving financial security?"}],"questions":[{"no":9,"type":"细节/推断题","prompt":"Whatarepeopleunder30advisedtodotoachievefinancialsecurity? (为实现财务安全,30岁以下的人","options":[{"label":"A","text":"Restrain themselves from high⁃risk investments."},{"label":"B","text":"Save one⁃fifth of their net monthly income."},{"label":"C","text":"Invest shrewdly in lucrative businesses."},{"label":"D","text":"Try to earn as much money as possible."}],"answer":"B","evidence":"存税后月收入20%","explanation":"答案 B。录音核心依据：存税后月收入20%。"},{"no":10,"type":"细节/推断题","prompt":"Whatshouldpeopledoiftheyfinditdifficulttofollowthespeaker'sadviceontheirfinancialplan? (如","options":[{"label":"A","text":"Start by doing something small."},{"label":"B","text":"Ask a close friend for advice."},{"label":"C","text":"Try to stick to their initial plan."},{"label":"D","text":"Cut 20% of their daily spending."}],"answer":"A","evidence":"从少量储蓄开始","explanation":"答案 A。录音核心依据：从少量储蓄开始。"},{"no":11,"type":"细节/推断题","prompt":"Whatdoesthespeakerthinkisimportantforachievingfinancialsecurity? (讲话者认为什么对于实现","options":[{"label":"A","text":"An optimistic attitude."},{"label":"B","text":"An ambitious plan."},{"label":"C","text":"A proper mindset."},{"label":"D","text":"A keen interest. Questions12to15arebasedonthepassageyouhavejustheard."}],"answer":"C","evidence":"正确心态","explanation":"第一段首句指出,要实现财务安全,存下多少钱很重要。第二段末两句指出,坚持执行严格的储蓄计划可能具有一定挑战性,但如果能树立正确的心态,便能使这一计划起作用,进而实现财务安全的目标。综上,C符合题意。"}]},{"id":"2020-12-1-s4","section":"Section B","title":"Passage 2 · 职场着装与形象 (Q12–15)","qRange":[12,15],"audio":"audio/listening/202012_s4.mp3","durationSec":172.5,"segments":[{"t0":0.27,"t1":23.97,"text":"Passage 2. I work in advertising and I like to keep up with current trends, mainly because I'm aware that we live in an image-obsessed world."},{"t0":23.97,"t1":33.97,"text":"However, when I first started my job, occasionally I'd catch a glimpse of myself in the lifts and find myself thinking that I looked a total mess."},{"t0":33.97,"t1":36.97,"text":"Was I being held back by my choice of clothing?"},{"t0":36.97,"t1":43.97,"text":"The short answer is yes, especially when clients are quick to judge you on your style rather than your work."},{"t0":43.97,"t1":49.97,"text":"But no one can be unique with their outfit every day. I mean, that's why uniforms were invented."},{"t0":49.97,"t1":54.97,"text":"So, here's what I did. I created my own uniform."},{"t0":54.97,"t1":62.97,"text":"To do this, I chose an appropriate outfit. Then I bought multiple items of the same style in different shades."},{"t0":62.97,"t1":70.97,"text":"Now I never worry about what I'm wearing in the morning, even if I do get a bit tired of just wearing the same classic pieces."},{"t0":70.97,"t1":78.97,"text":"Overall, when it comes to work you have to ask yourself, would looking smarter enhance my ability to do my job?"},{"t0":78.97,"t1":87.97,"text":"For some, this question may not be an issue at all, especially if you work remotely and rarely see your colleagues or clients face to face."},{"t0":87.97,"t1":93.97,"text":"But if your job involves interacting with other people, the answer to this is often yes."},{"t0":93.97,"t1":100.97,"text":"So rather than fighting the system, I think we should just do whatever helps us to achieve our goals at work."},{"t0":100.97,"t1":106.97,"text":"If that means playing it safe with your image, then let's face it, it's probably worth it."},{"t0":106.97,"t1":111.97,"text":"Questions 12 to 15 are based on the passage you have just heard."},{"t0":111.97,"t1":116.97,"text":"Question 12. What do we learn about the speaker when she first started her job?"},{"t0":116.97,"t1":135.84,"text":"Question 13. Why were uniforms invented according to the speaker?"},{"t0":135.84,"t1":153.48,"text":"Question 14. What does the speaker say about looking smarter?"},{"t0":153.48,"t1":172.5,"text":"Question 15. What does the speaker advise people to do in an image-obsessed world?"}],"questions":[{"no":12,"type":"细节/推断题","prompt":"Whatdowelearnaboutthespeakerwhenshefirststartedherjob? (我们了解到说话人刚开始工作时","options":[{"label":"A","text":"She was uninterested in advertising."},{"label":"B","text":"She found her outfit inappropriate."},{"label":"C","text":"She was unhappy with fashion trends."},{"label":"D","text":"She often checked herself in a mirror."}],"answer":"B","evidence":"起初着装不合适","explanation":"答案 B。录音核心依据：起初着装不合适。"},{"no":13,"type":"细节/推断题","prompt":"Whywereuniformsinventedaccordingtothespeaker? (说话人认为,制服是为什么而被发明出来的?)","options":[{"label":"A","text":"To save the trouble of choosing a unique outfit every day."},{"label":"B","text":"To meet the expectations of fashion⁃conscious clients."},{"label":"C","text":"To keep up with the current trends."},{"label":"D","text":"To save the expenses on clothing."}],"answer":"A","evidence":"免去每日选不同衣服","explanation":"答案 A。录音核心依据：免去每日选不同衣服。"},{"no":14,"type":"细节/推断题","prompt":"Whatdoesthespeakersayaboutlookingsmarter? (就“拥有更好的形象”,说话人有什么看法?)","options":[{"label":"A","text":"It enhances people's ability to work independently."},{"label":"B","text":"It helps people succeed in whatever they are doing."},{"label":"C","text":"It matters a lot in jobs involving interaction with others."},{"label":"D","text":"It boosts one's confidence when looking for employment."}],"answer":"C","evidence":"与人互动岗位尤为重要","explanation":"答案 C。录音核心依据：与人互动岗位尤为重要。"},{"no":15,"type":"细节/推断题","prompt":"Whatdoesthespeakeradvisepeopletodoinanimage-obsessedworld? (在这个格外看重形象的世界","options":[{"label":"A","text":"Design their own uniform to appear unique."},{"label":"B","text":","},{"label":"C","text":"andD).Thenmarkthe correspondingletteronAnswerSheet1withasinglelinethroughthecentre. Questionsl6to18arebasedontherecordingyouhavejustheard."},{"label":"D","text":"Do whatever is possible to look smart. SectionC questions.Therecordingswillbeplayedonlyonce.Afteryouhearaquestion,youmust choosethebestanswerfromthefourchoicesmarkedA),"}],"answer":"D","evidence":"尽力让形象得体","explanation":"第三段5句明确指出,“我们只需做好一切能帮我们达成工作目标的事情”,6句则进一步说明“如果这意味着要审慎对待个人形象,那么就要去做”,D是对这一观点的总结。"}]},{"id":"2020-12-1-s5","section":"Section C","title":"Recording 1 · 精简消费与家居 (Q16–18)","qRange":[16,18],"audio":"audio/listening/202012_s5.mp3","durationSec":240.5,"segments":[{"t0":0.0,"t1":1.01,"text":"Then mark the corresponding letter and answer sheet 1 with a single line through the centre."},{"t0":1.01,"t1":9.01,"text":"Recording 1. Did you know that Americans have approximately three times the amount of space we had 50 years ago?"},{"t0":9.01,"t1":14.01,"text":"Therefore, you'd think we'd have sufficient room for all of our possessions."},{"t0":14.01,"t1":19.01,"text":"On the contrary, the personal storage business is now a growing industry."},{"t0":19.01,"t1":27.01,"text":"We've got triple the space, but we've become such enthusiastic consumers that we require even more."},{"t0":27.01,"t1":34.01,"text":"This phenomenon has resulted in significant credit card debt, enormous environmental footprints,"},{"t0":34.01,"t1":41.01,"text":"and perhaps not coincidentally, our happiness levels have failed to increase over the same half-century."},{"t0":41.01,"t1":48.01,"text":"I'm here to suggest an alternative that having less might actually be a preferable decision."},{"t0":48.01,"t1":53.01,"text":"Many of us have experienced at some stage the pleasure of possessing less."},{"t0":53.01,"t1":61.01,"text":"I propose that less stuff and less space can not only help you economise but also simplify your life."},{"t0":61.01,"t1":69.01,"text":"I recently started an innovative project to discover some creative solutions that offered me everything I required."},{"t0":69.01,"t1":77.01,"text":"By purchasing an apartment that was 40 square metres instead of 60, I immediately saved $200,000."},{"t0":77.01,"t1":84.01,"text":"Smaller space leads to reduced utility bills and also a smaller carbon footprint."},{"t0":84.01,"t1":93.01,"text":"Because it's designed around an edited collection of possessions, limited to my favourite stuff, I'm really excited to live there."},{"t0":93.01,"t1":95.01,"text":"How can we live more basically?"},{"t0":95.01,"t1":101.01,"text":"Firstly, we must ruthlessly cut the unnecessary objects out of our lives."},{"t0":101.01,"t1":108.01,"text":"To stem consumption, we should think before we buy and ask ourselves, will it truly make me happier?"},{"t0":108.01,"t1":115.01,"text":"Obviously, we should possess some great stuff, but we want belongings that we're going to love for years."},{"t0":115.01,"t1":119.01,"text":"Secondly, we require space efficiency."},{"t0":119.01,"t1":125.01,"text":"We want appliances that are designed for use most of the time, not for occasional use."},{"t0":126.01,"t1":132.01,"text":"Why own a six-burner stove when you rarely use even three burners?"},{"t0":132.01,"t1":136.01,"text":"Finally, we need multifunctional spaces and housewares."},{"t0":136.01,"t1":142.01,"text":"I combined a movable wall with transforming furniture to get more out of my limited space."},{"t0":142.01,"t1":147.01,"text":"Consider my coffee table. It increases in size to accommodate ten."},{"t0":147.01,"t1":151.01,"text":"My office is tucked away, easily hidden."},{"t0":151.01,"t1":154.01,"text":"My bed simply pops out of the wall."},{"t0":154.01,"t1":161.01,"text":"For guests, I can relocate the movable wall and utilise the foldable guest beds I installed."},{"t0":161.01,"t1":168.01,"text":"I'm not saying we should all live in tiny apartments, but consider the benefits of an edited life."},{"t0":168.01,"t1":174.01,"text":"When you return home and walk through your front door, take a moment to ask yourselves,"},{"t0":174.01,"t1":180.01,"text":"could I do with a little live editing? Would that give me more freedom and more time?"},{"t0":180.01,"t1":185.01,"text":"Question 16 to 18 are based on the recording you have just heard."},{"t0":185.01,"t1":192.01,"text":"Question 16. What has prevented Americans' happiness levels from increasing?"},{"t0":192.01,"t1":209.75,"text":"Question 17. What things should we possess, according to the speaker?"},{"t0":209.75,"t1":240.5,"text":"Question 18. What do we learn about the items in the speaker's home?"}],"questions":[{"no":16,"type":"细节/推断题","prompt":"WhathaspreventedAmericans'happinesslevelsfromincreasing? (什么阻碍了美国人幸福水平的提高?)","options":[{"label":"A","text":"Their obsession with consumption."},{"label":"B","text":"Their failure to accumulate wealth."},{"label":"C","text":"The ever⁃increasing costs of housing."},{"label":"D","text":"The deterioration of the environment."}],"answer":"A","evidence":"过度消费","explanation":"答案 A。录音核心依据：过度消费。"},{"no":17,"type":"细节/推断题","prompt":"Whatthingsshouldwepossessaccordingtothespeaker? (据说话人所述,我们应该拥有什么样的物品?)","options":[{"label":"A","text":"Things that are rare to find."},{"label":"B","text":"Things that cost less money."},{"label":"C","text":"Things that boost efficiency."},{"label":"D","text":"Things that we cherish most."}],"answer":"D","evidence":"珍爱多年的东西","explanation":"答案 D。录音核心依据：珍爱多年的东西。"},{"no":18,"type":"细节/推断题","prompt":"Whatdowelearnabouttheitemsinthespeaker'shome? (关于说话人家里的物品,我们了解到什么?)","options":[{"label":"A","text":"They serve multiple purposes."},{"label":"B","text":"They benefit the environment."},{"label":"C","text":"They are mostly durable."},{"label":"D","text":"They are easily disposable. Questions19to21arebasedontherecordingyouhavejustheard."}],"answer":"A","evidence":"多用途家居","explanation":"第六段说话人提出建议三“我们需要多功能家庭用品”,并以家中的可移动墙壁、可变形家具例证,A正确。"}]},{"id":"2020-12-1-s6","section":"Section C","title":"Recording 2 · 诚实名誉与谎报 (Q19–21)","qRange":[19,21],"audio":"audio/listening/202012_s6.mp3","durationSec":211.0,"segments":[{"t0":0.0,"t1":0.46,"text":"Question 18. What do we learn about the items in the speaker's home?"},{"t0":0.46,"t1":11.46,"text":"Recording two. Now, believe it or not, people sometimes lie in order to maintain a good, honest reputation, even if it hurts them to do so."},{"t0":11.46,"t1":18.46,"text":"At least, this is what a team of scientists is suggesting, with evidence to prove it."},{"t0":18.46,"t1":25.46,"text":"Picture this scenario. You often drive for work and can be compensated for up to 400 miles per month."},{"t0":25.46,"t1":33.46,"text":"Most people at your company drive about 300 miles each month, but this month you drove 400 miles."},{"t0":33.46,"t1":37.46,"text":"How many miles do you think you'd claim in your expense report?"},{"t0":37.46,"t1":44.46,"text":"The scientists asked this exact question as part of the study we're discussing today, with surprising results."},{"t0":44.46,"t1":51.46,"text":"They found that 12% of respondents reported the distance they drove as less than the actual figure,"},{"t0":51.46,"t1":55.46,"text":"giving an average answer of 384 miles."},{"t0":55.46,"t1":62.46,"text":"In other words, they lied about the number of miles, even though they would forfeit money they were owed."},{"t0":62.46,"t1":71.46,"text":"The researchers believed this was to seem honest, with the assumption being that others would be suspicious of a high expense claim."},{"t0":71.46,"t1":75.46,"text":"But why would people fabricate numbers to their own detriment?"},{"t0":75.46,"t1":82.46,"text":"The researchers explained that many people care a great deal about their reputation and how they'll be judged by others."},{"t0":82.46,"t1":92.46,"text":"If they care enough, their concern about appearing honest and not losing the respect of others may be greater than their desire to actually be honest."},{"t0":92.46,"t1":98.46,"text":"The researchers assert that the findings suggest that when people obtain very favorable outcomes,"},{"t0":98.46,"t1":108.46,"text":"they anticipate other people's suspicious reactions and prefer lying and appearing honest to telling the truth and appearing as selfish liars."},{"t0":108.46,"t1":111.46,"text":"So why is this research important?"},{"t0":111.46,"t1":119.46,"text":"Well, experts generally agree there are two main types of lie, selfish lies and lies that are meant to benefit others."},{"t0":119.46,"t1":131.46,"text":"The first, as you may predict, is for selfish gain, such as submitting a fraudulent claim to an insurance company while the second involves lying to help others or not offend others,"},{"t0":131.46,"t1":136.46,"text":"for example, telling a friend whose outfit you don't like that they look great."},{"t0":136.46,"t1":143.46,"text":"But the researchers are suggesting a third type of lying, lying to maintain a good reputation."},{"t0":143.46,"t1":152.46,"text":"Now, this hypothesis is new and some skeptics argue that this isn't a whole new category of lie, but the findings seem intuitive to me."},{"t0":152.46,"t1":163.46,"text":"After all, one of the main motivations for lying is to increase our worth in the eyes of others, so it seems highly likely that people will lie to seem honest."},{"t0":163.46,"t1":168.46,"text":"Questions 19 to 21 are based in the recording you have just heard."},{"t0":168.46,"t1":173.46,"text":"Question 19, what did a team of scientists find in their study?"},{"t0":173.46,"t1":192.94,"text":"Question 20, why would people fabricate numbers to their own detriment according to the researchers?"},{"t0":192.94,"t1":211.0,"text":"Question 21, what does the speaker think of the researchers' findings?"}],"questions":[{"no":19,"type":"细节/推断题","prompt":"Whatdidateamofscientistsfindintheirstudy? (科学家团队在他们的研究中发现了什么?)","options":[{"label":"A","text":"All respondents were afraid of making a high expense claim."},{"label":"B","text":"A number of respondents gave an average answer of 400 miles."},{"label":"C","text":"Over 10% of the respondents lied about the distance they drove."},{"label":"D","text":"Most of the respondents got compensated for driving 384 miles."}],"answer":"C","evidence":"12%谎报里程","explanation":"答案 C。录音核心依据：12%谎报里程。"},{"no":20,"type":"细节/推断题","prompt":"Whywouldpeoplefabricatenumberstotheirowndetrimentaccordingtotheresearchers? (根据研究","options":[{"label":"A","text":"They responded to colleagues'suspicion."},{"label":"B","text":"They cared about other people's claims."},{"label":"C","text":"They wanted to protect their reputation."},{"label":"D","text":"They endeavored to actually be honest."}],"answer":"C","evidence":"保护声誉","explanation":"答案 C。录音核心依据：保护声誉。"},{"no":21,"type":"细节/推断题","prompt":"Whatdoesthespeakerthinkoftheresearchers'findings? (讲话人怎样看待研究者的发现?)","options":[{"label":"A","text":"They seem positive."},{"label":"B","text":"They seem intuitive."},{"label":"C","text":"They are illustrative."},{"label":"D","text":"They are conclusive. Questions22to25arebasedontherecordingyouhavejustheard."}],"answer":"B","evidence":"intuitive","explanation":"B中intuitive原词复现录音结尾处说话人的态度“但研究结果对我来说似乎是基于本能”。"}]},{"id":"2020-12-1-s7","section":"Section C","title":"Recording 3 · 年长者与新音乐 (Q22–25)","qRange":[22,25],"audio":"audio/listening/202012_s7.mp3","durationSec":267.5,"segments":[{"t0":0.0,"t1":0.55,"text":"Question 21, what does the speaker think of the researchers' findings?"},{"t0":0.55,"t1":15.22,"text":"Recording 3"},{"t0":15.22,"t1":18.22,"text":"Why do old people dislike new music?"},{"t0":18.22,"t1":27.22,"text":"As I've grown older, I often hear people my age say things like, they just don't make good music like they used to."},{"t0":27.22,"t1":33.22,"text":"Why does this happen? Luckily, psychology can give us some insights into this puzzle."},{"t0":33.22,"t1":45.22,"text":"Musical tastes begin to crystallise as early as age 13 or 14, and by the time we're in our early 20s, these tastes get locked into place pretty firmly."},{"t0":45.22,"t1":52.22,"text":"In fact, studies have found that by the time we turn 33, most of us have stopped listening to new music."},{"t0":52.22,"t1":61.22,"text":"Meanwhile, popular songs released when you're in your early teens are likely to remain quite popular among your age group for the rest of your life."},{"t0":61.22,"t1":70.22,"text":"There could be a biological explanation for this, as there's evidence that the brain's ability to make subtle distinctions between different chords,"},{"t0":70.22,"t1":74.22,"text":"rhythms and melodies deteriorates with age."},{"t0":74.22,"t1":80.22,"text":"So to older people, newer, less familiar songs might all sound the same."},{"t0":80.22,"t1":85.22,"text":"But there may be some simpler reasons for older people's aversion to newer music."},{"t0":85.22,"t1":91.22,"text":"One of the most researched laws of social psychology is something called the mere exposure effect,"},{"t0":91.22,"t1":97.22,"text":"which in essence means that the more we're exposed to something, the more we tend to like it."},{"t0":97.22,"t1":103.22,"text":"This happens with people we know, the advertisements we see, and the songs we listen to."},{"t0":103.22,"t1":110.22,"text":"When you're in your early teens, you probably spend a fair amount of time listening to music or watching music videos."},{"t0":110.22,"t1":115.22,"text":"Your favourite songs and artists become familiar, comforting parts of your routine."},{"t0":115.22,"t1":124.22,"text":"For many people, over 30, job and family obligations increase, so there's less time to spend discovering new music."},{"t0":124.22,"t1":132.22,"text":"Instead, many will simply listen to old, familiar favourites from that period of their lives when they had more free time."},{"t0":132.22,"t1":137.22,"text":"Of course, those teen years weren't necessarily carefree."},{"t0":137.22,"t1":144.22,"text":"They're famously confusing, which is why so many TV shows and movies revolve around high school turmoil."},{"t0":144.22,"t1":152.22,"text":"Psychology research has shown that the emotions that we experience as teens seem more intense than those that come later."},{"t0":152.22,"t1":160.22,"text":"And we also know that intense emotions are associated with stronger memories and preferences."},{"t0":160.22,"t1":167.22,"text":"Both of these might explain why the songs we listen to during this period become so memorable and beloved."},{"t0":167.22,"t1":172.22,"text":"So there's nothing wrong with your parents because they don't like your music."},{"t0":172.22,"t1":176.22,"text":"Rather, it's all part of the natural order of things."},{"t0":177.22,"t1":182.22,"text":"Questions 22 to 25 are based on the recording you have just heard."},{"t0":182.22,"t1":184.22,"text":"Question 22."},{"t0":184.22,"t1":188.22,"text":"What does the speaker mainly discuss in this talk?"},{"t0":188.22,"t1":202.96,"text":"Question 23."},{"t0":202.96,"t1":208.96,"text":"What have studies found about most people by the time they turn 33?"},{"t0":208.96,"t1":223.57,"text":"Question 24."},{"t0":223.57,"t1":242.14,"text":"What do we learn from one of the most researched laws of social psychology?"},{"t0":242.14,"t1":244.14,"text":"Question 25."},{"t0":244.14,"t1":251.14,"text":"What might explain the fact that songs people listen to in their teen years are memorable and beloved?"},{"t0":251.14,"t1":267.5,"text":"That's the end of listening comprehension."}],"questions":[{"no":22,"type":"细节/推断题","prompt":"Whatdoesthespeakermainlydiscussinthistalk? (说话人在这次讲话中主要谈论了什么?)","options":[{"label":"A","text":"Deterioration in the quality of new music."},{"label":"B","text":"Insights into the features of good music."},{"label":"C","text":"Older people's changing musical tastes."},{"label":"D","text":"Older people's aversion to new music."}],"answer":"D","evidence":"年长者反感新音乐","explanation":"答案 D。录音核心依据：年长者反感新音乐。"},{"no":23,"type":"细节/推断题","prompt":"Whathavestudiesfoundaboutmostpeoplebythetimetheyturn33? (关于“大多数人年满33岁时”","options":[{"label":"A","text":"They no longer listen to new music."},{"label":"B","text":"They find all music sounds the same."},{"label":"C","text":"They can make subtle distinctions about music."},{"label":"D","text":"They seldom listen to songs released in their teens."}],"answer":"A","evidence":"33岁多数不听新音乐","explanation":"答案 A。录音核心依据：33岁多数不听新音乐。"},{"no":24,"type":"细节/推断题","prompt":"Whatdowelearnfromoneofthemostresearchedlawsofsocialpsychology? (我们从社会心理学研究","options":[{"label":"A","text":"The more you are exposed to something, the more familiar it'll be to you."},{"label":"B","text":"The more you are exposed to something, the deeper you'll understand it."},{"label":"C","text":"The more you experience something, the longer you'll remember it."},{"label":"D","text":"The more you experience something, the better you'll appreciate it."}],"answer":"D","evidence":"接触越多越喜欢","explanation":"答案 D。录音核心依据：接触越多越喜欢。"},{"no":25,"type":"细节/推断题","prompt":"Whatmightexplainthefactthatsongspeoplelistentointheirteenyearsarememorableandbeloved?","options":[{"label":"A","text":"Teenagers'memories are more lasting."},{"label":"B","text":"Teenagers'emotions are more intense."},{"label":"C","text":"Teenagers are much more sensitive."},{"label":"D","text":"Teenagers are much more sentimental."}],"answer":"B","evidence":"青少年情绪更强烈","explanation":"第八段先指出研究发现“青少年时期的情感极其强烈”,随后指出人所共知的事实———“强烈的情感”与“更深的记忆及更强的偏好”相连。最后提出这两点或许能解释为什么这一时期听的歌会令人难忘。可见B正确,选项是对原文theemotionsthatweexperienceasteensseemmoreintense的同义改写。"}]}]}],"warmups":[{"id":"warmup-01","no":1,"title":"校园找教室","summary":"新生找205教室，对方指路并告知十分钟后上课，还愿意带路。","phrases":["look for寻找","on the second floor在二楼","show you the way带路。"],"script":"On campus. Excuse me. I am looking for room two hundred and five. Is it in this building? Yes, it is on the second floor. Take the stairs and turn left. Thank you. Is the class starting now? No, it starts in ten minutes. You have enough time. Great. I am new here, and I do not know the campus very well. That is all right. I can show you the way. Thank you for your help.","audioClear":"audio/listening/warmup_01_clear.mp3","audioNormal":"audio/listening/warmup_01_normal.mp3"},{"id":"warmup-02","no":2,"title":"图书馆借书","summary":"学生借书，可借两周；没有其他人预约时能在线续借。楼上有安静阅览室，可带水但不带食物。","phrases":["borrow a book借书","renew it online在线续借","a quiet place安静的地方。"],"script":"At the library. Hello. I would like to borrow this book. Do you have your student card? Yes, here it is. How long can I keep the book? You can keep it for two weeks. Can I renew it online? Yes, if nobody else is waiting for it. Thank you. I also need a quiet place to study. The reading room upstairs is usually quiet. Can I take a drink inside? Water is fine, but please do not bring food.","audioClear":"audio/listening/warmup_02_clear.mp3","audioNormal":"audio/listening/warmup_02_normal.mp3"},{"id":"warmup-03","no":3,"title":"小组讨论与兼职","summary":"两人协调小组报告与兼职时间，约两点在图书馆分工，今天做内容、明天查语言。","phrases":["part time job兼职","That works for me我可以","at once一次性。"],"script":"A study plan. Are you free this afternoon? We need to finish our group report. I have a part time job at four, but I am free before then. Shall we meet at the library at two? That works for me. I can write the first part. Could you check the numbers? Of course. Let us finish the main points today and check the language tomorrow. Good idea. We do not have to do everything at once.","audioClear":"audio/listening/warmup_03_clear.mp3","audioNormal":"audio/listening/warmup_03_normal.mp3"},{"id":"warmup-04","no":4,"title":"交通问路","summary":"问去火车站的车：当前线路要换乘12路，街对面的6路可直达，通常约20分钟，高峰期更久。","phrases":["get off下车","across the street街对面","rush hour交通高峰。"],"script":"Getting to the station. Excuse me. Does this bus go to the train station? Yes, but you need to get off at the next stop and change to bus twelve. Is there a direct bus? Yes. Bus six goes straight there. It stops across the street. Thank you. How long does the trip take? About twenty minutes, but it may take longer during rush hour. I see. I will take bus six. Thanks for explaining that.","audioClear":"audio/listening/warmup_04_clear.mp3","audioNormal":"audio/listening/warmup_04_normal.mp3"},{"id":"warmup-05","no":5,"title":"点餐与确认","summary":"点鸡肉三明治与小杯茶，不加奶、三明治去洋葱，价格8美元，在店内用餐。","phrases":["Could I have ...我想要……","leave ... out不放……","take it away打包带走。"],"script":"Ordering lunch. Hello. Could I have a chicken sandwich and a small cup of tea, please? Certainly. Would you like milk in your tea? No, thank you. And could you leave the onions out of the sandwich? Of course. Is that everything? Yes. How much is it? Eight dollars. Will you eat here or take it away? I will eat here. Please take a seat. We will bring your food to the table. Thank you.","audioClear":"audio/listening/warmup_05_clear.mp3","audioNormal":"audio/listening/warmup_05_normal.mp3"},{"id":"warmup-06","no":6,"title":"住宿与解决问题","summary":"住客办理两晚入住，早餐7到10点；晚上发现淋浴故障，前台安排检查，修不好就换房。","phrases":["have a reservation有预订","front desk前台","not working不能正常使用。"],"script":"At the hotel. Hello. I have a reservation for two nights. My name is Alex Lee. Welcome. May I see your passport, please? Certainly. Here it is. What time is breakfast? From seven to ten in the morning. Thank you. Later that evening, Alex calls the front desk. Hello. The shower in my room is not working. I am sorry about that. We will send someone to check it. If we cannot fix it, we will offer you another room.","audioClear":"audio/listening/warmup_06_clear.mp3","audioNormal":"audio/listening/warmup_06_normal.mp3"},{"id":"warmup-07","no":7,"title":"购物退换","summary":"衬衫太小，希望换大码，但同色无货，于是选择退款，原路退回付款卡。","phrases":["exchange it换货","a larger size更大尺码","a refund退款。"],"script":"Returning a shirt. Hello. I bought this shirt yesterday, but it is too small. Could I exchange it for a larger size? Certainly. Do you have the receipt? Yes, here it is. Let me check. I am sorry, we do not have a larger one in this color. Would you like a different color, or would you prefer a refund? I would like a refund, please. No problem. We will return the money to the card you used.","audioClear":"audio/listening/warmup_07_clear.mp3","audioNormal":"audio/listening/warmup_07_normal.mp3"},{"id":"warmup-08","no":8,"title":"听不懂时怎样求助","summary":"办理预约时没听清，主动请对方慢一点重复，确认填写姓名、电话和地址，并询问签名位置。","phrases":["Could you say that again请再说一遍","a little more slowly慢一点","where to sign在哪里签名。"],"script":"Asking for clarification. Hello. I am here for my appointment. Please fill in this form and wait near the window. I am sorry. Could you say that again, a little more slowly? Of course. First, write your name and phone number on this form. Then, take a seat near the window. Thank you. Do I need to write my address as well? Yes, please. All right. Could you show me where to sign? Right here, at the bottom of the page.","audioClear":"audio/listening/warmup_08_clear.mp3","audioNormal":"audio/listening/warmup_08_normal.mp3"}]};
